// Nuvemath — 5-sinf, II qism nazariyasi. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-2';

  // ---------- t1. O‘nli kasrni 10, 100 va 1000 ga ko‘paytirish va bo‘lish ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Vergul sayohatga chiqadi', 'Запятая отправляется в путь', 'The decimal point goes travelling'), p: [
      L('Tasavvur qiling: do‘konda bitta ruchka 2,5 ming so‘m turadi. Sinfdagi 10 nafar o‘quvchi uchun ruchka olmoqchisiz. Qancha pul kerak? Ustun shaklida ko‘paytirishni boshlashga shoshilmang — javobni bir soniyada aytish mumkin: 25 ming so‘m. Buning siri shundaki, 10, 100 va 1000 ga ko‘paytirish yoki bo‘lishda hech qanday raqam o‘zgarmaydi, faqat <b>vergul o‘z o‘rnini almashtiradi</b>.', 'Представьте: в магазине одна ручка стоит 2,5 тысячи сум. Вы хотите купить ручки для 10 учеников класса. Сколько денег нужно? Не спешите умножать столбиком — ответ можно назвать за секунду: 25 тысяч сум. Секрет в том, что при умножении или делении на 10, 100 и 1000 ни одна цифра не меняется, меняет место только <b>запятая</b>.', 'Imagine a pen costs 2.5 thousand sum. You want pens for 10 pupils in your class. How much money do you need? Do not rush to multiply in columns; the answer takes one second: 25 thousand sum. The secret is that multiplying or dividing by 10, 100 and 1000 does not change a single digit — only the <b>decimal point moves</b>.'),
      L('Birinchi qismda biz o‘nli kasrlarni qo‘shish va ayirishni o‘rgangan edik. Endi ular bilan eng tez va eng qulay amalni — xona birliklariga ko‘paytirish va bo‘lishni o‘rganamiz. Bu ko‘nikma o‘lchov birliklarini almashtirishda, pul hisobida va fizikada har kuni kerak bo‘ladi.', 'В первой части мы научились складывать и вычитать десятичные дроби. Теперь освоим самое быстрое и удобное действие — умножение и деление на разрядные единицы. Этот навык каждый день нужен при переводе единиц измерения, при подсчёте денег и в физике.', 'In Part I we learned to add and subtract decimals. Now we master the fastest and most convenient operation of all: multiplying and dividing by powers of ten. You will need this skill every day when converting units, counting money and doing physics.'),
      L('Mavzu oxirida siz 3,25 · 100 ni ham, 7 : 1000 ni ham ustunsiz, qog‘ozsiz, og‘zaki hisoblay olasiz. Boshladik!', 'К концу темы вы сможете вычислить и 3,25 · 100, и 7 : 1000 устно, без столбика и бумаги. Начинаем!', 'By the end of the topic you will be able to work out both 3.25 · 100 and 7 : 1000 in your head, with no columns and no paper. Let us begin!')
    ] },
    { kind: 'def', h: L('O‘nli kasr xonalari', 'Разряды десятичной дроби', 'Decimal place values'), p: [
      L('Eslaylik: <b>o‘nli kasr</b> — maxraji 10, 100, 1000 bo‘lgan kasrning vergul bilan yozilishi. 3,25 soni 3 butun va 25 yuzdan birni bildiradi. Vergulning chap tomonida butun qism, o‘ng tomonida kasr qism turadi.', 'Вспомним: <b>десятичная дробь</b> — запись дроби со знаменателем 10, 100, 1000 через запятую. Число 3,25 означает 3 целых и 25 сотых. Слева от запятой стоит целая часть, справа — дробная.', 'Recall: a <b>decimal</b> is a fraction with denominator 10, 100 or 1000 written with a decimal point. The number 3.25 means 3 units and 25 hundredths. The whole part is on the left of the point, the fractional part on the right.'),
      L('Har bir raqamning o‘z <b>xonasi</b> bor. Vergulning o‘ng tomonidagi birinchi raqam — o‘ndan birlar, ikkinchisi — yuzdan birlar, uchinchisi — mingdan birlar. Chap tomonda esa birlar, o‘nlar, yuzlar. Xonalar ro‘yxatini ko‘rib chiqamiz:', 'У каждой цифры есть свой <b>разряд</b>. Первая цифра справа от запятой — десятые, вторая — сотые, третья — тысячные. Слева стоят единицы, десятки, сотни. Рассмотрим список разрядов:', 'Every digit has its own <b>place</b>. The first digit to the right of the point is tenths, the second hundredths, the third thousandths. To the left come units, tens and hundreds. Here is the list of places:')
    ], list: [
      L('yuzlar · o‘nlar · birlar <b>,</b> o‘ndan birlar · yuzdan birlar · mingdan birlar', 'сотни · десятки · единицы <b>,</b> десятые · сотые · тысячные', 'hundreds · tens · units <b>.</b> tenths · hundredths · thousandths'),
      L('Qo‘shni xonalar o‘zaro 10 marta farq qiladi: 1 birlik = 10 o‘ndan bir = 100 yuzdan bir.', 'Соседние разряды отличаются в 10 раз: 1 единица = 10 десятых = 100 сотых.', 'Neighbouring places differ by a factor of 10: 1 unit = 10 tenths = 100 hundredths.'),
      L('Kasr qism oxiriga nol yozilsa, son o‘zgarmaydi: 2,5 = 2,50 = 2,500.', 'Если в конце дробной части дописать нуль, число не изменится: 2,5 = 2,50 = 2,500.', 'Writing zeros at the end of the fractional part does not change the number: 2.5 = 2.50 = 2.500.')
    ], after: [
      L('Ana shu «qo‘shni xonalar 10 marta farq qiladi» qoidasi bugungi mavzuning kaliti. Sonni 10 ga ko‘paytirsak, har bir raqam bir xona yuqoriga — chapga ko‘chadi. Vergul esa, aksincha, raqamlarga nisbatan o‘ngga surilgandek ko‘rinadi.', 'Правило «соседние разряды отличаются в 10 раз» — ключ к сегодняшней теме. Умножая число на 10, мы переводим каждую цифру на один разряд выше — влево. А запятая по отношению к цифрам как бы сдвигается вправо.', 'That rule, “neighbouring places differ by 10”, is the key to today’s topic. When we multiply by 10, every digit moves one place higher, to the left. Relative to the digits, the point appears to shift to the right.')
    ] },
    { kind: 'history', h: L('Vergul qayerdan kelgan?', 'Откуда взялась запятая?', 'Where did the decimal point come from?'), p: [
      L('O‘nli kasrlarni birinchi bo‘lib tizimli ishlatgan olimlardan biri Samarqandda, Ulug‘bek rasadxonasida ishlagan <b>G‘iyosiddin Jamshid al-Koshiy</b> edi. U 1427-yilda yozgan «Hisob kaliti» (Miftoh al-hisob) kitobida o‘nli kasrlar bilan qanday hisoblashni batafsil tushuntirgan va π sonini 16 ta o‘nli raqamgacha aniq topgan.', 'Одним из первых учёных, системно применявших десятичные дроби, был <b>Гиясиддин Джамшид аль-Каши</b>, работавший в Самарканде, в обсерватории Улугбека. В книге «Ключ арифметики» (Мифтах аль-хисаб), написанной в 1427 году, он подробно объяснил вычисления с десятичными дробями и нашёл число π с точностью до 16 десятичных знаков.', 'One of the first scholars to use decimals systematically was <b>Ghiyath al-Din Jamshid al-Kashi</b>, who worked in Samarkand at Ulugh Beg’s observatory. In his book “The Key to Arithmetic” (Miftah al-Hisab), written in 1427, he explained in detail how to calculate with decimals and found π correct to 16 decimal places.'),
      L('Yevropada o‘nli kasrlarni 1585-yilda flamand matematigi <b>Simon Stevin</b> «O‘ndan bir» (De Thiende) nomli kichik kitobchasida ommalashtirdi. U har bir raqam ustiga doira ichida xona raqamini yozar edi — vergul hali yo‘q edi!', 'В Европе десятичные дроби в 1585 году популяризировал фламандский математик <b>Симон Стевин</b> в небольшой книжке «Десятая» (De Thiende). Над каждой цифрой он писал номер разряда в кружке — запятой ещё не было!', 'In Europe decimals were popularised in 1585 by the Flemish mathematician <b>Simon Stevin</b> in a small book called “The Tenth” (De Thiende). He wrote the place number in a circle above each digit — there was no decimal point yet!'),
      L('Vergul yoki nuqtani ajratuvchi belgi sifatida XVII asr boshida shotland olimi <b>Jon Neper</b> taklif qildi. Shundan beri dunyo ikkiga bo‘lingan: O‘zbekiston, Rossiya, Germaniya va Fransiyada vergul (3,14), Buyuk Britaniya va AQShda nuqta (3.14) ishlatiladi.', 'Запятую или точку как разделитель в начале XVII века предложил шотландский учёный <b>Джон Непер</b>. С тех пор мир разделился: в Узбекистане, России, Германии и Франции пишут запятую (3,14), а в Великобритании и США — точку (3.14).', 'The comma or dot as a separator was proposed in the early 17th century by the Scottish scholar <b>John Napier</b>. Since then the world has been split: Uzbekistan, Russia, Germany and France use a comma (3,14), while Britain and the USA use a point (3.14).')
    ] },
    { kind: 'rule', h: L('Asosiy qoida', 'Основное правило', 'The main rule'), p: [
      L('O‘nli kasrni 10, 100, 1000 ga ko‘paytirish va bo‘lish qoidasi juda sodda:', 'Правило умножения и деления десятичной дроби на 10, 100, 1000 очень простое:', 'The rule for multiplying and dividing a decimal by 10, 100 and 1000 is very simple:')
    ], list: [
      L('<b>10 ga ko‘paytirish</b> — vergulni <b>bir</b> xona <b>o‘ngga</b> suramiz: 3,25 · 10 = 32,5.', '<b>Умножение на 10</b> — переносим запятую на <b>один</b> знак <b>вправо</b>: 3,25 · 10 = 32,5.', '<b>Multiply by 10</b> — move the point <b>one</b> place to the <b>right</b>: 3.25 · 10 = 32.5.'),
      L('<b>100 ga ko‘paytirish</b> — <b>ikki</b> xona o‘ngga: 3,25 · 100 = 325.', '<b>Умножение на 100</b> — на <b>два</b> знака вправо: 3,25 · 100 = 325.', '<b>Multiply by 100</b> — <b>two</b> places right: 3.25 · 100 = 325.'),
      L('<b>1000 ga ko‘paytirish</b> — <b>uch</b> xona o‘ngga: 3,25 · 1000 = 3250 (yetishmagan joyga nol yozamiz).', '<b>Умножение на 1000</b> — на <b>три</b> знака вправо: 3,25 · 1000 = 3250 (недостающие места заполняем нулями).', '<b>Multiply by 1000</b> — <b>three</b> places right: 3.25 · 1000 = 3250 (fill empty places with zeros).'),
      L('<b>10, 100, 1000 ga bo‘lish</b> — vergulni shuncha xona <b>chapga</b> suramiz: 48,6 : 10 = 4,86; 48,6 : 100 = 0,486; 48,6 : 1000 = 0,0486.', '<b>Деление на 10, 100, 1000</b> — переносим запятую на столько же знаков <b>влево</b>: 48,6 : 10 = 4,86; 48,6 : 100 = 0,486; 48,6 : 1000 = 0,0486.', '<b>Divide by 10, 100, 1000</b> — move the point that many places to the <b>left</b>: 48.6 : 10 = 4.86; 48.6 : 100 = 0.486; 48.6 : 1000 = 0.0486.')
    ], after: [
      L('Qisqa qilib: ko‘paytiruvchi yoki bo‘luvchidagi <b>nollar soni</b> — vergul necha xona surilishini aytadi. Ko‘paytirishda son kattalashadi (vergul o‘ngga), bo‘lishda kichiklashadi (vergul chapga).', 'Коротко: <b>число нулей</b> в множителе или делителе показывает, на сколько знаков переносить запятую. При умножении число растёт (запятая вправо), при делении уменьшается (запятая влево).', 'In short: the <b>number of zeros</b> in the multiplier or divisor tells you how many places to move the point. Multiplying makes the number bigger (point right); dividing makes it smaller (point left).'),
      L('Nega shunday? Chunki 10 ga ko‘paytirganda har bir raqam bir xona yuqoriga ko‘tariladi: o‘ndan birlar birlarga, birlar o‘nlarga aylanadi. Raqamlar ketma-ketligi o‘zgarmaydi — demak, faqat vergul «yuradi».', 'Почему так? Потому что при умножении на 10 каждая цифра поднимается на разряд выше: десятые становятся единицами, единицы — десятками. Последовательность цифр не меняется — значит, «ходит» только запятая.', 'Why? Because multiplying by 10 lifts every digit one place higher: tenths become units, units become tens. The sequence of digits does not change, so only the point “walks”.')
    ] },
    { kind: 'steps', h: L('Qadamma-qadam', 'Шаг за шагом', 'Step by step'), p: [
      L('Masalan, 0,07 · 1000 ni hisoblaymiz. Quyidagi tartibda ishlang:', 'Например, вычислим 0,07 · 1000. Действуйте в таком порядке:', 'Let us work out 0.07 · 1000. Follow this order:')
    ], list: [
      L('1-qadam. Amalni aniqlang: ko‘paytirish — vergul <b>o‘ngga</b>, bo‘lish — <b>chapga</b>.', 'Шаг 1. Определите действие: умножение — запятая <b>вправо</b>, деление — <b>влево</b>.', 'Step 1. Identify the operation: multiplying — point <b>right</b>; dividing — <b>left</b>.'),
      L('2-qadam. Nollarni sanang: 1000 da uchta nol — demak, 3 xona.', 'Шаг 2. Сосчитайте нули: в 1000 три нуля — значит, 3 знака.', 'Step 2. Count the zeros: 1000 has three zeros, so 3 places.'),
      L('3-qadam. Vergulni suring: 0,07 → 0,7 → 7, → 70,. Ikki raqam yetdi, uchinchi joyga nol qo‘shdik.', 'Шаг 3. Перенесите запятую: 0,07 → 0,7 → 7, → 70,. Цифр хватило на два шага, на третий добавили нуль.', 'Step 3. Move the point: 0.07 → 0.7 → 7. → 70. Two digits were enough for two steps; we added a zero for the third.'),
      L('4-qadam. Javobni tartibga keltiring: oxiridagi vergulni va boshidagi ortiqcha nollarni olib tashlang: 0,07 · 1000 = <b>70</b>.', 'Шаг 4. Приведите ответ в порядок: уберите запятую в конце и лишние нули в начале: 0,07 · 1000 = <b>70</b>.', 'Step 4. Tidy the answer: drop the trailing point and any leading zeros: 0.07 · 1000 = <b>70</b>.'),
      L('5-qadam. Tekshiring: ko‘paytirdik — son kattalashdi (70 &gt; 0,07). To‘g‘ri!', 'Шаг 5. Проверьте: умножали — число выросло (70 &gt; 0,07). Верно!', 'Step 5. Check: we multiplied, so the number grew (70 &gt; 0.07). Correct!')
    ], after: [
      L('Bo‘lishda chapga surganda raqam yetmasa, oldinga nol yozamiz: 7 : 1000 → 0,007. Butun sonda vergul oxirida turibdi deb hisoblaymiz: 7 = 7,0.', 'Если при делении, двигаясь влево, цифр не хватает, дописываем нули спереди: 7 : 1000 → 0,007. У целого числа запятая стоит в конце: 7 = 7,0.', 'When dividing, if you run out of digits moving left, write zeros in front: 7 : 1000 → 0.007. A whole number has its point at the end: 7 = 7.0.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Avval o‘zingiz hisoblang, keyin yechimni oching.', 'Сначала посчитайте сами, потом откройте решение.', 'Calculate first, then open the solution.')
    ], ex: [
      { q: L('3,25 · 100 = ?', '3,25 · 100 = ?', '3.25 · 100 = ?'), s: L('100 da ikkita nol — vergul ikki xona o‘ngga: 3,25 → 32,5 → 325. Javob: <b>325</b>.', 'В 100 два нуля — запятая на два знака вправо: 3,25 → 32,5 → 325. Ответ: <b>325</b>.', '100 has two zeros, so the point moves two places right: 3.25 → 32.5 → 325. Answer: <b>325</b>.') },
      { q: L('48,6 : 10 = ?', '48,6 : 10 = ?', '48.6 : 10 = ?'), s: L('Bo‘lish — vergul chapga, bitta xona: 48,6 → 4,86. Javob: <b>4,86</b>. Tekshiramiz: 4,86 · 10 = 48,6.', 'Деление — запятая влево на один знак: 48,6 → 4,86. Ответ: <b>4,86</b>. Проверка: 4,86 · 10 = 48,6.', 'Dividing: point one place left: 48.6 → 4.86. Answer: <b>4.86</b>. Check: 4.86 · 10 = 48.6.') },
      { q: L('7 : 1000 = ?', '7 : 1000 = ?', '7 : 1000 = ?'), s: L('7 = 7,0. Uch xona chapga: 0,7 → 0,07 → 0,007. Javob: <b>0,007</b> — yetti mingdan bir.', '7 = 7,0. Три знака влево: 0,7 → 0,07 → 0,007. Ответ: <b>0,007</b> — семь тысячных.', '7 = 7.0. Three places left: 0.7 → 0.07 → 0.007. Answer: <b>0.007</b>, seven thousandths.') },
      { q: L('0,45 · 1000 = ?', '0,45 · 1000 = ?', '0.45 · 1000 = ?'), s: L('Uch xona o‘ngga: 4,5 → 45 → 450. Ikkita raqam bor edi, uchinchi joyga nol qo‘ydik. Javob: <b>450</b>.', 'Три знака вправо: 4,5 → 45 → 450. Цифр было две, на третье место ставим нуль. Ответ: <b>450</b>.', 'Three places right: 4.5 → 45 → 450. There were two digits; the third place gets a zero. Answer: <b>450</b>.') },
      { q: L('Bir metr lenta 1,8 ming so‘m. 100 m lenta qancha turadi?', 'Метр ленты стоит 1,8 тысячи сум. Сколько стоят 100 м?', 'One metre of ribbon costs 1.8 thousand sum. How much do 100 m cost?'), s: L('1,8 · 100 = 180. Javob: <b>180 ming so‘m</b>.', '1,8 · 100 = 180. Ответ: <b>180 тысяч сум</b>.', '1.8 · 100 = 180. Answer: <b>180 thousand sum</b>.') }
    ] },
    { kind: 'table', h: L('Bitta son — oltita natija', 'Одно число — шесть результатов', 'One number, six results'), p: [
      L('6,4 sonini olib, u bilan barcha olti amalni bajaramiz. Vergul qanday «yurishiga» e’tibor bering.', 'Возьмём число 6,4 и выполним с ним все шесть действий. Обратите внимание, как «ходит» запятая.', 'Take the number 6.4 and perform all six operations on it. Watch how the point “walks”.')
    ], table: { head: [L('Amal', 'Действие', 'Operation'), L('Vergul', 'Запятая', 'Point'), L('Natija', 'Результат', 'Result')], rows: [
      [L('6,4 · 10', '6,4 · 10', '6.4 · 10'), L('1 xona o‘ngga', '1 знак вправо', '1 place right'), '64'],
      [L('6,4 · 100', '6,4 · 100', '6.4 · 100'), L('2 xona o‘ngga', '2 знака вправо', '2 places right'), '640'],
      [L('6,4 · 1000', '6,4 · 1000', '6.4 · 1000'), L('3 xona o‘ngga', '3 знака вправо', '3 places right'), '6400'],
      [L('6,4 : 10', '6,4 : 10', '6.4 : 10'), L('1 xona chapga', '1 знак влево', '1 place left'), L('0,64', '0,64', '0.64')],
      [L('6,4 : 100', '6,4 : 100', '6.4 : 100'), L('2 xona chapga', '2 знака влево', '2 places left'), L('0,064', '0,064', '0.064')],
      [L('6,4 : 1000', '6,4 : 1000', '6.4 : 1000'), L('3 xona chapga', '3 знака влево', '3 places left'), L('0,0064', '0,0064', '0.0064')]
    ] }, after: [
      L('Jadvalga qarang: ko‘paytirishda raqamlar «6» va «4» doim joyida, ular orqasiga nollar qo‘shiladi. Bo‘lishda esa oldiga nollar keladi. Raqamlar ketma-ketligi 6-4 hech qachon buzilmaydi.', 'Посмотрите на таблицу: при умножении цифры «6» и «4» всегда на месте, после них добавляются нули. При делении нули появляются спереди. Последовательность 6-4 никогда не нарушается.', 'Look at the table: when multiplying, the digits “6” and “4” stay put and zeros are added after them. When dividing, zeros appear in front. The sequence 6-4 is never broken.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), p: [
      L('Qoida oson, lekin shoshilganda xato qilish ham oson. Quyidagilarga e’tibor bering:', 'Правило простое, но в спешке легко ошибиться. Обратите внимание:', 'The rule is easy, but it is also easy to slip when hurrying. Watch out for these:')
    ], list: [
      L('<b>Yo‘nalishni adashtirish.</b> 2,5 : 10 = 25 — noto‘g‘ri! Bo‘lganda son kichiklashishi kerak: 2,5 : 10 = 0,25.', '<b>Путаница в направлении.</b> 2,5 : 10 = 25 — неверно! При делении число должно уменьшиться: 2,5 : 10 = 0,25.', '<b>Wrong direction.</b> 2.5 : 10 = 25 is wrong! Dividing must make the number smaller: 2.5 : 10 = 0.25.'),
      L('<b>Nolni unutish.</b> 0,4 · 100 = 4 — xato. Ikki xona kerak, bitta raqam bor: 0,4 → 4 → 40. To‘g‘risi: 40.', '<b>Забытый нуль.</b> 0,4 · 100 = 4 — ошибка. Нужно два знака, а цифра одна: 0,4 → 4 → 40. Верно: 40.', '<b>Forgotten zero.</b> 0.4 · 100 = 4 is wrong. Two places are needed but there is one digit: 0.4 → 4 → 40. Correct: 40.'),
      L('<b>Butun sonda vergul «yo‘q» deb o‘ylash.</b> 5 : 100 = 0,5 — xato. 5 = 5,0; ikki xona chapga: 0,05.', '<b>Думать, что у целого числа «нет» запятой.</b> 5 : 100 = 0,5 — ошибка. 5 = 5,0; два знака влево: 0,05.', '<b>Thinking a whole number has “no” point.</b> 5 : 100 = 0.5 is wrong. 5 = 5.0; two places left: 0.05.'),
      L('<b>Nollarni noto‘g‘ri sanash.</b> 1000 — uchta nol, 100 — ikkita. Shoshilib 1000 ga ko‘paytirganda ikki xona surish — keng tarqalgan xato.', '<b>Неверный подсчёт нулей.</b> В 1000 три нуля, в 100 — два. Сдвинуть на два знака при умножении на 1000 — частая ошибка.', '<b>Miscounting zeros.</b> 1000 has three zeros, 100 has two. Moving two places when multiplying by 1000 is a common slip.')
    ], after: [
      L('Eng yaxshi himoya — <b>taxminiy tekshiruv</b>. 3,25 · 100 taxminan 3 · 100 = 300 ga yaqin bo‘lishi kerak. Agar 32,5 chiqsa — bir xona kam surilgan.', 'Лучшая защита — <b>прикидка</b>. 3,25 · 100 должно быть близко к 3 · 100 = 300. Если получилось 32,5 — сдвинули на знак меньше.', 'The best protection is an <b>estimate</b>. 3.25 · 100 should be close to 3 · 100 = 300. If you got 32.5, you moved one place too few.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is this used in life?'), p: [
      L('<b>Pul.</b> O‘zbekistonda narxlar ko‘pincha ming so‘mlarda aytiladi: «12,5 ming» — bu 12,5 · 1000 = 12 500 so‘m. Ming so‘mdan so‘mga o‘tish — bu 1000 ga ko‘paytirish.', '<b>Деньги.</b> В Узбекистане цены часто называют в тысячах сум: «12,5 тысячи» — это 12,5 · 1000 = 12 500 сум. Переход от тысяч к сумам — умножение на 1000.', '<b>Money.</b> In Uzbekistan prices are often quoted in thousands of sum: “12.5 thousand” means 12.5 · 1000 = 12 500 sum. Going from thousands to sum is multiplying by 1000.'),
      L('<b>O‘lchovlar.</b> 1 km = 1000 m, 1 m = 100 cm, 1 kg = 1000 g, 1 l = 1000 ml. 2,3 km masofani metrda ifodalash uchun 2,3 · 1000 = 2300 m. Keyingi mavzuda buni batafsil ko‘ramiz.', '<b>Измерения.</b> 1 км = 1000 м, 1 м = 100 см, 1 кг = 1000 г, 1 л = 1000 мл. Чтобы выразить 2,3 км в метрах: 2,3 · 1000 = 2300 м. В следующей теме разберём это подробно.', '<b>Measurements.</b> 1 km = 1000 m, 1 m = 100 cm, 1 kg = 1000 g, 1 l = 1000 ml. To express 2.3 km in metres: 2.3 · 1000 = 2300 m. We will study this in detail in the next topic.'),
      L('<b>Kompyuter va texnika.</b> Fayl hajmi 1,5 MB bo‘lsa, bu taxminan 1500 KB. Telefon ekrani 6,1 dyuym bo‘lsa, 10 ta telefon yonma-yon 61 dyuym bo‘ladi. Dorixonada 0,5 g dori = 500 mg.', '<b>Компьютер и техника.</b> Файл размером 1,5 МБ — это примерно 1500 КБ. Экран телефона 6,1 дюйма: 10 телефонов рядом — 61 дюйм. В аптеке 0,5 г лекарства = 500 мг.', '<b>Computers and devices.</b> A 1.5 MB file is about 1500 KB. A phone screen of 6.1 inches: 10 phones side by side make 61 inches. At the pharmacy 0.5 g of medicine = 500 mg.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('Yorug‘lik tezligi — sekundiga taxminan 300 000 km. Bu 3 · 100 000, ya’ni 3 ni besh marta 10 ga ko‘paytirgandek. Olimlar shunday katta sonlarni yozishda 10 ning darajalaridan foydalanadi: 3 · 10<sup>5</sup>.', 'Скорость света — около 300 000 км в секунду. Это 3 · 100 000, то есть 3, умноженное на 10 пять раз. Учёные записывают такие большие числа через степени десяти: 3 · 10<sup>5</sup>.', 'The speed of light is about 300 000 km per second. That is 3 · 100 000, or 3 multiplied by 10 five times. Scientists write such big numbers with powers of ten: 3 · 10<sup>5</sup>.'),
      L('Inson sochi qalinligi taxminan 0,07 mm. Mikroskop uni 1000 marta kattalashtirsa, ekranda 0,07 · 1000 = 70 mm, ya’ni 7 cm bo‘lib ko‘rinadi!', 'Толщина человеческого волоса — примерно 0,07 мм. Если микроскоп увеличит его в 1000 раз, на экране он будет 0,07 · 1000 = 70 мм, то есть 7 см!', 'A human hair is about 0.07 mm thick. If a microscope magnifies it 1000 times, it appears 0.07 · 1000 = 70 mm, that is 7 cm, on the screen!'),
      L('Al-Koshiy π ni hisoblaganda 60 lik (Bobil) va 10 lik tizimda natijalarni bir-biriga o‘tkazgan. Uning 3,1415926535897932 natijasi 180 yil davomida dunyodagi eng aniq qiymat bo‘lib qoldi.', 'Вычисляя π, аль-Каши переводил результаты из шестидесятеричной (вавилонской) системы в десятичную. Его значение 3,1415926535897932 оставалось самым точным в мире 180 лет.', 'When computing π, al-Kashi converted his results between the sexagesimal (Babylonian) and decimal systems. His value 3.1415926535897932 remained the most accurate in the world for 180 years.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), p: [
      L('Javob berishdan oldin «ko‘paytirish — kattalashadi, bo‘lish — kichiklashadi» deb o‘zingizga eslating.', 'Перед ответом напомните себе: «умножение — растёт, деление — уменьшается».', 'Before answering, remind yourself: “multiplying grows, dividing shrinks”.')
    ], list: [
      L('12,07 · 10 nimaga teng? Nega javobda hamon vergul bor?', 'Чему равно 12,07 · 10? Почему в ответе всё ещё есть запятая?', 'What is 12.07 · 10? Why is there still a point in the answer?'),
      L('0,003 · 1000 — bu butun sonmi?', '0,003 · 1000 — это целое число?', 'Is 0.003 · 1000 a whole number?'),
      L('Qaysi biri katta: 45 : 100 yoki 4,5 : 10? Nima uchun?', 'Что больше: 45 : 100 или 4,5 : 10? Почему?', 'Which is bigger: 45 : 100 or 4.5 : 10? Why?'),
      L('Sonni 10 ga ko‘paytirib, keyin 100 ga bo‘lsak, u necha marta o‘zgaradi?', 'Если число умножить на 10, а потом разделить на 100, во сколько раз оно изменится?', 'If you multiply a number by 10 and then divide by 100, by what factor does it change?')
    ], after: [
      L('Javoblar: 120,7 (kasr qism 7 qoldi); ha, 3; ular teng — ikkalasi 0,45; 10 marta kichiklashadi, ya’ni 10 ga bo‘lgandek.', 'Ответы: 120,7 (осталась дробная часть 7); да, 3; они равны — оба 0,45; уменьшится в 10 раз, как при делении на 10.', 'Answers: 120.7 (the fractional 7 remains); yes, 3; they are equal, both 0.45; it becomes 10 times smaller, as if divided by 10.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('10, 100, 1000 ga ko‘paytirish va bo‘lishda raqamlar o‘zgarmaydi — faqat <b>vergul suriladi</b>.', 'При умножении и делении на 10, 100, 1000 цифры не меняются — <b>сдвигается только запятая</b>.', 'Multiplying or dividing by 10, 100, 1000 leaves the digits unchanged — only the <b>point moves</b>.'),
      L('Ko‘paytirish — vergul <b>o‘ngga</b>, son kattalashadi.', 'Умножение — запятая <b>вправо</b>, число растёт.', 'Multiplying — point <b>right</b>, the number grows.'),
      L('Bo‘lish — vergul <b>chapga</b>, son kichiklashadi.', 'Деление — запятая <b>влево</b>, число уменьшается.', 'Dividing — point <b>left</b>, the number shrinks.'),
      L('Nollar soni = surish xonalari soni: 10 → 1, 100 → 2, 1000 → 3.', 'Число нулей = число знаков сдвига: 10 → 1, 100 → 2, 1000 → 3.', 'Number of zeros = number of places moved: 10 → 1, 100 → 2, 1000 → 3.'),
      L('Raqam yetmasa — nol qo‘shing: 0,4 · 100 = 40; 7 : 1000 = 0,007.', 'Не хватает цифр — добавьте нули: 0,4 · 100 = 40; 7 : 1000 = 0,007.', 'Out of digits? Add zeros: 0.4 · 100 = 40; 7 : 1000 = 0.007.'),
      L('Har doim taxminiy tekshiruv qiling.', 'Всегда делайте прикидку.', 'Always make a rough check.')
    ] }
  ] });

  // ---------- t2. O‘nlik, yuzlik va mingliklarga ko‘paytirish va bo‘lish ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('300 — bu 3 marta 100', '300 — это 3 раза по 100', '300 is 3 times 100'), p: [
      L('O‘tgan mavzuda vergulni surishni o‘rgandik. Endi savol: 0,4 · 300 ni qanday hisoblaymiz? 300 — bu na 10, na 100, na 1000. Lekin 300 ni ikki qismga ajratish mumkin: 300 = 3 · 100. Demak, avval 0,4 ni 3 ga ko‘paytiramiz (bu oddiy), keyin natijani 100 ga ko‘paytiramiz (vergulni suramiz). Shu bilan masala yechildi!', 'В прошлой теме мы научились переносить запятую. Теперь вопрос: как вычислить 0,4 · 300? 300 — это ни 10, ни 100, ни 1000. Но 300 можно разложить: 300 = 3 · 100. Значит, сначала умножаем 0,4 на 3 (это просто), потом результат умножаем на 100 (переносим запятую). Задача решена!', 'In the last topic we learned to move the point. Now the question: how do we work out 0.4 · 300? 300 is neither 10, nor 100, nor 1000. But 300 can be split: 300 = 3 · 100. So first multiply 0.4 by 3 (easy), then multiply the result by 100 (move the point). Problem solved!'),
      L('Bunday sonlar — 20, 50, 300, 4000 — <b>o‘nliklar, yuzliklar va mingliklar</b> deyiladi: ular oxirida nol bilan tugaydi. Ular bilan ishlash ikki bosqichli: oddiy raqam bilan amal, so‘ng vergulni surish.', 'Такие числа — 20, 50, 300, 4000 — называют <b>десятками, сотнями и тысячами</b>: они оканчиваются нулями. Работа с ними идёт в два шага: действие с простой цифрой, затем перенос запятой.', 'Numbers like 20, 50, 300, 4000 are called <b>tens, hundreds and thousands</b>: they end in zeros. Working with them takes two steps: an operation with a simple digit, then moving the point.'),
      L('Bu usul hayotda juda ko‘p uchraydi: 30 ta g‘isht massasi, 200 km yo‘lga yoqilg‘i, 50 o‘quvchiga daftar. Keling, uni mukammal o‘rganamiz.', 'Этот приём очень часто встречается в жизни: масса 30 кирпичей, топливо на 200 км пути, тетради для 50 учеников. Давайте освоим его в совершенстве.', 'This method comes up constantly in life: the mass of 30 bricks, fuel for 200 km, notebooks for 50 pupils. Let us master it properly.')
    ] },
    { kind: 'def', h: L('Dumaloq sonlar', 'Круглые числа', 'Round numbers'), p: [
      L('<b>Dumaloq son</b> — oxirida bir yoki bir nechta nol bilan tugaydigan natural son: 20, 70, 400, 6000. Har qanday dumaloq sonni <b>raqam · xona birligi</b> ko‘rinishida yozish mumkin:', '<b>Круглое число</b> — натуральное число, оканчивающееся одним или несколькими нулями: 20, 70, 400, 6000. Любое круглое число можно записать в виде <b>цифра · разрядная единица</b>:', 'A <b>round number</b> is a natural number ending in one or more zeros: 20, 70, 400, 6000. Any round number can be written as <b>digit · power of ten</b>:')
    ], list: [
      L('20 = 2 · 10, 70 = 7 · 10 — o‘nliklar;', '20 = 2 · 10, 70 = 7 · 10 — десятки;', '20 = 2 · 10, 70 = 7 · 10 — tens;'),
      L('400 = 4 · 100, 900 = 9 · 100 — yuzliklar;', '400 = 4 · 100, 900 = 9 · 100 — сотни;', '400 = 4 · 100, 900 = 9 · 100 — hundreds;'),
      L('6000 = 6 · 1000, 2000 = 2 · 1000 — mingliklar.', '6000 = 6 · 1000, 2000 = 2 · 1000 — тысячи.', '6000 = 6 · 1000, 2000 = 2 · 1000 — thousands.')
    ], after: [
      L('Bu yerda ko‘paytirishning <b>guruhlash xossasi</b> ishlaydi: (a · b) · c = a · (b · c). Shuning uchun 0,4 · 300 = 0,4 · (3 · 100) = (0,4 · 3) · 100. Ko‘paytuvchilarni istalgan tartibda guruhlash mumkin — natija o‘zgarmaydi.', 'Здесь работает <b>сочетательное свойство</b> умножения: (a · b) · c = a · (b · c). Поэтому 0,4 · 300 = 0,4 · (3 · 100) = (0,4 · 3) · 100. Множители можно группировать в любом порядке — результат не изменится.', 'The <b>associative property</b> of multiplication is at work here: (a · b) · c = a · (b · c). So 0.4 · 300 = 0.4 · (3 · 100) = (0.4 · 3) · 100. Factors can be grouped in any order; the result does not change.'),
      L('Bo‘lishda ham shunday: sonni 30 ga bo‘lish — uni avval 3 ga, keyin 10 ga bo‘lish bilan bir xil (yoki aksincha).', 'С делением так же: разделить число на 30 — то же, что разделить его сначала на 3, а потом на 10 (или наоборот).', 'Division works the same way: dividing by 30 is the same as dividing first by 3 and then by 10 (or the other way round).')
    ] },
    { kind: 'history', h: L('Nol — buyuk ixtiro', 'Нуль — великое изобретение', 'Zero, the great invention'), p: [
      L('Dumaloq sonlar bilan osongina ishlashimizga <b>nol</b> raqami va o‘nlik sanoq tizimi sabab. Nolni alohida raqam sifatida hindistonlik olimlar taxminan V–VII asrlarda qo‘llay boshlagan. Ungacha rimliklar 300 ni CCC deb yozar edi — bunday yozuvda vergul surish haqida gap ham bo‘lishi mumkin emas edi.', 'Легко работать с круглыми числами нам позволяют цифра <b>нуль</b> и десятичная система счисления. Нуль как отдельную цифру индийские учёные начали применять примерно в V–VII веках. До этого римляне писали 300 как CCC — в такой записи ни о каком переносе запятой речи быть не могло.', 'We can handle round numbers so easily thanks to the digit <b>zero</b> and the decimal number system. Indian scholars began using zero as a separate digit around the 5th–7th centuries. Before that the Romans wrote 300 as CCC, and in such notation moving a point was out of the question.'),
      L('Hind raqamlarini va o‘nlik tizimni butun dunyoga tanitgan olim — vatandoshimiz <b>Muhammad ibn Muso al-Xorazmiy</b> (taxminan 783–850). Uning hind hisobi haqidagi kitobi lotin tiliga tarjima qilingach, Yevropa ming yillik rim raqamlaridan voz kechdi. «Algoritm» so‘zi uning nomidan kelib chiqqan.', 'Учёный, познакомивший весь мир с индийскими цифрами и десятичной системой, — наш соотечественник <b>Мухаммад ибн Муса аль-Хорезми</b> (около 783–850). Когда его книгу об индийском счёте перевели на латынь, Европа отказалась от тысячелетних римских цифр. Слово «алгоритм» произошло от его имени.', 'The scholar who introduced Indian numerals and the decimal system to the whole world was our compatriot <b>Muhammad ibn Musa al-Khwarizmi</b> (about 783–850). When his book on Indian reckoning was translated into Latin, Europe abandoned the Roman numerals it had used for a thousand years. The word “algorithm” comes from his name.'),
      L('Xorazmiy usullari tufayli savdogarlar katta sonlarni tez hisoblay boshladilar: 40 ta tuyaga 300 kg dan yuk — 12 000 kg. Bugun biz ham aynan shu yo‘ldan boramiz.', 'Благодаря методам аль-Хорезми купцы стали быстро считать большие числа: 40 верблюдов по 300 кг груза — 12 000 кг. Сегодня мы идём тем же путём.', 'Thanks to al-Khwarizmi’s methods merchants began to calculate large numbers quickly: 40 camels carrying 300 kg each make 12 000 kg. Today we follow the same path.')
    ] },
    { kind: 'rule', h: L('Qoida: ikki bosqich', 'Правило: два шага', 'The rule: two steps'), p: [
      L('O‘nli kasrni dumaloq songa ko‘paytirish yoki bo‘lish uchun dumaloq sonni ajratamiz va amalni ikki bosqichda bajaramiz:', 'Чтобы умножить или разделить десятичную дробь на круглое число, раскладываем круглое число и выполняем действие в два шага:', 'To multiply or divide a decimal by a round number, split the round number and do the operation in two steps:')
    ], list: [
      L('<b>Ko‘paytirish:</b> 0,4 · 300 = (0,4 · 3) · 100 = 1,2 · 100 = <b>120</b>.', '<b>Умножение:</b> 0,4 · 300 = (0,4 · 3) · 100 = 1,2 · 100 = <b>120</b>.', '<b>Multiplying:</b> 0.4 · 300 = (0.4 · 3) · 100 = 1.2 · 100 = <b>120</b>.'),
      L('<b>Bo‘lish:</b> 2,4 : 30 = (2,4 : 3) : 10 = 0,8 : 10 = <b>0,08</b>.', '<b>Деление:</b> 2,4 : 30 = (2,4 : 3) : 10 = 0,8 : 10 = <b>0,08</b>.', '<b>Dividing:</b> 2.4 : 30 = (2.4 : 3) : 10 = 0.8 : 10 = <b>0.08</b>.'),
      L('Bosqichlar tartibi muhim emas: 0,4 · 300 = (0,4 · 100) · 3 = 40 · 3 = 120. Qaysi tartib qulay bo‘lsa, shuni tanlang.', 'Порядок шагов не важен: 0,4 · 300 = (0,4 · 100) · 3 = 40 · 3 = 120. Выбирайте тот порядок, который удобнее.', 'The order of the steps does not matter: 0.4 · 300 = (0.4 · 100) · 3 = 40 · 3 = 120. Choose whichever order is more convenient.')
    ], after: [
      L('Oddiy raqamga ko‘paytirishda esa o‘nli kasrni butun songa ko‘paytirgandek ish tutamiz: raqamlarni ko‘paytiramiz, keyin kasrdagi vergul o‘rniga qarab natijada vergul qo‘yamiz. 0,4 · 3: 4 · 3 = 12, kasr qismda bitta raqam — 1,2.', 'При умножении на простую цифру поступаем как при умножении десятичной дроби на целое число: перемножаем цифры, а потом ставим запятую по числу знаков в дроби. 0,4 · 3: 4 · 3 = 12, в дробной части одна цифра — 1,2.', 'Multiplying by a single digit works like multiplying a decimal by a whole number: multiply the digits, then place the point according to the decimal places. 0.4 · 3: 4 · 3 = 12, one decimal place — 1.2.'),
      L('Bo‘lishda ham: 2,4 : 3 — 24 : 3 = 8, kasr qismda bitta raqam — 0,8.', 'При делении так же: 2,4 : 3 — 24 : 3 = 8, одна цифра в дробной части — 0,8.', 'Dividing likewise: 2.4 : 3 — 24 : 3 = 8, one decimal place — 0.8.')
    ] },
    { kind: 'steps', h: L('Algoritm', 'Алгоритм', 'The algorithm'), p: [
      L('Masalan, 1,5 · 4000 ni hisoblaymiz.', 'Например, вычислим 1,5 · 4000.', 'Let us work out 1.5 · 4000.')
    ], list: [
      L('1-qadam. Dumaloq sonni ajrating: 4000 = 4 · 1000.', 'Шаг 1. Разложите круглое число: 4000 = 4 · 1000.', 'Step 1. Split the round number: 4000 = 4 · 1000.'),
      L('2-qadam. Oddiy raqam bilan amal bajaring: 1,5 · 4 = 6.', 'Шаг 2. Выполните действие с простой цифрой: 1,5 · 4 = 6.', 'Step 2. Do the operation with the single digit: 1.5 · 4 = 6.'),
      L('3-qadam. Vergulni suring: 6 · 1000 = 6000.', 'Шаг 3. Перенесите запятую: 6 · 1000 = 6000.', 'Step 3. Move the point: 6 · 1000 = 6000.'),
      L('4-qadam. Tekshiring: 1,5 · 4000 taxminan 1 · 4000 dan 2 · 4000 gacha, ya’ni 4000 va 8000 orasida. 6000 — mos.', 'Шаг 4. Проверьте: 1,5 · 4000 — между 1 · 4000 и 2 · 4000, то есть от 4000 до 8000. 6000 подходит.', 'Step 4. Check: 1.5 · 4000 lies between 1 · 4000 and 2 · 4000, so between 4000 and 8000. 6000 fits.')
    ], after: [
      L('Bo‘lishda ham xuddi shunday: 9,6 : 400 → 400 = 4 · 100; 9,6 : 4 = 2,4; 2,4 : 100 = 0,024.', 'При делении так же: 9,6 : 400 → 400 = 4 · 100; 9,6 : 4 = 2,4; 2,4 : 100 = 0,024.', 'Dividing is the same: 9.6 : 400 → 400 = 4 · 100; 9.6 : 4 = 2.4; 2.4 : 100 = 0.024.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir namunada ikkala bosqichni aniq ko‘rsatamiz.', 'В каждом примере ясно показываем оба шага.', 'In each example both steps are shown clearly.')
    ], ex: [
      { q: L('0,4 · 300 = ?', '0,4 · 300 = ?', '0.4 · 300 = ?'), s: L('300 = 3 · 100. 0,4 · 3 = 1,2; 1,2 · 100 = 120. Javob: <b>120</b>.', '300 = 3 · 100. 0,4 · 3 = 1,2; 1,2 · 100 = 120. Ответ: <b>120</b>.', '300 = 3 · 100. 0.4 · 3 = 1.2; 1.2 · 100 = 120. Answer: <b>120</b>.') },
      { q: L('2,4 : 30 = ?', '2,4 : 30 = ?', '2.4 : 30 = ?'), s: L('30 = 3 · 10. 2,4 : 3 = 0,8; 0,8 : 10 = 0,08. Javob: <b>0,08</b>. Tekshiramiz: 0,08 · 30 = 2,4.', '30 = 3 · 10. 2,4 : 3 = 0,8; 0,8 : 10 = 0,08. Ответ: <b>0,08</b>. Проверка: 0,08 · 30 = 2,4.', '30 = 3 · 10. 2.4 : 3 = 0.8; 0.8 : 10 = 0.08. Answer: <b>0.08</b>. Check: 0.08 · 30 = 2.4.') },
      { q: L('Bitta g‘isht 2,5 kg. 40 ta g‘ishtning massasi?', 'Один кирпич весит 2,5 кг. Масса 40 кирпичей?', 'One brick weighs 2.5 kg. Mass of 40 bricks?'), s: L('2,5 · 40 = (2,5 · 4) · 10 = 10 · 10 = 100. Javob: <b>100 kg</b>.', '2,5 · 40 = (2,5 · 4) · 10 = 10 · 10 = 100. Ответ: <b>100 кг</b>.', '2.5 · 40 = (2.5 · 4) · 10 = 10 · 10 = 100. Answer: <b>100 kg</b>.') },
      { q: L('7,2 : 800 = ?', '7,2 : 800 = ?', '7.2 : 800 = ?'), s: L('800 = 8 · 100. 7,2 : 8 = 0,9; 0,9 : 100 = 0,009. Javob: <b>0,009</b>.', '800 = 8 · 100. 7,2 : 8 = 0,9; 0,9 : 100 = 0,009. Ответ: <b>0,009</b>.', '800 = 8 · 100. 7.2 : 8 = 0.9; 0.9 : 100 = 0.009. Answer: <b>0.009</b>.') },
      { q: L('Mashina 100 km ga 7,5 l benzin sarflaydi. 600 km ga qancha kerak?', 'Машина расходует 7,5 л бензина на 100 км. Сколько нужно на 600 км?', 'A car uses 7.5 l of petrol per 100 km. How much is needed for 600 km?'), s: L('600 km — bu 6 marta 100 km. 7,5 · 6 = 45. Javob: <b>45 l</b>. (Bu yerda 7,5 · 600 : 100 = 7,5 · 6 ham deyish mumkin.)', '600 км — это 6 раз по 100 км. 7,5 · 6 = 45. Ответ: <b>45 л</b>. (Можно записать и так: 7,5 · 600 : 100 = 7,5 · 6.)', '600 km is 6 lots of 100 km. 7.5 · 6 = 45. Answer: <b>45 l</b>. (One can also write 7.5 · 600 : 100 = 7.5 · 6.)') }
    ] },
    { kind: 'table', h: L('Taqqoslash jadvali', 'Сравнительная таблица', 'Comparison table'), p: [
      L('1,2 sonini turli dumaloq sonlarga ko‘paytiramiz va bo‘lamiz. Ikkinchi ustunda ajratish, uchinchisida natija.', 'Умножим и разделим число 1,2 на разные круглые числа. Во втором столбце — разложение, в третьем — результат.', 'Multiply and divide 1.2 by various round numbers. The second column shows the split, the third the result.')
    ], table: { head: [L('Amal', 'Действие', 'Operation'), L('Ajratish', 'Разложение', 'Split'), L('Natija', 'Результат', 'Result')], rows: [
      [L('1,2 · 20', '1,2 · 20', '1.2 · 20'), L('1,2 · 2 · 10 = 2,4 · 10', '1,2 · 2 · 10 = 2,4 · 10', '1.2 · 2 · 10 = 2.4 · 10'), '24'],
      [L('1,2 · 500', '1,2 · 500', '1.2 · 500'), L('1,2 · 5 · 100 = 6 · 100', '1,2 · 5 · 100 = 6 · 100', '1.2 · 5 · 100 = 6 · 100'), '600'],
      [L('1,2 · 3000', '1,2 · 3000', '1.2 · 3000'), L('1,2 · 3 · 1000 = 3,6 · 1000', '1,2 · 3 · 1000 = 3,6 · 1000', '1.2 · 3 · 1000 = 3.6 · 1000'), '3600'],
      [L('1,2 : 40', '1,2 : 40', '1.2 : 40'), L('1,2 : 4 : 10 = 0,3 : 10', '1,2 : 4 : 10 = 0,3 : 10', '1.2 : 4 : 10 = 0.3 : 10'), L('0,03', '0,03', '0.03')],
      [L('1,2 : 600', '1,2 : 600', '1.2 : 600'), L('1,2 : 6 : 100 = 0,2 : 100', '1,2 : 6 : 100 = 0,2 : 100', '1.2 : 6 : 100 = 0.2 : 100'), L('0,002', '0,002', '0.002')]
    ] }, after: [
      L('E’tibor bering: 1,2 · 500 = 600 — natija butun son chiqdi. Bu tez-tez bo‘ladi: 0,5 · 200 = 100, 2,5 · 40 = 100. Natija butun chiqsa, uni vergulsiz yozamiz.', 'Обратите внимание: 1,2 · 500 = 600 — получилось целое число. Так бывает часто: 0,5 · 200 = 100, 2,5 · 40 = 100. Если результат целый, пишем его без запятой.', 'Notice that 1.2 · 500 = 600 came out as a whole number. This happens often: 0.5 · 200 = 100, 2.5 · 40 = 100. If the result is whole, write it without a point.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Faqat nollarni hisobga olish.</b> 0,4 · 300 = 40 — xato! Uchlikni unutdik: 0,4 · 3 = 1,2, keyin 120.', '<b>Учитывать только нули.</b> 0,4 · 300 = 40 — ошибка! Забыли тройку: 0,4 · 3 = 1,2, затем 120.', '<b>Counting only the zeros.</b> 0.4 · 300 = 40 is wrong! The three was forgotten: 0.4 · 3 = 1.2, then 120.'),
      L('<b>Faqat raqamni hisobga olish.</b> 2,4 : 30 = 0,8 — xato, bu 2,4 : 3. Yana 10 ga bo‘lish kerak: 0,08.', '<b>Учитывать только цифру.</b> 2,4 : 30 = 0,8 — ошибка, это 2,4 : 3. Нужно ещё разделить на 10: 0,08.', '<b>Counting only the digit.</b> 2.4 : 30 = 0.8 is wrong; that is 2.4 : 3. You still need to divide by 10: 0.08.'),
      L('<b>Bo‘lishda yo‘nalish.</b> 2,4 : 30 ni hisoblaganda vergulni o‘ngga surish — xato. Bo‘lganda son kichiklashadi.', '<b>Направление при делении.</b> Сдвигать запятую вправо при вычислении 2,4 : 30 — ошибка. При делении число уменьшается.', '<b>Direction when dividing.</b> Moving the point right for 2.4 : 30 is wrong. Dividing makes the number smaller.'),
      L('<b>Oraliq natijada vergulni yo‘qotish.</b> 0,4 · 3 = 12 deb yozib, keyin 1200 chiqarish. Avval 1,2, keyin 120.', '<b>Потеря запятой в промежуточном результате.</b> Записать 0,4 · 3 = 12 и получить 1200. Сначала 1,2, потом 120.', '<b>Losing the point in the intermediate step.</b> Writing 0.4 · 3 = 12 and getting 1200. First 1.2, then 120.')
    ], after: [
      L('Maslahat: har bir bosqichni alohida satrga yozing. Ko‘z bilan tekshirish oson bo‘ladi: 0,4 · 3 = 1,2 → 1,2 · 100 = 120.', 'Совет: записывайте каждый шаг отдельной строкой. Так легче проверить глазами: 0,4 · 3 = 1,2 → 1,2 · 100 = 120.', 'Tip: write each step on its own line. It is easier to check by eye: 0.4 · 3 = 1.2 → 1.2 · 100 = 120.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in life'), p: [
      L('<b>Qurilish.</b> Bitta sement qopi 50 kg, bitta g‘isht 3,5 kg. 200 ta g‘isht — 3,5 · 200 = 700 kg. Yuk mashinasi 3 tonna ko‘tarsa, nechta g‘isht sig‘adi? 3000 : 3,5 — bu keyingi sinflarda. Lekin 700 kg ni darhol hisoblay olamiz.', '<b>Стройка.</b> Мешок цемента — 50 кг, кирпич — 3,5 кг. 200 кирпичей — 3,5 · 200 = 700 кг. Если грузовик берёт 3 тонны, сколько кирпичей поместится? 3000 : 3,5 — это в старших классах. Но 700 кг мы считаем сразу.', '<b>Building.</b> A bag of cement is 50 kg, a brick 3.5 kg. 200 bricks weigh 3.5 · 200 = 700 kg. If a lorry carries 3 tonnes, how many bricks fit? 3000 : 3.5 is for later grades, but 700 kg we can find at once.'),
      L('<b>Oshxona.</b> Bir porsiya palovga 0,15 kg guruch ketadi. To‘yda 300 porsiya — 0,15 · 300 = 45 kg guruch. Bir kishiga 0,2 l choy — 50 kishiga 10 l.', '<b>Кухня.</b> На одну порцию плова идёт 0,15 кг риса. На свадьбе 300 порций — 0,15 · 300 = 45 кг риса. По 0,2 л чая на человека — на 50 человек 10 л.', '<b>Kitchen.</b> One portion of plov needs 0.15 kg of rice. For a wedding of 300 portions that is 0.15 · 300 = 45 kg of rice. At 0.2 l of tea per person, 50 people need 10 l.'),
      L('<b>Sport.</b> Yuguruvchi 400 metrlik aylanani 1,2 minutda yuguradi. 20 aylana — 24 minut. Suzuvchi 50 m hovuzda 0,5 minutda bir uzunlikni suzadi — 40 uzunlik (2 km) 20 minut.', '<b>Спорт.</b> Бегун пробегает круг 400 м за 1,2 минуты. 20 кругов — 24 минуты. Пловец проплывает 50-метровый бассейн за 0,5 минуты — 40 длин (2 км) за 20 минут.', '<b>Sport.</b> A runner does a 400 m lap in 1.2 minutes. 20 laps take 24 minutes. A swimmer covers a 50 m pool in 0.5 minutes, so 40 lengths (2 km) take 20 minutes.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('Chumoli o‘z massasidan 50 marta og‘ir yukni ko‘tara oladi. Chumoli 0,004 g bo‘lsa, u 0,004 · 50 = 0,2 g ko‘taradi. Odam shunday kuchli bo‘lganda, 60 kg li kishi 3 tonnani ko‘tarardi!', 'Муравей поднимает груз в 50 раз тяжелее себя. Если муравей весит 0,004 г, он поднимает 0,004 · 50 = 0,2 г. Будь человек таким сильным, 60-килограммовый поднимал бы 3 тонны!', 'An ant can lift 50 times its own mass. If an ant weighs 0.004 g, it lifts 0.004 · 50 = 0.2 g. If people were that strong, a 60 kg person would lift 3 tonnes!'),
      L('Yer yuzasidan Oygacha o‘rtacha 384 400 km. Yorug‘lik u yerga 1,3 sekundda yetib boradi. Avtomobil 100 km/soat tezlikda to‘xtamasdan yursa, 3844 soat — 160 kun yo‘l yurardi.', 'От Земли до Луны в среднем 384 400 км. Свет долетает туда за 1,3 секунды. Автомобиль на скорости 100 км/ч без остановок ехал бы 3844 часа — 160 дней.', 'The Moon is on average 384 400 km from Earth. Light gets there in 1.3 seconds. A car at 100 km/h without stopping would take 3844 hours, about 160 days.'),
      L('Dunyodagi eng uzun poyezd 2001-yilda Avstraliyada yurgan: 682 ta vagon, uzunligi 7,3 km. Har bir vagon o‘rtacha 7300 : 682 ≈ 10,7 m.', 'Самый длинный поезд в мире прошёл в Австралии в 2001 году: 682 вагона, длина 7,3 км. Каждый вагон в среднем 7300 : 682 ≈ 10,7 м.', 'The longest train in the world ran in Australia in 2001: 682 wagons, 7.3 km long. Each wagon averaged 7300 : 682 ≈ 10.7 m.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('0,25 · 400 — natija butun sonmi?', '0,25 · 400 — результат целое число?', 'Is 0.25 · 400 a whole number?'),
      L('6 : 200 ni ikki xil tartibda hisoblang: avval 2 ga, keyin 100 ga; va aksincha. Natija bir xilmi?', 'Вычислите 6 : 200 двумя способами: сначала на 2, потом на 100; и наоборот. Результат одинаковый?', 'Work out 6 : 200 in two orders: first by 2 then by 100, and the other way round. Same result?'),
      L('Qaysi biri katta: 0,8 · 50 yoki 0,5 · 80?', 'Что больше: 0,8 · 50 или 0,5 · 80?', 'Which is bigger: 0.8 · 50 or 0.5 · 80?'),
      L('Bir kun 24 soat. 0,5 kun necha soat? 1,5 hafta necha kun?', 'В сутках 24 часа. Сколько часов в 0,5 суток? Сколько дней в 1,5 неделях?', 'A day has 24 hours. How many hours are in 0.5 of a day? How many days in 1.5 weeks?')
    ], after: [
      L('Javoblar: ha, 100; ha, ikkalasi ham 0,03; ular teng — ikkalasi 40; 12 soat va 10,5 kun.', 'Ответы: да, 100; да, оба 0,03; они равны — оба 40; 12 часов и 10,5 дня.', 'Answers: yes, 100; yes, both 0.03; they are equal, both 40; 12 hours and 10.5 days.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Dumaloq son = raqam · xona birligi: 300 = 3 · 100, 40 = 4 · 10.', 'Круглое число = цифра · разрядная единица: 300 = 3 · 100, 40 = 4 · 10.', 'Round number = digit · power of ten: 300 = 3 · 100, 40 = 4 · 10.'),
      L('Ko‘paytirish ikki bosqichda: raqamga ko‘paytir, keyin vergulni o‘ngga sur.', 'Умножение в два шага: умножь на цифру, затем сдвинь запятую вправо.', 'Multiply in two steps: multiply by the digit, then move the point right.'),
      L('Bo‘lish ikki bosqichda: raqamga bo‘l, keyin vergulni chapga sur.', 'Деление в два шага: раздели на цифру, затем сдвинь запятую влево.', 'Divide in two steps: divide by the digit, then move the point left.'),
      L('Bosqichlar tartibi natijaga ta’sir qilmaydi.', 'Порядок шагов на результат не влияет.', 'The order of the steps does not affect the result.'),
      L('Oraliq natijada vergulni yo‘qotmang: 0,4 · 3 = 1,2, 12 emas.', 'Не теряйте запятую в промежуточном результате: 0,4 · 3 = 1,2, а не 12.', 'Do not lose the point in the middle step: 0.4 · 3 = 1.2, not 12.'),
      L('Har doim taxminiy tekshiruv qiling.', 'Всегда делайте прикидку.', 'Always estimate to check.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-2';

  // ---------- t3. O‘lchov birliklarini almashtirish ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Bitta narsa — turli raqamlar', 'Одна вещь — разные числа', 'One thing, different numbers'), p: [
      L('Shifokor bolaning bo‘yini o‘lchab «1 metr 42 santimetr» deydi. Daftaringizga esa «142 cm» deb yozishingiz yoki «1,42 m» deyishingiz mumkin. Uchala yozuv ham bitta bo‘yni bildiradi! Faqat <b>o‘lchov birligi</b> boshqa. Xuddi shunday, bozorda «yarim kilo» uzum so‘raymiz, retseptda esa «500 g» deb yozilgan bo‘ladi.', 'Врач измеряет рост ребёнка и говорит: «1 метр 42 сантиметра». В тетради можно записать «142 см» или «1,42 м». Все три записи означают один и тот же рост! Отличается лишь <b>единица измерения</b>. Так же на базаре мы просим «полкило» винограда, а в рецепте написано «500 г».', 'A doctor measures a child’s height and says “1 metre 42 centimetres”. In your notebook you could write “142 cm” or “1.42 m”. All three mean the same height! Only the <b>unit of measurement</b> differs. In the same way, at the market we ask for “half a kilo” of grapes, while a recipe says “500 g”.'),
      L('Bir birlikdan boshqasiga o‘tish — <b>birliklarni almashtirish</b>. Bunda o‘tgan mavzulardagi ko‘nikma — 10, 100, 1000 ga ko‘paytirish va bo‘lish — asosiy vosita bo‘ladi. Bu mavzuda uzunlik, massa, hajm va vaqt birliklarini almashtirishni o‘rganamiz.', 'Переход от одной единицы к другой — <b>перевод единиц</b>. Главный инструмент здесь — навык из прошлых тем: умножение и деление на 10, 100, 1000. В этой теме научимся переводить единицы длины, массы, объёма и времени.', 'Going from one unit to another is <b>converting units</b>. The main tool is the skill from the previous topics: multiplying and dividing by 10, 100 and 1000. In this topic we learn to convert units of length, mass, volume and time.')
    ] },
    { kind: 'def', h: L('Asosiy birliklar', 'Основные единицы', 'The main units'), p: [
      L('<b>O‘lchov birligi</b> — kattalikni o‘lchash uchun kelishib olingan namuna. Biz ishlatadigan <b>metrik tizim</b>da har bir kattalikning asosiy birligi bor va boshqa birliklar undan 10, 100 yoki 1000 marta katta yoki kichik:', '<b>Единица измерения</b> — условленный образец для измерения величины. В <b>метрической системе</b>, которой мы пользуемся, у каждой величины есть основная единица, а остальные больше или меньше её в 10, 100 или 1000 раз:', 'A <b>unit of measurement</b> is an agreed standard for measuring a quantity. In the <b>metric system</b> we use, each quantity has a base unit, and the other units are 10, 100 or 1000 times larger or smaller:')
    ], list: [
      L('<b>Uzunlik:</b> 1 km = 1000 m; 1 m = 10 dm = 100 cm = 1000 mm; 1 cm = 10 mm.', '<b>Длина:</b> 1 км = 1000 м; 1 м = 10 дм = 100 см = 1000 мм; 1 см = 10 мм.', '<b>Length:</b> 1 km = 1000 m; 1 m = 10 dm = 100 cm = 1000 mm; 1 cm = 10 mm.'),
      L('<b>Massa:</b> 1 t = 1000 kg; 1 kg = 1000 g; 1 sentner (s) = 100 kg.', '<b>Масса:</b> 1 т = 1000 кг; 1 кг = 1000 г; 1 центнер (ц) = 100 кг.', '<b>Mass:</b> 1 t = 1000 kg; 1 kg = 1000 g; 1 quintal = 100 kg.'),
      L('<b>Hajm (sig‘im):</b> 1 l = 1000 ml; 1 l = 10 dl.', '<b>Объём (вместимость):</b> 1 л = 1000 мл; 1 л = 10 дл.', '<b>Volume (capacity):</b> 1 l = 1000 ml; 1 l = 10 dl.'),
      L('<b>Vaqt:</b> 1 soat = 60 min; 1 min = 60 s — bu yerda 10 lik emas, 60 lik bog‘lanish!', '<b>Время:</b> 1 ч = 60 мин; 1 мин = 60 с — здесь связь не через 10, а через 60!', '<b>Time:</b> 1 h = 60 min; 1 min = 60 s — here the link is 60, not 10!')
    ], after: [
      L('Birlik nomlaridagi qo‘shimchalar ma’noga ega: <b>kilo</b> — ming (kilogramm = 1000 gramm), <b>santi</b> — yuzdan bir (santimetr = metrning yuzdan biri), <b>milli</b> — mingdan bir (millimetr = metrning mingdan biri).', 'Приставки в названиях единиц имеют смысл: <b>кило</b> — тысяча (килограмм = 1000 граммов), <b>санти</b> — сотая (сантиметр = сотая метра), <b>милли</b> — тысячная (миллиметр = тысячная метра).', 'The prefixes in unit names carry meaning: <b>kilo</b> means a thousand (kilogram = 1000 grams), <b>centi</b> means a hundredth (centimetre = one hundredth of a metre), <b>milli</b> means a thousandth (millimetre = one thousandth of a metre).')
    ] },
    { kind: 'history', h: L('Tirsakdan metrgacha', 'От локтя до метра', 'From the cubit to the metre'), p: [
      L('Qadimda uzunlik tana a’zolari bilan o‘lchangan: tirsak, qarich, qadam, oyoq (fut). Muammo shundaki, har kimning tirsagi har xil! Bir shaharda bir «tirsak» mato, boshqasida boshqa uzunlikda sotilardi. Savdogarlar doim tortishardi.', 'В древности длину измеряли частями тела: локтем, пядью, шагом, ступнёй (футом). Беда в том, что локоть у каждого свой! В одном городе «локоть» ткани был одной длины, в другом — другой. Купцы постоянно спорили.', 'In ancient times length was measured with parts of the body: the cubit, the span, the pace, the foot. The trouble was that everyone’s forearm is different! A “cubit” of cloth in one town was one length and in another town a different one. Merchants argued constantly.'),
      L('1790-yillarda Fransiyada olimlar yangi, hamma uchun bir xil tizim yaratdi. <b>Metr</b> Yer meridiani choragining o‘n milliondan bir qismi deb belgilandi. Kilogramm — 1 dm<sup>3</sup> suvning massasi. Barcha birliklar 10 ga asoslangani uchun ularni almashtirish vergul surishga aylandi.', 'В 1790-х годах во Франции учёные создали новую, единую для всех систему. <b>Метр</b> определили как одну десятимиллионную часть четверти земного меридиана. Килограмм — масса 1 дм<sup>3</sup> воды. Все единицы основаны на 10, поэтому перевод превратился в перенос запятой.', 'In the 1790s scientists in France created a new system, the same for everyone. The <b>metre</b> was defined as one ten-millionth of a quarter of the Earth’s meridian. The kilogram was the mass of 1 dm<sup>3</sup> of water. Since every unit was based on 10, converting turned into moving a point.'),
      L('O‘rta Osiyoda ham o‘lchovlar bilan jiddiy shug‘ullanishgan. <b>Abu Rayhon Beruniy</b> Yer radiusini tog‘ cho‘qqisidan ufqni kuzatib o‘lchagan va hozirgi qiymatga juda yaqin natija olgan. Bugun metrik tizimdan dunyoning deyarli barcha mamlakatlari foydalanadi.', 'В Средней Азии тоже серьёзно занимались измерениями. <b>Абу Райхан Беруни</b> измерил радиус Земли, наблюдая горизонт с горной вершины, и получил результат, очень близкий к современному. Сегодня метрической системой пользуются почти все страны мира.', 'Central Asian scholars took measurement seriously too. <b>Abu Rayhan Biruni</b> measured the Earth’s radius by observing the horizon from a mountain top and got a result very close to today’s value. Today almost every country in the world uses the metric system.')
    ] },
    { kind: 'rule', h: L('Almashtirish qoidasi', 'Правило перевода', 'The conversion rule'), p: [
      L('Qoidani eslab qolish oson, agar uning ma’nosini tushunsangiz:', 'Правило легко запомнить, если понять его смысл:', 'The rule is easy to remember once you understand its meaning:')
    ], list: [
      L('<b>Katta birlikdan kichigiga</b> — <b>ko‘paytiramiz</b>. Kichik birliklar ko‘p kerak bo‘ladi: 2,5 kg = 2,5 · 1000 g = 2500 g.', '<b>Из большей единицы в меньшую</b> — <b>умножаем</b>. Мелких единиц нужно много: 2,5 кг = 2,5 · 1000 г = 2500 г.', '<b>From a bigger unit to a smaller one</b> — <b>multiply</b>. You need many small units: 2.5 kg = 2.5 · 1000 g = 2500 g.'),
      L('<b>Kichik birlikdan kattasiga</b> — <b>bo‘lamiz</b>. Katta birliklar kam bo‘ladi: 350 cm = 350 : 100 m = 3,5 m.', '<b>Из меньшей единицы в большую</b> — <b>делим</b>. Крупных единиц получится мало: 350 см = 350 : 100 м = 3,5 м.', '<b>From a smaller unit to a bigger one</b> — <b>divide</b>. You get few big units: 350 cm = 350 : 100 m = 3.5 m.'),
      L('Nimaga ko‘paytirish yoki bo‘lishni <b>birliklar orasidagi bog‘lanish</b> aytadi: km va m orasida 1000, m va cm orasida 100.', 'На что умножать или делить, подсказывает <b>связь между единицами</b>: между км и м — 1000, между м и см — 100.', 'What to multiply or divide by is given by the <b>link between the units</b>: 1000 between km and m, 100 between m and cm.')
    ], after: [
      L('Tekshiruv savoli: «Son kattalashdimi?» Kichik birlikka o‘tsak, son kattalashishi kerak (2,5 → 2500). Katta birlikka o‘tsak — kichiklashishi kerak (350 → 3,5).', 'Проверочный вопрос: «Число выросло?» При переходе к меньшей единице число должно вырасти (2,5 → 2500). К большей — уменьшиться (350 → 3,5).', 'Check question: “Did the number grow?” Moving to a smaller unit the number must grow (2.5 → 2500). Moving to a bigger unit it must shrink (350 → 3.5).')
    ] },
    { kind: 'steps', h: L('Qadamma-qadam', 'Шаг за шагом', 'Step by step'), p: [
      L('Masalan, 4 m 7 cm ni metrlarda yozamiz.', 'Например, запишем 4 м 7 см в метрах.', 'For example, write 4 m 7 cm in metres.')
    ], list: [
      L('1-qadam. Qaysi birlikka o‘tishni aniqlang: cm → m, ya’ni kichikdan kattaga — bo‘lamiz.', 'Шаг 1. Определите, в какую единицу переводим: см → м, то есть из меньшей в большую — делим.', 'Step 1. Decide the direction: cm → m, small to big, so divide.'),
      L('2-qadam. Bog‘lanishni toping: 1 m = 100 cm.', 'Шаг 2. Найдите связь: 1 м = 100 см.', 'Step 2. Find the link: 1 m = 100 cm.'),
      L('3-qadam. Almashtiring: 7 cm = 7 : 100 m = 0,07 m.', 'Шаг 3. Переведите: 7 см = 7 : 100 м = 0,07 м.', 'Step 3. Convert: 7 cm = 7 : 100 m = 0.07 m.'),
      L('4-qadam. Qo‘shing: 4 m + 0,07 m = 4,07 m.', 'Шаг 4. Сложите: 4 м + 0,07 м = 4,07 м.', 'Step 4. Add: 4 m + 0.07 m = 4.07 m.'),
      L('5-qadam. Tekshiring: 4,07 m = 407 cm. Haqiqatan, 4 m 7 cm = 400 + 7 = 407 cm.', 'Шаг 5. Проверьте: 4,07 м = 407 см. Действительно, 4 м 7 см = 400 + 7 = 407 см.', 'Step 5. Check: 4.07 m = 407 cm. Indeed, 4 m 7 cm = 400 + 7 = 407 cm.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('2,5 kg = ? g', '2,5 кг = ? г', '2.5 kg = ? g'), s: L('Kattadan kichikka — ko‘paytiramiz, 1 kg = 1000 g. 2,5 · 1000 = 2500. Javob: <b>2500 g</b>.', 'Из большей в меньшую — умножаем, 1 кг = 1000 г. 2,5 · 1000 = 2500. Ответ: <b>2500 г</b>.', 'Big to small, multiply; 1 kg = 1000 g. 2.5 · 1000 = 2500. Answer: <b>2500 g</b>.') },
      { q: L('350 cm = ? m', '350 см = ? м', '350 cm = ? m'), s: L('Kichikdan kattaga — bo‘lamiz, 1 m = 100 cm. 350 : 100 = 3,5. Javob: <b>3,5 m</b>.', 'Из меньшей в большую — делим, 1 м = 100 см. 350 : 100 = 3,5. Ответ: <b>3,5 м</b>.', 'Small to big, divide; 1 m = 100 cm. 350 : 100 = 3.5. Answer: <b>3.5 m</b>.') },
      { q: L('750 ml = ? l', '750 мл = ? л', '750 ml = ? l'), s: L('1 l = 1000 ml. 750 : 1000 = 0,75. Javob: <b>0,75 l</b> — litrning to‘rtdan uchi.', '1 л = 1000 мл. 750 : 1000 = 0,75. Ответ: <b>0,75 л</b> — три четверти литра.', '1 l = 1000 ml. 750 : 1000 = 0.75. Answer: <b>0.75 l</b>, three quarters of a litre.') },
      { q: L('3 km 40 m = ? km', '3 км 40 м = ? км', '3 km 40 m = ? km'), s: L('40 m = 40 : 1000 km = 0,04 km. 3 + 0,04 = 3,04. Javob: <b>3,04 km</b>. Diqqat: 3,4 km emas! 3,4 km = 3 km 400 m.', '40 м = 40 : 1000 км = 0,04 км. 3 + 0,04 = 3,04. Ответ: <b>3,04 км</b>. Внимание: не 3,4 км! 3,4 км = 3 км 400 м.', '40 m = 40 : 1000 km = 0.04 km. 3 + 0.04 = 3.04. Answer: <b>3.04 km</b>. Careful: not 3.4 km! 3.4 km = 3 km 400 m.') },
      { q: L('1,5 soat = ? min', '1,5 ч = ? мин', '1.5 h = ? min'), s: L('Vaqtda bog‘lanish 60: 1,5 · 60 = 90. Javob: <b>90 min</b>, ya’ni 1 soat 30 minut — 1 soat 50 minut emas!', 'Для времени связь 60: 1,5 · 60 = 90. Ответ: <b>90 мин</b>, то есть 1 ч 30 мин — а не 1 ч 50 мин!', 'For time the link is 60: 1.5 · 60 = 90. Answer: <b>90 min</b>, that is 1 h 30 min — not 1 h 50 min!') }
    ] },
    { kind: 'table', h: L('Birliklar jadvali', 'Таблица единиц', 'Table of units'), table: { head: [L('Kattalik', 'Величина', 'Quantity'), L('Bog‘lanish', 'Связь', 'Link'), L('Misol', 'Пример', 'Example')], rows: [
      [L('Uzunlik', 'Длина', 'Length'), L('1 km = 1000 m', '1 км = 1000 м', '1 km = 1000 m'), L('2,3 km = 2300 m', '2,3 км = 2300 м', '2.3 km = 2300 m')],
      [L('Uzunlik', 'Длина', 'Length'), L('1 m = 100 cm', '1 м = 100 см', '1 m = 100 cm'), L('1,42 m = 142 cm', '1,42 м = 142 см', '1.42 m = 142 cm')],
      [L('Uzunlik', 'Длина', 'Length'), L('1 cm = 10 mm', '1 см = 10 мм', '1 cm = 10 mm'), L('4,5 cm = 45 mm', '4,5 см = 45 мм', '4.5 cm = 45 mm')],
      [L('Massa', 'Масса', 'Mass'), L('1 t = 1000 kg', '1 т = 1000 кг', '1 t = 1000 kg'), L('0,8 t = 800 kg', '0,8 т = 800 кг', '0.8 t = 800 kg')],
      [L('Massa', 'Масса', 'Mass'), L('1 kg = 1000 g', '1 кг = 1000 г', '1 kg = 1000 g'), L('250 g = 0,25 kg', '250 г = 0,25 кг', '250 g = 0.25 kg')],
      [L('Hajm', 'Объём', 'Volume'), L('1 l = 1000 ml', '1 л = 1000 мл', '1 l = 1000 ml'), L('1,5 l = 1500 ml', '1,5 л = 1500 мл', '1.5 l = 1500 ml')],
      [L('Vaqt', 'Время', 'Time'), L('1 soat = 60 min', '1 ч = 60 мин', '1 h = 60 min'), L('0,5 soat = 30 min', '0,5 ч = 30 мин', '0.5 h = 30 min')]
    ] }, after: [
      L('Jadvalni yodlash shart emas — qo‘shimchalarni (kilo, santi, milli) bilsangiz, bog‘lanishni o‘zingiz tiklaysiz.', 'Таблицу не обязательно зубрить — зная приставки (кило, санти, милли), вы сами восстановите связь.', 'You do not have to memorise the table: if you know the prefixes (kilo, centi, milli) you can rebuild each link yourself.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Yo‘nalishni adashtirish.</b> 2,5 kg = 0,0025 g — bema’ni javob: 2,5 kg olma bir zarradan ham yengil bo‘lib qoldi! Kichik birlikka o‘tganda son kattalashadi.', '<b>Путаница в направлении.</b> 2,5 кг = 0,0025 г — абсурд: 2,5 кг яблок стали легче пылинки! При переходе к меньшей единице число растёт.', '<b>Wrong direction.</b> 2.5 kg = 0.0025 g is absurd: 2.5 kg of apples became lighter than a speck of dust! Moving to a smaller unit makes the number grow.'),
      L('<b>Noto‘g‘ri bog‘lanish.</b> 3 m = 3000 cm — xato, m va cm orasida 100: 3 m = 300 cm.', '<b>Неверная связь.</b> 3 м = 3000 см — ошибка, между м и см 100: 3 м = 300 см.', '<b>Wrong link.</b> 3 m = 3000 cm is wrong; m and cm differ by 100: 3 m = 300 cm.'),
      L('<b>Nolni tushirib qoldirish.</b> 3 km 40 m = 3,4 km — xato. 40 m = 0,040 km, demak 3,04 km.', '<b>Пропуск нуля.</b> 3 км 40 м = 3,4 км — ошибка. 40 м = 0,040 км, значит 3,04 км.', '<b>Dropping a zero.</b> 3 km 40 m = 3.4 km is wrong. 40 m = 0.040 km, so 3.04 km.'),
      L('<b>Vaqtni 100 lik deb o‘ylash.</b> 2,5 soat = 2 soat 50 minut — xato. 0,5 soat = 30 minut, demak 2 soat 30 minut.', '<b>Считать время сотнями.</b> 2,5 ч = 2 ч 50 мин — ошибка. 0,5 ч = 30 мин, значит 2 ч 30 мин.', '<b>Treating time as base 100.</b> 2.5 h = 2 h 50 min is wrong. 0.5 h = 30 min, so 2 h 30 min.'),
      L('<b>Turli birliklarni qo‘shish.</b> 2 m + 30 cm = 32 — ma’nosiz. Avval bir birlikka keltiring: 2,3 m yoki 230 cm.', '<b>Сложение разных единиц.</b> 2 м + 30 см = 32 — бессмыслица. Сначала приведите к одной единице: 2,3 м или 230 см.', '<b>Adding different units.</b> 2 m + 30 cm = 32 is meaningless. First convert to one unit: 2.3 m or 230 cm.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in life'), p: [
      L('<b>Yo‘lda.</b> Yo‘l belgisida «Toshkent 12,5 km» yozilgan. Velosipedchi uchun bu 12 500 m. Navigator «800 m dan keyin o‘ngga buriling» desa — bu 0,8 km.', '<b>В дороге.</b> На знаке написано «Ташкент 12,5 км». Для велосипедиста это 12 500 м. Навигатор говорит «через 800 м поверните направо» — это 0,8 км.', '<b>On the road.</b> A sign says “Tashkent 12.5 km”. For a cyclist that is 12 500 m. A navigator says “turn right in 800 m” — that is 0.8 km.'),
      L('<b>Oshxona va do‘kon.</b> Retseptda 0,2 kg un — tarozida 200 g. Sharbat qutisida 0,95 l — bu 950 ml. Ikki quti sharbat bilan 1,9 l, ya’ni 8 ta 237 ml li stakan to‘ladi.', '<b>Кухня и магазин.</b> В рецепте 0,2 кг муки — на весах 200 г. На пакете сока 0,95 л — это 950 мл. Двумя пакетами (1,9 л) можно наполнить 8 стаканов по 237 мл.', '<b>Kitchen and shop.</b> A recipe needs 0.2 kg of flour — 200 g on the scales. A juice carton holds 0.95 l, which is 950 ml. Two cartons (1.9 l) fill 8 glasses of 237 ml.'),
      L('<b>Tibbiyot.</b> Dorining bir dozasi 0,25 g — qadoqda «250 mg» yoziladi. Shifokorlar va farmatsevtlar birliklarni xatosiz almashtirishi hayot uchun muhim.', '<b>Медицина.</b> Одна доза лекарства 0,25 г — на упаковке пишут «250 мг». Для врачей и фармацевтов безошибочный перевод единиц жизненно важен.', '<b>Medicine.</b> One dose of a medicine is 0.25 g; the packet says “250 mg”. For doctors and pharmacists, converting units without error is a matter of life and death.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('1999-yilda NASAning «Mars Climate Orbiter» kosmik apparati Mars atmosferasida yonib ketdi. Sababi — bir jamoa kuchni metrik birliklarda, boshqasi esa ingliz birliklarida hisoblagan. Birlik xatosi 125 million dollarlik apparatni yo‘q qildi!', 'В 1999 году аппарат NASA «Mars Climate Orbiter» сгорел в атмосфере Марса. Причина: одна команда считала силу в метрических единицах, а другая — в английских. Ошибка в единицах уничтожила аппарат стоимостью 125 миллионов долларов!', 'In 1999 NASA’s Mars Climate Orbiter burned up in the Martian atmosphere. The cause: one team calculated force in metric units, the other in imperial units. A unit mix-up destroyed a 125-million-dollar spacecraft!'),
      L('2019-yildan boshlab kilogramm endi Parijdagi metall silindr bilan emas, balki tabiatning doimiy kattaligi — Plank doimiysi orqali aniqlanadi. Metr esa yorug‘likning vakuumda 1/299 792 458 sekundda bosib o‘tgan yo‘li.', 'С 2019 года килограмм определяется не металлическим цилиндром в Париже, а через постоянную природы — постоянную Планка. А метр — это путь, который свет проходит в вакууме за 1/299 792 458 секунды.', 'Since 2019 the kilogram has been defined not by a metal cylinder in Paris but by a constant of nature, the Planck constant. The metre is the distance light travels in a vacuum in 1/299 792 458 of a second.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('Qaysi biri og‘ir: 1,2 kg yoki 1050 g?', 'Что тяжелее: 1,2 кг или 1050 г?', 'Which is heavier: 1.2 kg or 1050 g?'),
      L('5 m 5 cm ni metrlarda yozing.', 'Запишите 5 м 5 см в метрах.', 'Write 5 m 5 cm in metres.'),
      L('0,25 soat necha minut?', 'Сколько минут в 0,25 ч?', 'How many minutes are in 0.25 h?'),
      L('Paqirga 12 l suv sig‘adi. 1,5 l li butilkadan nechta kerak?', 'В ведро входит 12 л воды. Сколько нужно бутылок по 1,5 л?', 'A bucket holds 12 l. How many 1.5 l bottles fill it?')
    ], after: [
      L('Javoblar: 1,2 kg = 1200 g — og‘irroq; 5,05 m; 15 minut; 8 ta butilka.', 'Ответы: 1,2 кг = 1200 г — тяжелее; 5,05 м; 15 минут; 8 бутылок.', 'Answers: 1.2 kg = 1200 g, heavier; 5.05 m; 15 minutes; 8 bottles.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Metrik tizimda birliklar 10, 100, 1000 marta farq qiladi.', 'В метрической системе единицы отличаются в 10, 100, 1000 раз.', 'In the metric system units differ by factors of 10, 100 and 1000.'),
      L('Katta → kichik: <b>ko‘paytiramiz</b>; kichik → katta: <b>bo‘lamiz</b>.', 'Большая → меньшая: <b>умножаем</b>; меньшая → большая: <b>делим</b>.', 'Big → small: <b>multiply</b>; small → big: <b>divide</b>.'),
      L('kilo = 1000, santi = 1/100, milli = 1/1000.', 'кило = 1000, санти = 1/100, милли = 1/1000.', 'kilo = 1000, centi = 1/100, milli = 1/1000.'),
      L('Ikki birlikli yozuvni (3 km 40 m) almashtirishda nollarga e’tibor bering: 3,04 km.', 'Переводя запись с двумя единицами (3 км 40 м), следите за нулями: 3,04 км.', 'When converting a two-unit value (3 km 40 m), mind the zeros: 3.04 km.'),
      L('Vaqt 60 lik: 0,5 soat = 30 minut.', 'Время — по 60: 0,5 ч = 30 мин.', 'Time works in 60s: 0.5 h = 30 min.'),
      L('Faqat bir xil birliklarni qo‘shish va ayirish mumkin.', 'Складывать и вычитать можно только одинаковые единицы.', 'Only like units can be added or subtracted.')
    ] }
  ] });

  // ---------- t4. O‘nli kasrlarga doir matnli masalalar ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Matematika hikoya ichida', 'Математика внутри истории', 'Maths inside a story'), p: [
      L('Matnli masala — bu kichik hikoya, uning ichida savol yashiringan. «Onam bozordan 2,5 kg olma va 1,75 kg nok oldi. Jami qancha meva oldi?» Bu hikoyadan amalni ajratib olish — asosiy mahorat. Hisoblashning o‘zi ko‘pincha oson; qiyini — nima hisoblashni tushunish.', 'Текстовая задача — это маленькая история, в которой спрятан вопрос. «Мама купила на базаре 2,5 кг яблок и 1,75 кг груш. Сколько всего фруктов она купила?» Главное умение — извлечь из истории действие. Само вычисление обычно лёгкое; трудно понять, что вычислять.', 'A word problem is a little story with a question hidden inside. “Mum bought 2.5 kg of apples and 1.75 kg of pears at the market. How much fruit did she buy?” The key skill is pulling the operation out of the story. The calculation itself is usually easy; the hard part is knowing what to calculate.'),
      L('Hayotdagi deyarli barcha masalalarda o‘nli kasrlar uchraydi: narx, massa, masofa, vaqt, harorat. Bu mavzuda biz o‘nli kasrli masalalarni yechishning aniq rejasini tuzamiz va eng ko‘p uchraydigan turlarini ko‘rib chiqamiz.', 'Почти во всех жизненных задачах встречаются десятичные дроби: цена, масса, расстояние, время, температура. В этой теме составим чёткий план решения задач с десятичными дробями и разберём самые частые их виды.', 'Decimals appear in almost every real-life problem: prices, masses, distances, times, temperatures. In this topic we build a clear plan for solving decimal word problems and look at the most common types.')
    ] },
    { kind: 'def', h: L('Masalaning qismlari', 'Части задачи', 'Parts of a problem'), p: [
      L('Har qanday matnli masala uch qismdan iborat:', 'Любая текстовая задача состоит из трёх частей:', 'Every word problem has three parts:')
    ], list: [
      L('<b>Shart</b> — nima ma’lum: sonlar va ular orasidagi munosabatlar («2,5 kg olma», «1 kg i 12 ming so‘m»).', '<b>Условие</b> — что известно: числа и отношения между ними («2,5 кг яблок», «1 кг стоит 12 тысяч сум»).', '<b>Given</b> — what is known: the numbers and how they relate (“2.5 kg of apples”, “1 kg costs 12 thousand sum”).'),
      L('<b>Savol</b> — nimani topish kerak («jami qancha?», «qancha qaytim?»).', '<b>Вопрос</b> — что нужно найти («сколько всего?», «сколько сдачи?»).', '<b>Question</b> — what to find (“how much in all?”, “how much change?”).'),
      L('<b>Yechim</b> — shartdan savolga olib boruvchi amallar zanjiri va <b>javob</b> (birligi bilan!).', '<b>Решение</b> — цепочка действий от условия к вопросу, и <b>ответ</b> (с единицами!).', '<b>Solution</b> — the chain of operations from the given to the question, and the <b>answer</b> (with units!).')
    ], after: [
      L('Kalit so‘zlar yordam beradi, lekin ularga ko‘r-ko‘rona ishonmang. «Jami», «birgalikda» ko‘pincha qo‘shishni, «qoldi», «farqi», «qancha ko‘p» — ayirishni, «har biri … dan, n ta» — ko‘paytirishni, «teng bo‘lib» — bo‘lishni bildiradi. Ammo har doim mazmunni o‘ylang.', 'Ключевые слова помогают, но не доверяйте им слепо. «Всего», «вместе» часто означают сложение, «осталось», «разница», «на сколько больше» — вычитание, «по … каждый, n штук» — умножение, «поровну» — деление. Но всегда думайте о смысле.', 'Key words help, but do not trust them blindly. “In all” and “together” often mean adding; “left”, “difference”, “how much more” mean subtracting; “each … , n of them” means multiplying; “shared equally” means dividing. But always think about the meaning.')
    ] },
    { kind: 'history', h: L('Qadimiy masalalar', 'Древние задачи', 'Ancient problems'), p: [
      L('Eng qadimgi matnli masalalar Misrning <b>Rind papirusida</b> (taxminan miloddan avvalgi 1650-yil) saqlangan: non va pivoni ishchilarga teng bo‘lish, don omborining hajmini topish. Misrliklar kasrlarni «1/n» ko‘rinishidagi bo‘laklar yig‘indisi sifatida yozishgan.', 'Самые древние текстовые задачи сохранились в египетском <b>папирусе Ринда</b> (около 1650 г. до н. э.): разделить хлеб и пиво между работниками поровну, найти объём зернохранилища. Египтяне записывали дроби как суммы долей вида «1/n».', 'The oldest word problems survive in Egypt’s <b>Rhind Papyrus</b> (about 1650 BC): sharing bread and beer equally among workers, finding the volume of a granary. The Egyptians wrote fractions as sums of unit parts “1/n”.'),
      L('<b>Al-Xorazmiy</b> o‘zining mashhur «Al-jabr va al-muqobala» kitobida meros taqsimlash, savdo va yer o‘lchash bo‘yicha yuzlab masalalar keltirgan. U har bir masalani so‘z bilan yechib, «shuni qil, keyin buni qil» deb tushuntirgan — bu aslida algoritm edi.', '<b>Аль-Хорезми</b> в знаменитой книге «Аль-джабр валь-мукабала» привёл сотни задач о разделе наследства, торговле и измерении земли. Он решал каждую словами, объясняя «сделай это, затем то», — по сути, это был алгоритм.', 'In his famous book “Al-jabr wa’l-muqabala”, <b>al-Khwarizmi</b> gave hundreds of problems about inheritance, trade and land measurement. He solved each in words, explaining “do this, then that” — in effect, an algorithm.'),
      L('Al-Koshiy esa o‘nli kasrlarni aynan amaliy hisob uchun — me’morlar, savdogarlar va astronomlar uchun qulay bo‘lsin deb targ‘ib qilgan. U gumbaz va ravoqlarning yuzi va hajmini hisoblash usullarini ham yozib qoldirgan.', 'А аль-Каши продвигал десятичные дроби именно для практического счёта — чтобы было удобно зодчим, купцам и астрономам. Он оставил и способы вычисления площадей и объёмов куполов и арок.', 'Al-Kashi, for his part, championed decimals precisely for practical work — to help architects, merchants and astronomers. He also recorded methods for computing the areas and volumes of domes and arches.')
    ] },
    { kind: 'rule', h: L('O‘nli kasrlar bilan amallar — eslatma', 'Действия с десятичными дробями — памятка', 'Operations with decimals — a reminder'), list: [
      L('<b>Qo‘shish va ayirish:</b> vergulni vergul ostiga yozamiz, xonalarni tenglash uchun nol qo‘shamiz: 2,5 + 1,75 = 2,50 + 1,75 = 4,25.', '<b>Сложение и вычитание:</b> пишем запятую под запятой, для выравнивания добавляем нули: 2,5 + 1,75 = 2,50 + 1,75 = 4,25.', '<b>Adding and subtracting:</b> line the points up, padding with zeros: 2.5 + 1.75 = 2.50 + 1.75 = 4.25.'),
      L('<b>Natural songa ko‘paytirish:</b> vergulga e’tibor bermay ko‘paytiramiz, so‘ng kasr qismda nechta raqam bo‘lsa, natijada shuncha raqamni vergul bilan ajratamiz: 1,25 · 4 = 5,00 = 5.', '<b>Умножение на натуральное число:</b> умножаем, не обращая внимания на запятую, затем отделяем запятой столько цифр, сколько их было в дробной части: 1,25 · 4 = 5,00 = 5.', '<b>Multiplying by a whole number:</b> multiply ignoring the point, then mark off as many decimal places as the decimal had: 1.25 · 4 = 5.00 = 5.'),
      L('<b>Natural songa bo‘lish:</b> butun qismni bo‘lib bo‘lgach, bo‘linmaga vergul qo‘yamiz va bo‘lishni davom ettiramiz: 7,2 : 3 = 2,4.', '<b>Деление на натуральное число:</b> разделив целую часть, ставим в частном запятую и продолжаем деление: 7,2 : 3 = 2,4.', '<b>Dividing by a whole number:</b> after dividing the whole part, put the point in the quotient and carry on: 7.2 : 3 = 2.4.'),
      L('<b>Har doim:</b> javobga birlik yozing va mantiqan tekshiring.', '<b>Всегда:</b> пишите единицы в ответе и проверяйте его на разумность.', '<b>Always:</b> write units in the answer and check it makes sense.')
    ] },
    { kind: 'steps', h: L('Masala yechish rejasi', 'План решения задачи', 'A plan for solving problems'), list: [
      L('1. <b>O‘qing</b> — masalani ikki marta, shoshilmasdan o‘qing.', '1. <b>Прочитайте</b> задачу дважды, не спеша.', '1. <b>Read</b> the problem twice, slowly.'),
      L('2. <b>Ajrating</b> — nima ma’lum, nima so‘ralgan? Qisqa yozuv yoki chizma qiling.', '2. <b>Выделите</b>: что известно, что спрашивается? Сделайте краткую запись или рисунок.', '2. <b>Pick out</b> what is known and what is asked. Make a short note or a sketch.'),
      L('3. <b>Rejalashtiring</b> — qaysi amallar va qaysi tartibda kerak? Birliklar bir xilmi?', '3. <b>Спланируйте</b>: какие действия и в каком порядке? Единицы одинаковые?', '3. <b>Plan</b>: which operations, in what order? Are the units the same?'),
      L('4. <b>Hisoblang</b> — har bir amalni alohida yozing, vergulni kuzating.', '4. <b>Вычислите</b>: записывайте каждое действие отдельно, следите за запятой.', '4. <b>Calculate</b>: write each step separately and watch the point.'),
      L('5. <b>Tekshiring</b> — taxminiy hisob bilan solishtiring va javobni to‘liq gap bilan yozing.', '5. <b>Проверьте</b>: сравните с прикидкой и запишите ответ полным предложением.', '5. <b>Check</b>: compare with an estimate and write the answer as a full sentence.')
    ] },
    { kind: 'example', h: L('Yechilgan masalalar', 'Разобранные задачи', 'Worked problems'), ex: [
      { q: L('1 kg olma 12 ming so‘m. 2,5 kg olma qancha turadi?', '1 кг яблок стоит 12 тысяч сум. Сколько стоят 2,5 кг?', '1 kg of apples costs 12 thousand sum. How much do 2.5 kg cost?'), s: L('Narx · massa: 12 · 2,5 = 30. Taxmin: 2 kg — 24, 3 kg — 36, javob ular orasida. Javob: <b>30 ming so‘m</b>.', 'Цена · масса: 12 · 2,5 = 30. Прикидка: 2 кг — 24, 3 кг — 36, ответ между ними. Ответ: <b>30 тысяч сум</b>.', 'Price · mass: 12 · 2.5 = 30. Estimate: 2 kg costs 24, 3 kg costs 36; the answer lies between. Answer: <b>30 thousand sum</b>.') },
      { q: L('Ip 5,2 m edi. Undan 1,75 m kesib olindi. Qancha qoldi?', 'Нитка была 5,2 м. От неё отрезали 1,75 м. Сколько осталось?', 'A string was 5.2 m long. 1.75 m was cut off. How much is left?'), s: L('Ayirish: 5,20 − 1,75 = 3,45. Tekshiruv: 3,45 + 1,75 = 5,20. Javob: <b>3,45 m</b>.', 'Вычитание: 5,20 − 1,75 = 3,45. Проверка: 3,45 + 1,75 = 5,20. Ответ: <b>3,45 м</b>.', 'Subtract: 5.20 − 1.75 = 3.45. Check: 3.45 + 1.75 = 5.20. Answer: <b>3.45 m</b>.') },
      { q: L('3 ta bir xil daftar 7,2 ming so‘m turadi. 5 ta daftar qancha?', '3 одинаковые тетради стоят 7,2 тысячи сум. Сколько стоят 5 тетрадей?', '3 identical notebooks cost 7.2 thousand sum. How much do 5 cost?'), s: L('1) Bitta daftar: 7,2 : 3 = 2,4. 2) Beshtasi: 2,4 · 5 = 12. Javob: <b>12 ming so‘m</b>.', '1) Одна тетрадь: 7,2 : 3 = 2,4. 2) Пять: 2,4 · 5 = 12. Ответ: <b>12 тысяч сум</b>.', '1) One notebook: 7.2 : 3 = 2.4. 2) Five: 2.4 · 5 = 12. Answer: <b>12 thousand sum</b>.') },
      { q: L('Ali 50 ming so‘m bilan do‘konga bordi. 1,5 l li sut 11,5 ming, non 4,8 ming turadi. U 2 ta sut va 1 non oldi. Qaytim qancha?', 'Али пошёл в магазин с 50 тысячами сум. Молоко 1,5 л — 11,5 тысячи, хлеб — 4,8 тысячи. Он купил 2 пакета молока и 1 хлеб. Какова сдача?', 'Ali went to the shop with 50 thousand sum. A 1.5 l milk costs 11.5 thousand, bread 4.8 thousand. He bought 2 milks and 1 bread. What is his change?'), s: L('1) Sut: 11,5 · 2 = 23. 2) Xarid: 23 + 4,8 = 27,8. 3) Qaytim: 50 − 27,8 = 22,2. Javob: <b>22,2 ming so‘m</b>, ya’ni 22 200 so‘m.', '1) Молоко: 11,5 · 2 = 23. 2) Покупка: 23 + 4,8 = 27,8. 3) Сдача: 50 − 27,8 = 22,2. Ответ: <b>22,2 тысячи сум</b>, то есть 22 200 сум.', '1) Milk: 11.5 · 2 = 23. 2) Total: 23 + 4.8 = 27.8. 3) Change: 50 − 27.8 = 22.2. Answer: <b>22.2 thousand sum</b>, that is 22 200 sum.') },
      { q: L('Velosipedchi 1 soatda 14,5 km yuradi. 3 soatda u qancha yo‘l bosadi?', 'Велосипедист проезжает 14,5 км за час. Какой путь он проедет за 3 часа?', 'A cyclist rides 14.5 km an hour. How far does he ride in 3 hours?'), s: L('14,5 · 3 = 43,5. Javob: <b>43,5 km</b>.', '14,5 · 3 = 43,5. Ответ: <b>43,5 км</b>.', '14.5 · 3 = 43.5. Answer: <b>43.5 km</b>.') }
    ] },
    { kind: 'table', h: L('Masala turlari', 'Виды задач', 'Types of problems'), table: { head: [L('Bog‘lanish', 'Связь', 'Relationship'), L('Formula', 'Формула', 'Formula'), L('Misol', 'Пример', 'Example')], rows: [
      [L('Narx, miqdor, qiymat', 'Цена, количество, стоимость', 'Price, quantity, cost'), L('qiymat = narx · miqdor', 'стоимость = цена · количество', 'cost = price · quantity'), L('3,5 · 4 = 14 ming so‘m', '3,5 · 4 = 14 тыс. сум', '3.5 · 4 = 14 thousand sum')],
      [L('Tezlik, vaqt, masofa', 'Скорость, время, расстояние', 'Speed, time, distance'), L('masofa = tezlik · vaqt', 'расстояние = скорость · время', 'distance = speed · time'), L('60 · 2,5 = 150 km', '60 · 2,5 = 150 км', '60 · 2.5 = 150 km')],
      [L('Bitta massa, soni, jami', 'Масса одного, число, общая', 'Mass each, count, total'), L('jami = bittasi · soni', 'общая = одного · число', 'total = each · count'), L('0,25 · 8 = 2 kg', '0,25 · 8 = 2 кг', '0.25 · 8 = 2 kg')],
      [L('Butun va qismlar', 'Целое и части', 'Whole and parts'), L('qism = butun − boshqa qism', 'часть = целое − другая часть', 'part = whole − other part'), L('5,2 − 1,75 = 3,45 m', '5,2 − 1,75 = 3,45 м', '5.2 − 1.75 = 3.45 m')]
    ] }, after: [
      L('Har bir uchlikda bitta kattalik noma’lum bo‘lsa, uni qolgan ikkitasidan topamiz. Masalan, qiymat va miqdor ma’lum bo‘lsa, narx = qiymat : miqdor; masofa va tezlik ma’lum bo‘lsa, vaqt = masofa : tezlik. Ko‘paytirish va bo‘lish bir-biriga teskari amallar ekanini eslang: agar 12 · 2,5 = 30 bo‘lsa, unda 30 : 2,5 = 12 va 30 : 12 = 2,5.', 'Если в каждой тройке одна величина неизвестна, её находят по двум другим. Например, зная стоимость и количество, находим цену = стоимость : количество; зная расстояние и скорость — время = расстояние : скорость. Помните, что умножение и деление — обратные действия: если 12 · 2,5 = 30, то 30 : 2,5 = 12 и 30 : 12 = 2,5.', 'In each trio, if one quantity is unknown we find it from the other two. For example, knowing the cost and the quantity gives price = cost : quantity; knowing distance and speed gives time = distance : speed. Remember that multiplication and division undo each other: if 12 · 2.5 = 30, then 30 : 2.5 = 12 and 30 : 12 = 2.5.'),
      L('Ko‘p bosqichli masalalarda bunday bog‘lanishlar zanjir bo‘lib ulanadi: avval bitta buyum narxini topamiz, keyin undan foydalanib boshqa miqdorning qiymatini hisoblaymiz. Shuning uchun har bir oraliq natijaga nom bering: «bitta daftar narxi», «xarid qiymati» va hokazo. Bu sizni chalkashlikdan saqlaydi.', 'В многошаговых задачах такие связи соединяются в цепочку: сначала находим цену одного предмета, затем с её помощью — стоимость другого количества. Поэтому давайте имя каждому промежуточному результату: «цена одной тетради», «стоимость покупки» и т. д. Это убережёт от путаницы.', 'In multi-step problems these links join into a chain: first find the price of one item, then use it to find the cost of a different amount. So give each intermediate result a name: “price of one notebook”, “cost of the shopping” and so on. That keeps you from getting muddled.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Vergulni noto‘g‘ri tekislash.</b> 5,2 − 1,75 ni oxirgi raqamlar bo‘yicha tekislab, 5,2 ni 0,52 deb hisoblash. Vergul — vergul ostida!', '<b>Неверное выравнивание.</b> Выровнять 5,2 − 1,75 по последним цифрам, будто 5,2 — это 0,52. Запятая — под запятой!', '<b>Wrong alignment.</b> Lining up 5.2 − 1.75 by the last digits, as if 5.2 were 0.52. Point under point!'),
      L('<b>Birliklarni aralashtirish.</b> 2 kg + 300 g = 302 — xato. 2 kg + 0,3 kg = 2,3 kg.', '<b>Смешение единиц.</b> 2 кг + 300 г = 302 — ошибка. 2 кг + 0,3 кг = 2,3 кг.', '<b>Mixing units.</b> 2 kg + 300 g = 302 is wrong. 2 kg + 0.3 kg = 2.3 kg.'),
      L('<b>Oraliq savolni o‘tkazib yuborish.</b> Qaytim masalasida xarid narxini topmasdan 50 dan faqat bitta narxni ayirish.', '<b>Пропуск промежуточного вопроса.</b> В задаче на сдачу вычесть из 50 только одну цену, не найдя стоимость всей покупки.', '<b>Skipping a middle step.</b> In a change problem, subtracting only one price from 50 without finding the whole bill.'),
      L('<b>Javobni tekshirmaslik.</b> Agar 2,5 kg olma 300 ming so‘m chiqsa — bu shubhali, 1 kg 12 ming bo‘lsa. Vergul bir xona siljigan.', '<b>Не проверять ответ.</b> Если 2,5 кг яблок стоят 300 тысяч при цене 12 тысяч за кг — это подозрительно. Запятая сдвинулась на знак.', '<b>Not checking.</b> If 2.5 kg of apples at 12 thousand a kilo comes to 300 thousand, something is off: the point slipped a place.')
    ] },
    { kind: 'life', h: L('Hayotdagi masalalar', 'Задачи из жизни', 'Real-life problems'), p: [
      L('<b>Oilaviy byudjet.</b> Oyiga elektr uchun 1 kVt·soat 450 so‘mdan 180 kVt·soat sarflansa, to‘lov 450 · 180 = 81 000 so‘m. Gaz, suv, internet ham shunday hisoblanadi.', '<b>Семейный бюджет.</b> Если в месяц расходуется 180 кВт·ч электричества по 450 сум, плата 450 · 180 = 81 000 сум. Так же считают газ, воду, интернет.', '<b>Family budget.</b> If a family uses 180 kWh of electricity a month at 450 sum each, the bill is 450 · 180 = 81 000 sum. Gas, water and internet are worked out the same way.'),
      L('<b>Sayohat.</b> Avtobus chiptasi 2,5 ming so‘m, kuniga 2 marta, 22 ish kuni — oyiga 110 ming so‘m. Oylik abonement 90 ming bo‘lsa, u foydaliroq.', '<b>Поездки.</b> Билет на автобус — 2,5 тысячи сум, 2 раза в день, 22 рабочих дня — 110 тысяч в месяц. Если проездной стоит 90 тысяч, он выгоднее.', '<b>Travel.</b> A bus ticket is 2.5 thousand sum, twice a day for 22 school days — 110 thousand a month. If a monthly pass costs 90 thousand, it is the better deal.'),
      L('<b>Sport.</b> Sportchi 100 m ni 11,8 s da yugurdi, keyingi urinishda 11,65 s da. Natija 11,8 − 11,65 = 0,15 s ga yaxshilandi.', '<b>Спорт.</b> Спортсмен пробежал 100 м за 11,8 с, в следующей попытке — за 11,65 с. Результат улучшился на 11,8 − 11,65 = 0,15 с.', '<b>Sport.</b> An athlete ran 100 m in 11.8 s, then in 11.65 s. The time improved by 11.8 − 11.65 = 0.15 s.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('Usain Bolt 2009-yilda 100 m ni 9,58 sekundda yugurib, jahon rekordini o‘rnatdi. Bu soatiga taxminan 37,6 km o‘rtacha tezlik demakdir — shahar ko‘chasidagi velosipedchidan ham tez!', 'Усэйн Болт в 2009 году пробежал 100 м за 9,58 секунды и установил мировой рекорд. Это средняя скорость около 37,6 км/ч — быстрее городского велосипедиста!', 'In 2009 Usain Bolt ran 100 m in 9.58 seconds, a world record. That is an average speed of about 37.6 km/h, faster than a city cyclist!'),
      L('Sport musobaqalarida vaqt sekundning yuzdan bir, hatto mingdan bir ulushigacha o‘lchanadi. Suzishda ba’zan g‘olib 0,01 s farq bilan aniqlanadi — bu ko‘z ochib-yumishdan o‘n baravar tezroq.', 'На соревнованиях время измеряют до сотых и даже тысячных долей секунды. В плавании победителя порой определяет разница в 0,01 с — это в десять раз быстрее моргания.', 'In sport, time is measured to hundredths and even thousandths of a second. In swimming the winner is sometimes decided by 0.01 s — ten times quicker than a blink.')
    ] },
    { kind: 'practice', h: L('O‘zingiz yeching', 'Решите сами', 'Try it yourself'), list: [
      L('Kitob 18,5 ming, daftar 3,25 ming so‘m. Kitob daftardan qancha qimmat?', 'Книга стоит 18,5 тысячи, тетрадь — 3,25 тысячи сум. На сколько книга дороже?', 'A book costs 18.5 thousand, a notebook 3.25 thousand sum. How much more is the book?'),
      L('4 ta bir xil quti 10 kg. Bitta quti massasi?', '4 одинаковые коробки весят 10 кг. Масса одной?', '4 identical boxes weigh 10 kg. Mass of one?'),
      L('Poyezd soatiga 72,5 km tezlikda 4 soat yurdi. Masofa?', 'Поезд шёл 4 часа со скоростью 72,5 км/ч. Расстояние?', 'A train travelled 4 hours at 72.5 km/h. Distance?')
    ], after: [
      L('Javoblar: 15,25 ming so‘m; 2,5 kg; 290 km.', 'Ответы: 15,25 тысячи сум; 2,5 кг; 290 км.', 'Answers: 15.25 thousand sum; 2.5 kg; 290 km.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Masala = shart + savol + yechim + javob.', 'Задача = условие + вопрос + решение + ответ.', 'Problem = given + question + solution + answer.'),
      L('Reja: o‘qing, ajrating, rejalashtiring, hisoblang, tekshiring.', 'План: прочитай, выдели, спланируй, вычисли, проверь.', 'Plan: read, pick out, plan, calculate, check.'),
      L('Qo‘shish va ayirishda vergul vergul ostida.', 'При сложении и вычитании — запятая под запятой.', 'When adding and subtracting, line up the points.'),
      L('Avval birliklarni tenglashtiring.', 'Сначала приведите единицы к одной.', 'First make the units the same.'),
      L('Asosiy bog‘lanishlar: qiymat = narx · miqdor; masofa = tezlik · vaqt.', 'Основные связи: стоимость = цена · количество; расстояние = скорость · время.', 'Key links: cost = price · quantity; distance = speed · time.'),
      L('Javobni taxmin bilan tekshiring va birligini yozing.', 'Проверяйте ответ прикидкой и пишите единицы.', 'Check by estimating and write the units.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-2';

  // ---------- t5. Me’yorni topish ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Kim tezroq ishlaydi?', 'Кто работает быстрее?', 'Who works faster?'), p: [
      L('Ikki do‘st gilos terdi. Aziz 3 soatda 18 kg, Bekzod 4 soatda 20 kg terdi. Kim tezroq terdi? Bekzod ko‘proq terdi, lekin u ko‘proq vaqt ham ishladi. Adolatli taqqoslash uchun har biri <b>bir soatda</b> qancha terganini bilish kerak: Aziz — 18 : 3 = 6 kg, Bekzod — 20 : 4 = 5 kg. Demak, Aziz tezroq!', 'Два друга собирали черешню. Азиз за 3 часа собрал 18 кг, Бекзод за 4 часа — 20 кг. Кто собирал быстрее? Бекзод собрал больше, но и работал дольше. Чтобы сравнить честно, нужно знать, сколько каждый собрал <b>за один час</b>: Азиз — 18 : 3 = 6 кг, Бекзод — 20 : 4 = 5 кг. Значит, Азиз быстрее!', 'Two friends picked cherries. Aziz picked 18 kg in 3 hours, Bekzod 20 kg in 4 hours. Who picked faster? Bekzod picked more, but he also worked longer. For a fair comparison we need to know how much each picked <b>in one hour</b>: Aziz 18 : 3 = 6 kg, Bekzod 20 : 4 = 5 kg. So Aziz was faster!'),
      L('Bir soatga, bir kilogrammga, bir kishiga to‘g‘ri keladigan miqdor — <b>me’yor</b> deyiladi. Me’yor turli vaziyatlarni bir xil o‘lchov bilan taqqoslash imkonini beradi: qaysi mashina tezroq, qaysi do‘kon arzonroq, qaysi nasos kuchliroq.', 'Величина, приходящаяся на один час, один килограмм, одного человека, называется <b>нормой</b>. Норма позволяет сравнивать разные ситуации одной меркой: какая машина быстрее, какой магазин дешевле, какой насос мощнее.', 'The amount per one hour, one kilogram or one person is called a <b>rate</b>. A rate lets us compare different situations by the same yardstick: which car is faster, which shop is cheaper, which pump is stronger.'),
      L('Bu mavzuda me’yorni topishni, uning birligini to‘g‘ri yozishni va me’yorlar yordamida taqqoslashni o‘rganamiz.', 'В этой теме научимся находить норму, правильно записывать её единицу и сравнивать с её помощью.', 'In this topic we learn to find a rate, write its unit correctly and use rates to compare.')
    ] },
    { kind: 'def', h: L('Me’yor nima?', 'Что такое норма?', 'What is a rate?'), p: [
      L('<b>Me’yor</b> — bir kattalikning boshqa kattalikning <b>bir birligiga</b> to‘g‘ri keladigan qiymati. Uni topish uchun jami miqdorni birliklar soniga bo‘lamiz.', '<b>Норма</b> — значение одной величины, приходящееся на <b>одну единицу</b> другой величины. Чтобы её найти, общее количество делят на число единиц.', 'A <b>rate</b> is the value of one quantity for <b>one unit</b> of another quantity. To find it, divide the total by the number of units.')
    ], list: [
      L('<b>Tezlik</b> — bir soatda (minutda, sekundda) bosib o‘tilgan yo‘l: km/soat, m/s.', '<b>Скорость</b> — путь за один час (минуту, секунду): км/ч, м/с.', '<b>Speed</b> — distance covered in one hour (minute, second): km/h, m/s.'),
      L('<b>Narx</b> — bir dona yoki bir kilogramm tovarning qiymati: so‘m/kg, so‘m/dona.', '<b>Цена</b> — стоимость одной штуки или одного килограмма товара: сум/кг, сум/шт.', '<b>Price</b> — the cost of one item or one kilogram: sum/kg, sum/item.'),
      L('<b>Ish unumdorligi</b> — bir vaqt birligida bajarilgan ish: bet/min, detal/soat.', '<b>Производительность</b> — работа, сделанная за единицу времени: стр./мин, деталей/ч.', '<b>Productivity</b> — work done per unit of time: pages/min, parts/hour.'),
      L('<b>Sarf</b> — bir birlikka ketadigan material: l/100 km, kg/kishi.', '<b>Расход</b> — материал на одну единицу: л/100 км, кг/чел.', '<b>Consumption</b> — material used per unit: l/100 km, kg/person.')
    ], after: [
      L('Me’yor birligi har doim kasr chizig‘i bilan yoziladi: yuqorida — nima o‘lchanadi, pastda — nimaning bir birligiga. «km/soat» deb o‘qiymiz «kilometr soatiga», «so‘m/kg» — «so‘m kilogrammiga».', 'Единица нормы всегда записывается через черту: сверху — что измеряем, снизу — на единицу чего. «км/ч» читаем «километров в час», «сум/кг» — «сумов за килограмм».', 'A rate’s unit is always written with a slash: on top what is measured, below the unit it is “per”. “km/h” is read “kilometres per hour”, “sum/kg” is “sum per kilogram”.')
    ] },
    { kind: 'history', h: L('Me’yorlar tarixidan', 'Из истории нормы', 'Rates in history'), p: [
      L('Me’yor tushunchasi juda qadimiy. Qadimgi Bobilda ishchilarga kunlik arpa me’yori belgilangan, qurilishda esa bir ishchi bir kunda nechta g‘isht qo‘yishi kerakligi hisoblangan. Bu yozuvlar loy taxtachalarda bugungacha saqlangan.', 'Понятие нормы очень древнее. В Древнем Вавилоне работникам назначали дневную норму ячменя, а на стройке рассчитывали, сколько кирпичей один работник должен уложить за день. Эти записи сохранились на глиняных табличках.', 'The idea of a rate is very old. In ancient Babylon workers received a daily ration of barley, and on building sites people worked out how many bricks one worker should lay in a day. These records survive on clay tablets.'),
      L('Buyuk Ipak yo‘lida karvonlar kuniga taxminan 30–40 km yo‘l bosgan. Savdogarlar shu me’yor bo‘yicha Samarqanddan Xitoygacha necha kun ketishini oldindan hisoblab, suv va yem zaxirasini tayyorlashgan.', 'На Великом шёлковом пути караваны проходили примерно 30–40 км в день. По этой норме купцы заранее считали, сколько дней займёт путь из Самарканда в Китай, и готовили запасы воды и корма.', 'On the Great Silk Road caravans covered roughly 30–40 km a day. Using that rate, merchants worked out in advance how many days the journey from Samarkand to China would take and prepared stores of water and fodder.'),
      L('«Kilometr soatiga» birligi esa XIX asrda, poyezdlar paydo bo‘lgach, keng tarqaldi. Ilk paravozlar soatiga 20–30 km yurgan bo‘lsa, bugungi «Afrosiyob» tezyurar poyezdi Toshkentdan Samarqandgacha soatiga 200 km dan ortiq tezlikda yuradi.', 'Единица «километр в час» широко распространилась в XIX веке с появлением поездов. Первые паровозы ходили со скоростью 20–30 км/ч, а нынешний скоростной поезд «Афросиаб» идёт из Ташкента в Самарканд со скоростью более 200 км/ч.', 'The unit “kilometres per hour” spread in the 19th century once trains appeared. The first steam engines did 20–30 km/h, while today’s high-speed Afrosiyob train runs from Tashkent to Samarkand at over 200 km/h.')
    ] },
    { kind: 'rule', h: L('Me’yor formulasi', 'Формула нормы', 'The rate formula'), p: [
      L('<b>Me’yor = jami miqdor : birliklar soni</b>', '<b>Норма = общее количество : число единиц</b>', '<b>Rate = total amount : number of units</b>')
    ], list: [
      L('Mashina 4 soatda 360 km yurdi: 360 : 4 = <b>90 km/soat</b>.', 'Машина за 4 часа проехала 360 км: 360 : 4 = <b>90 км/ч</b>.', 'A car went 360 km in 4 hours: 360 : 4 = <b>90 km/h</b>.'),
      L('Nasos 8 minutda 1200 l suv chiqardi: 1200 : 8 = <b>150 l/min</b>.', 'Насос за 8 минут выкачал 1200 л: 1200 : 8 = <b>150 л/мин</b>.', 'A pump moved 1200 l in 8 minutes: 1200 : 8 = <b>150 l/min</b>.'),
      L('5 kg shakar 60 ming so‘m: 60 : 5 = <b>12 ming so‘m/kg</b>.', '5 кг сахара — 60 тысяч сум: 60 : 5 = <b>12 тысяч сум/кг</b>.', '5 kg of sugar cost 60 thousand sum: 60 : 5 = <b>12 thousand sum/kg</b>.')
    ], after: [
      L('Nima nimaga bo‘linishini adashtirmang: biz «har bir soatga qancha km» deb so‘raymiz, demak km soatlarga bo‘linadi. Agar teskari bo‘lsak (4 : 360), «bir km ga necha soat» degan boshqa me’yor chiqadi.', 'Не путайте, что на что делится: мы спрашиваем «сколько км на каждый час», значит, км делим на часы. Если разделить наоборот (4 : 360), получится другая норма — «сколько часов на один км».', 'Do not mix up what divides what: we ask “how many km for each hour”, so km is divided by hours. Dividing the other way (4 : 360) gives a different rate, “how many hours per km”.'),
      L('Me’yor jarayon bir tekisda borgan deb hisoblanadi. Haqiqatda mashina goh tez, goh sekin yuradi; 90 km/soat — bu <b>o‘rtacha</b> tezlik.', 'Норма предполагает, что процесс идёт равномерно. На деле машина едет то быстрее, то медленнее; 90 км/ч — это <b>средняя</b> скорость.', 'A rate assumes the process runs evenly. In reality a car speeds up and slows down; 90 km/h is the <b>average</b> speed.'),
      L('Nega bo‘lish ishlaydi? Tasavvur qiling, 360 km yo‘lni 4 ta teng bo‘lakka — har bir soatga bittadan — ajratdik. Har bir bo‘lak bir xil uzunlikda bo‘lishi uchun 360 ni 4 ta teng qismga bo‘lamiz. Demak, me’yor topish aslida «teng taqsimlash» masalasi: jami miqdor birliklar o‘rtasida baravar bo‘lib chiqiladi. Shuning uchun me’yor topishni bo‘lishning eng tabiiy qo‘llanishi deyish mumkin.', 'Почему работает деление? Представьте, что 360 км пути мы разрезали на 4 равных куска — по одному на каждый час. Чтобы куски были одинаковыми, делим 360 на 4 равные части. Значит, нахождение нормы — по сути задача «разделить поровну»: общее количество распределяется между единицами поровну. Поэтому нахождение нормы можно назвать самым естественным применением деления.', 'Why does division work? Imagine cutting the 360 km journey into 4 equal pieces, one for each hour. For the pieces to be equal we divide 360 into 4 equal parts. So finding a rate is really an “equal sharing” problem: the total is shared out evenly among the units. That is why finding a rate is perhaps the most natural use of division.')
    ] },
    { kind: 'steps', h: L('Qadamma-qadam', 'Шаг за шагом', 'Step by step'), list: [
      L('1. Jami miqdorni toping (km, l, so‘m, bet…).', '1. Найдите общее количество (км, л, сум, стр…).', '1. Find the total (km, l, sum, pages…).'),
      L('2. Birliklar sonini toping (soat, minut, kg, kishi…).', '2. Найдите число единиц (часы, минуты, кг, люди…).', '2. Find the number of units (hours, minutes, kg, people…).'),
      L('3. Jamini birliklar soniga bo‘ling.', '3. Разделите общее количество на число единиц.', '3. Divide the total by the number of units.'),
      L('4. Me’yor birligini yozing: «jami birligi / bir birlik».', '4. Запишите единицу нормы: «единица общего / одна единица».', '4. Write the rate’s unit: “unit of the total / one unit”.'),
      L('5. Tekshiring: me’yor · birliklar soni = jami.', '5. Проверьте: норма · число единиц = общее количество.', '5. Check: rate · number of units = total.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir namunada avval jami miqdor va birliklar sonini aniqlaymiz, keyin bo‘lamiz va birlikni yozamiz. Oxirgi namuna eng muhimi: unda me’yor ikki xaridni taqqoslash uchun ishlatiladi. Bunday taqqoslash do‘konda har kuni kerak bo‘ladi, chunki ishlab chiqaruvchilar qadoqlarni turli o‘lchamlarda chiqaradi va qaysi biri foydali ekanini bir qarashda bilib bo‘lmaydi.', 'В каждом примере сначала определяем общее количество и число единиц, затем делим и пишем единицу. Последний пример самый важный: в нём норма помогает сравнить две покупки. Такое сравнение нужно в магазине каждый день, ведь производители выпускают упаковки разного размера, и с первого взгляда не понять, какая выгоднее.', 'In each example we first identify the total and the number of units, then divide and write the unit. The last example matters most: the rate is used to compare two purchases. You need that comparison in shops every day, because makers sell packs in different sizes and you cannot tell at a glance which is the better buy.')
    ], ex: [
      { q: L('Mashina 4 soatda 360 km yurdi. Uning tezligi?', 'Машина за 4 часа проехала 360 км. Её скорость?', 'A car went 360 km in 4 hours. Its speed?'), s: L('360 : 4 = 90. Tekshiruv: 90 · 4 = 360. Javob: <b>90 km/soat</b>.', '360 : 4 = 90. Проверка: 90 · 4 = 360. Ответ: <b>90 км/ч</b>.', '360 : 4 = 90. Check: 90 · 4 = 360. Answer: <b>90 km/h</b>.') },
      { q: L('Printer 6 minutda 150 bet chop etdi. Minutiga necha bet?', 'Принтер за 6 минут напечатал 150 страниц. Сколько страниц в минуту?', 'A printer printed 150 pages in 6 minutes. Pages per minute?'), s: L('150 : 6 = 25. Javob: <b>25 bet/min</b>.', '150 : 6 = 25. Ответ: <b>25 стр./мин</b>.', '150 : 6 = 25. Answer: <b>25 pages/min</b>.') },
      { q: L('3 kg guruch 37,5 ming so‘m. 1 kg narxi?', '3 кг риса стоят 37,5 тысячи сум. Цена 1 кг?', '3 kg of rice cost 37.5 thousand sum. Price of 1 kg?'), s: L('37,5 : 3 = 12,5. Javob: <b>12,5 ming so‘m/kg</b>, ya’ni 12 500 so‘m.', '37,5 : 3 = 12,5. Ответ: <b>12,5 тысячи сум/кг</b>, то есть 12 500 сум.', '37.5 : 3 = 12.5. Answer: <b>12.5 thousand sum/kg</b>, i.e. 12 500 sum.') },
      { q: L('Qaysi biri arzon: 2 kg 26 ming so‘mlik yoki 5 kg 60 ming so‘mlik qadoq?', 'Что дешевле: упаковка 2 кг за 26 тысяч или 5 кг за 60 тысяч сум?', 'Which is cheaper: a 2 kg pack for 26 thousand or a 5 kg pack for 60 thousand sum?'), s: L('Narxlarni bir kg ga keltiramiz: 26 : 2 = 13; 60 : 5 = 12. Javob: <b>5 kg li qadoq</b> arzon (12 ming so‘m/kg).', 'Приводим цены к 1 кг: 26 : 2 = 13; 60 : 5 = 12. Ответ: <b>упаковка 5 кг</b> дешевле (12 тысяч сум/кг).', 'Reduce to the price per kg: 26 : 2 = 13; 60 : 5 = 12. Answer: <b>the 5 kg pack</b> is cheaper (12 thousand sum/kg).') }
    ] },
    { kind: 'table', h: L('Me’yorlar jadvali', 'Таблица норм', 'Table of rates'), table: { head: [L('Vaziyat', 'Ситуация', 'Situation'), L('Hisob', 'Вычисление', 'Calculation'), L('Me’yor', 'Норма', 'Rate')], rows: [
      [L('Piyoda 2 soatda 9 km', 'Пешеход: 9 км за 2 ч', 'Walker: 9 km in 2 h'), '9 : 2', L('4,5 km/soat', '4,5 км/ч', '4.5 km/h')],
      [L('Kran 10 minutda 600 l', 'Кран: 600 л за 10 мин', 'Tap: 600 l in 10 min'), '600 : 10', L('60 l/min', '60 л/мин', '60 l/min')],
      [L('Mashina 300 km ga 24 l', 'Машина: 24 л на 300 км', 'Car: 24 l for 300 km'), '24 : 3', L('8 l/100 km', '8 л/100 км', '8 l/100 km')],
      [L('8 kishiga 2 kg go‘sht', 'Мясо: 2 кг на 8 человек', 'Meat: 2 kg for 8 people'), '2 : 8', L('0,25 kg/kishi', '0,25 кг/чел.', '0.25 kg/person')],
      [L('Yurak 1 minutda 72 marta', 'Сердце: 72 удара за минуту', 'Heart: 72 beats in a minute'), '72 : 1', L('72 zarba/min', '72 уд./мин', '72 beats/min')]
    ] }, after: [
      L('Uchinchi qatorga e’tibor bering: yoqilg‘i sarfi odatda 100 km ga hisoblanadi. 300 km — bu uchta 100 km, shuning uchun 24 ni 3 ga bo‘ldik.', 'Обратите внимание на третью строку: расход топлива обычно считают на 100 км. 300 км — это три раза по 100 км, поэтому 24 делим на 3.', 'Look at the third row: fuel use is usually given per 100 km. 300 km is three lots of 100 km, so we divided 24 by 3.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Teskari bo‘lish.</b> 4 : 360 deb hisoblash. Qaysi kattalik «bir birlikka» to‘g‘ri kelishini so‘rang — u bo‘luvchi bo‘ladi.', '<b>Деление наоборот.</b> Вычислить 4 : 360. Спросите себя, «на единицу» чего считаем, — это и будет делитель.', '<b>Dividing the wrong way.</b> Working out 4 : 360. Ask which quantity we want “per one” of — that is the divisor.'),
      L('<b>Birliksiz javob.</b> «90» — bu nima? 90 km/soat, 90 so‘m yoki 90 bet? Me’yorning birligi javobning yarmi.', '<b>Ответ без единицы.</b> «90» — это что? 90 км/ч, 90 сум или 90 страниц? Единица нормы — половина ответа.', '<b>No unit.</b> “90” of what? 90 km/h, 90 sum or 90 pages? The unit is half the answer.'),
      L('<b>Jami bilan me’yorni taqqoslash.</b> «Bekzod ko‘p terdi, demak tez terdi» — xato. Taqqoslash faqat me’yorlar orqali adolatli.', '<b>Сравнение общего, а не нормы.</b> «Бекзод собрал больше, значит, быстрее» — ошибка. Честно сравнивать можно только нормы.', '<b>Comparing totals instead of rates.</b> “Bekzod picked more, so he was faster” is wrong. Only rates give a fair comparison.'),
      L('<b>Har xil vaqt birliklari.</b> 30 minutda 2 km — 2 : 30 emas, agar km/soat kerak bo‘lsa. 30 min = 0,5 soat, 2 : 0,5 = 4 km/soat (yoki 2 · 2 = 4).', '<b>Разные единицы времени.</b> 2 км за 30 минут — не 2 : 30, если нужны км/ч. 30 мин = 0,5 ч, 2 : 0,5 = 4 км/ч (или 2 · 2 = 4).', '<b>Mixed time units.</b> 2 km in 30 minutes is not 2 : 30 if km/h is wanted. 30 min = 0.5 h, so 2 : 0.5 = 4 km/h (or 2 · 2 = 4).')
    ] },
    { kind: 'life', h: L('Hayotda me’yor', 'Норма в жизни', 'Rates in life'), p: [
      L('<b>Xarid.</b> Do‘konlarda narx yorlig‘ida ko‘pincha kichik harflar bilan «1 kg narxi» yoki «1 l narxi» yoziladi. Bu — me’yor. Uning yordamida turli hajmdagi qadoqlarni adolatli taqqoslaysiz: katta qadoq har doim ham arzon emas!', '<b>Покупки.</b> На ценниках часто мелким шрифтом пишут «цена за 1 кг» или «цена за 1 л». Это и есть норма. С её помощью честно сравнивают упаковки разного объёма: большая упаковка не всегда дешевле!', '<b>Shopping.</b> Price labels often show, in small print, the “price per 1 kg” or “per 1 l”. That is a rate. It lets you compare packs of different sizes fairly: the big pack is not always cheaper!'),
      L('<b>Sog‘liq.</b> Shifokor yurak urishini minutiga sanaydi: 10–11 yoshli bolada odatda 70–100 zarba/min. Nafas olish ham me’yor: minutiga 18–20 marta.', '<b>Здоровье.</b> Врач считает пульс в минуту: у ребёнка 10–11 лет обычно 70–100 ударов/мин. Дыхание — тоже норма: 18–20 вдохов в минуту.', '<b>Health.</b> A doctor counts heartbeats per minute: for a 10–11-year-old it is usually 70–100 beats/min. Breathing is a rate too: 18–20 breaths a minute.'),
      L('<b>Internet.</b> Internet tezligi «Mbit/s» da o‘lchanadi — sekundiga necha megabit ma’lumot keladi. 100 Mbit/s tezlikda 500 megabitlik video 5 sekundda yuklanadi.', '<b>Интернет.</b> Скорость интернета измеряют в «Мбит/с» — сколько мегабит данных приходит в секунду. При 100 Мбит/с видео в 500 мегабит загрузится за 5 секунд.', '<b>Internet.</b> Connection speed is measured in “Mbit/s”, megabits of data per second. At 100 Mbit/s a 500-megabit video downloads in 5 seconds.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('Gepard — eng tez quruqlik hayvoni: qisqa masofada soatiga 100 km dan ortiq tezlikka erisha oladi. Shilliqqurt esa soatiga taxminan 0,05 km, ya’ni 50 metr yuradi.', 'Гепард — самое быстрое сухопутное животное: на короткой дистанции он развивает больше 100 км/ч. А улитка проползает около 0,05 км в час, то есть 50 метров.', 'The cheetah is the fastest land animal: over short distances it can exceed 100 km/h. A snail manages about 0.05 km an hour, that is 50 metres.'),
      L('Yer Quyosh atrofida sekundiga taxminan 30 km tezlikda aylanadi. Siz bu gapni o‘qigan 5 sekund ichida biz koinotda 150 km yo‘l bosib o‘tdik!', 'Земля движется вокруг Солнца со скоростью около 30 км в секунду. За 5 секунд, пока вы читали эту фразу, мы пролетели в космосе 150 км!', 'The Earth orbits the Sun at about 30 km per second. In the 5 seconds you spent reading this sentence, we travelled 150 km through space!')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('Velosipedchi 3 soatda 42 km yurdi. Tezligi?', 'Велосипедист проехал 42 км за 3 часа. Его скорость?', 'A cyclist rode 42 km in 3 hours. Speed?'),
      L('6 ta bir xil kitob 54 ming so‘m. Bittasi qancha?', '6 одинаковых книг стоят 54 тысячи сум. Сколько стоит одна?', '6 identical books cost 54 thousand sum. How much is one?'),
      L('Qaysi biri tezroq yozadi: 20 minutda 600 so‘z yozgan Malika yoki 15 minutda 480 so‘z yozgan Nodira?', 'Кто печатает быстрее: Малика — 600 слов за 20 минут, или Нодира — 480 слов за 15 минут?', 'Who types faster: Malika with 600 words in 20 minutes or Nodira with 480 words in 15 minutes?')
    ], after: [
      L('Javoblar: 14 km/soat; 9 ming so‘m; Malika — 30 so‘z/min, Nodira — 32 so‘z/min, Nodira tezroq.', 'Ответы: 14 км/ч; 9 тысяч сум; Малика — 30 слов/мин, Нодира — 32 слова/мин, Нодира быстрее.', 'Answers: 14 km/h; 9 thousand sum; Malika 30 words/min, Nodira 32 words/min, so Nodira is faster.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Me’yor — bir birlikka to‘g‘ri keladigan miqdor.', 'Норма — величина, приходящаяся на одну единицу.', 'A rate is the amount per one unit.'),
      L('Me’yor = jami : birliklar soni.', 'Норма = всего : число единиц.', 'Rate = total : number of units.'),
      L('Birligi kasr chizig‘i bilan: km/soat, so‘m/kg, l/min.', 'Единица — через черту: км/ч, сум/кг, л/мин.', 'Its unit uses a slash: km/h, sum/kg, l/min.'),
      L('Turli vaziyatlarni faqat me’yor orqali adolatli taqqoslash mumkin.', 'Разные ситуации честно сравнивают только по нормам.', 'Different situations can be compared fairly only through rates.'),
      L('Tekshiruv: me’yor · birliklar soni = jami.', 'Проверка: норма · число единиц = всего.', 'Check: rate · number of units = total.')
    ] }
  ] });

  // ---------- t6. Me’yorga ko‘ra jami va birliklar soni ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Me’yor ma’lum — qolgani oson', 'Норма известна — остальное просто', 'Know the rate, and the rest is easy'), p: [
      L('O‘tgan mavzuda me’yorni topdik: jamini birliklar soniga bo‘ldik. Endi teskari savollar: printer minutiga 25 bet chop etsa, 12 minutda necha bet chiqaradi? 300 betni chop etishga necha minut kerak? Bu savollarga javob berish uchun me’yor, jami va birliklar soni orasidagi bog‘lanishni bilish kifoya.', 'В прошлой теме мы находили норму: делили общее количество на число единиц. Теперь обратные вопросы: если принтер печатает 25 страниц в минуту, сколько страниц он напечатает за 12 минут? Сколько минут нужно на 300 страниц? Для ответа достаточно знать связь между нормой, общим количеством и числом единиц.', 'In the last topic we found a rate by dividing a total by the number of units. Now the reverse questions: if a printer prints 25 pages a minute, how many pages does it print in 12 minutes? How many minutes does it need for 300 pages? To answer, we only need the link between the rate, the total and the number of units.'),
      L('Bu uchlik — matematikaning eng foydali «uchburchagi». Undagi istalgan ikki kattalik ma’lum bo‘lsa, uchinchisini topish mumkin. Oshpaz, quruvchi, haydovchi, dasturchi — hamma kuniga bir necha marta shunday hisob qiladi.', 'Эта тройка — самый полезный «треугольник» математики. Зная любые две величины, можно найти третью. Повар, строитель, водитель, программист — все считают так по несколько раз в день.', 'This trio is the most useful “triangle” in maths. Knowing any two quantities, you can find the third. Cooks, builders, drivers and programmers all do this sort of calculation several times a day.')
    ] },
    { kind: 'def', h: L('Uch kattalik', 'Три величины', 'Three quantities'), p: [
      L('Har bir me’yorli masalada uchta kattalik qatnashadi:', 'В каждой задаче на норму участвуют три величины:', 'Every rate problem involves three quantities:')
    ], list: [
      L('<b>Me’yor</b> — bir birlikka qancha (25 bet/min).', '<b>Норма</b> — сколько на одну единицу (25 стр./мин).', '<b>Rate</b> — how much per unit (25 pages/min).'),
      L('<b>Birliklar soni</b> — nechta birlik (12 minut).', '<b>Число единиц</b> — сколько единиц (12 минут).', '<b>Number of units</b> — how many units (12 minutes).'),
      L('<b>Jami miqdor</b> — hammasi bo‘lib qancha (300 bet).', '<b>Общее количество</b> — сколько всего (300 страниц).', '<b>Total</b> — how much altogether (300 pages).')
    ], after: [
      L('Ular quyidagi tenglik bilan bog‘langan: <b>jami = me’yor · birliklar soni</b>. Ko‘paytirish va bo‘lish bir-biriga teskari bo‘lgani uchun qolgan ikki formula shundan kelib chiqadi.', 'Они связаны равенством: <b>всего = норма · число единиц</b>. Так как умножение и деление — обратные действия, две другие формулы следуют отсюда.', 'They are linked by the equation <b>total = rate · number of units</b>. Since multiplication and division undo each other, the other two formulas follow from it.'),
      L('Yodda tutish uchun «uchburchak» chizing: tepada — jami, pastda — me’yor va son. Topmoqchi bo‘lgan kattalikni yoping: qolgan ikkitasi yonma-yon bo‘lsa — ko‘paytiring, biri ustida bo‘lsa — bo‘ling.', 'Чтобы запомнить, нарисуйте «треугольник»: вверху — всего, внизу — норма и число. Закройте искомую величину: если оставшиеся стоят рядом — умножайте, если одна над другой — делите.', 'To remember, draw a “triangle”: total on top, rate and number below. Cover the quantity you want: if the remaining two sit side by side, multiply; if one is above the other, divide.')
    ] },
    { kind: 'history', h: L('Qadimgi ustalar hisobi', 'Счёт древних мастеров', 'How ancient builders counted'), p: [
      L('Samarqanddagi Registon maydoni madrasalari va Bibixonim masjidi qurilganda me’morlar ishchilar soni, kunlik me’yor va kerakli g‘ishtlar sonini oldindan hisoblashlari kerak edi. Tarixchilarning yozishicha, Amir Temur Bibixonim masjidini tez qurish uchun yuzlab ustalarni yig‘gan.', 'При строительстве медресе на площади Регистан и мечети Биби-Ханым в Самарканде зодчим нужно было заранее рассчитать число работников, дневную норму и количество кирпичей. По словам историков, Амир Темур собрал сотни мастеров, чтобы быстро построить мечеть Биби-Ханым.', 'When the madrasas of the Registan and the Bibi-Khanym Mosque were built in Samarkand, architects had to work out in advance the number of workers, the daily rate and how many bricks were needed. Historians write that Amir Temur gathered hundreds of craftsmen to build the Bibi-Khanym Mosque quickly.'),
      L('<b>Al-Koshiy</b> «Hisob kaliti» kitobida qurilish uchun g‘isht va ohak miqdorini hisoblash usullarini yozgan. Uning masalalari aynan «bir birlikka qancha — jami qancha» tipida edi.', 'В «Ключе арифметики» <b>аль-Каши</b> описал способы расчёта количества кирпича и извести для строительства. Его задачи были как раз типа «сколько на единицу — сколько всего».', 'In “The Key to Arithmetic” <b>al-Kashi</b> described ways to calculate the amount of brick and lime for building. His problems were exactly of the “how much per unit — how much in all” kind.'),
      L('XX asr boshida Genri Ford avtomobil zavodida konveyer joriy qildi: bitta mashinani yig‘ish vaqti 12 soatdan taxminan 1,5 soatga qisqardi. Zavodlar hali ham «soatiga necha dona» me’yori bilan ishlaydi.', 'В начале XX века Генри Форд ввёл на автомобильном заводе конвейер: время сборки одной машины сократилось с 12 часов примерно до 1,5 часа. Заводы до сих пор работают по норме «сколько штук в час».', 'In the early 20th century Henry Ford introduced the assembly line in his car factory: the time to build one car fell from 12 hours to about 1.5 hours. Factories still work to a “how many per hour” rate.')
    ] },
    { kind: 'rule', h: L('Ikki formula', 'Две формулы', 'Two formulas'), list: [
      L('<b>Jami = me’yor · birliklar soni.</b> Printer minutiga 25 bet: 12 minutda 25 · 12 = 300 bet.', '<b>Всего = норма · число единиц.</b> Принтер — 25 стр./мин: за 12 минут 25 · 12 = 300 страниц.', '<b>Total = rate · number of units.</b> Printer at 25 pages/min: in 12 minutes 25 · 12 = 300 pages.'),
      L('<b>Birliklar soni = jami : me’yor.</b> 300 betni 25 betdan: 300 : 25 = 12 minut.', '<b>Число единиц = всего : норма.</b> 300 страниц по 25 в минуту: 300 : 25 = 12 минут.', '<b>Number of units = total : rate.</b> 300 pages at 25 a minute: 300 : 25 = 12 minutes.'),
      L('<b>Me’yor = jami : birliklar soni</b> (o‘tgan mavzu): 300 : 12 = 25 bet/min.', '<b>Норма = всего : число единиц</b> (прошлая тема): 300 : 12 = 25 стр./мин.', '<b>Rate = total : number of units</b> (last topic): 300 : 12 = 25 pages/min.')
    ], after: [
      L('Uchala formula aslida bitta tenglikning uch ko‘rinishi. Bittasini yaxshi bilsangiz, qolganlarini teskari amal orqali tiklaysiz.', 'Все три формулы — это три вида одного равенства. Зная одну, остальные восстановите через обратное действие.', 'All three formulas are three faces of one equation. Know one well and you can recover the others by the inverse operation.')
    ] },
    { kind: 'steps', h: L('Qaysi formulani tanlash?', 'Какую формулу выбрать?', 'Which formula?'), list: [
      L('1. Masaladagi me’yorni toping: «har biriga», «har soatda», «… dan» so‘zlari yonidagi son.', '1. Найдите в задаче норму: число рядом со словами «на каждого», «в час», «по …».', '1. Find the rate: the number next to words like “each”, “per hour”, “… a time”.'),
      L('2. Nima so‘ralayotganini aniqlang: «hammasi qancha?» — jami; «nechta?», «necha soat?» — birliklar soni.', '2. Определите, что спрашивают: «сколько всего?» — общее; «сколько штук?», «сколько часов?» — число единиц.', '2. Decide what is asked: “how much in all?” — the total; “how many?”, “how many hours?” — the number of units.'),
      L('3. Jami so‘ralsa — ko‘paytiring; birliklar soni so‘ralsa — bo‘ling.', '3. Спрашивают общее — умножайте; число единиц — делите.', '3. If the total is asked, multiply; if the number of units, divide.'),
      L('4. Birliklar mosligini tekshiring (minut va soat, gramm va kilogramm).', '4. Проверьте соответствие единиц (минуты и часы, граммы и килограммы).', '4. Check the units match (minutes and hours, grams and kilograms).'),
      L('5. Javobni teskari amal bilan tekshiring.', '5. Проверьте ответ обратным действием.', '5. Check the answer with the inverse operation.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir masalada avval me’yorni topamiz, keyin savolga qaraymiz: jami so‘ralyaptimi yoki birliklar soni? To‘rtinchi namunada ikki bosqichli zanjir bor: avval bir kunlik oilaviy me’yorni topamiz, keyin uni kunlar soniga ko‘paytiramiz. Shu tarzda murakkab masala ikki oddiy masalaga ajraladi. Yechimni yozganda har bir qadamga izoh bering — bu xatoni topishni osonlashtiradi.', 'В каждой задаче сначала находим норму, затем смотрим на вопрос: спрашивают общее или число единиц? В четвёртом примере цепочка из двух шагов: сначала находим дневную норму для семьи, затем умножаем на число дней. Так сложная задача распадается на две простые. Записывая решение, поясняйте каждый шаг — так легче найти ошибку.', 'In each problem we first find the rate, then look at the question: is it asking for the total or the number of units? The fourth example has a two-step chain: first the family’s daily amount, then multiply by the number of days. That way a harder problem splits into two simple ones. When writing a solution, label each step — it makes mistakes easier to spot.')
    ], ex: [
      { q: L('Avtobus soatiga 60 km tezlikda 3,5 soat yurdi. Qancha yo‘l bosdi?', 'Автобус ехал 3,5 часа со скоростью 60 км/ч. Какой путь он проехал?', 'A bus travelled for 3.5 hours at 60 km/h. How far did it go?'), s: L('Jami = me’yor · son: 60 · 3,5 = 210. Javob: <b>210 km</b>.', 'Всего = норма · число: 60 · 3,5 = 210. Ответ: <b>210 км</b>.', 'Total = rate · number: 60 · 3.5 = 210. Answer: <b>210 km</b>.') },
      { q: L('Har bir shishaga 0,5 l sharbat quyiladi. 12 l sharbatga nechta shisha kerak?', 'В каждую бутылку наливают 0,5 л сока. Сколько бутылок нужно для 12 л?', 'Each bottle takes 0.5 l of juice. How many bottles for 12 l?'), s: L('Son = jami : me’yor: 12 : 0,5 = 24 (yarim litrdan — har litrga 2 ta, 12 · 2 = 24). Javob: <b>24 ta shisha</b>.', 'Число = всего : норма: 12 : 0,5 = 24 (по пол-литра — на каждый литр 2 бутылки, 12 · 2 = 24). Ответ: <b>24 бутылки</b>.', 'Number = total : rate: 12 : 0.5 = 24 (half a litre each means 2 bottles per litre, 12 · 2 = 24). Answer: <b>24 bottles</b>.') },
      { q: L('Ishchi soatiga 18 ta detal yasaydi. 144 ta detalni necha soatda yasaydi?', 'Рабочий делает 18 деталей в час. За сколько часов он сделает 144 детали?', 'A worker makes 18 parts an hour. How many hours for 144 parts?'), s: L('144 : 18 = 8. Tekshiruv: 18 · 8 = 144. Javob: <b>8 soat</b>.', '144 : 18 = 8. Проверка: 18 · 8 = 144. Ответ: <b>8 часов</b>.', '144 : 18 = 8. Check: 18 · 8 = 144. Answer: <b>8 hours</b>.') },
      { q: L('Bir kishiga kuniga 2,5 l suv kerak. 4 kishilik oila 7 kunlik sayohatga qancha suv olishi kerak?', 'Одному человеку нужно 2,5 л воды в день. Сколько воды взять семье из 4 человек на 7 дней?', 'One person needs 2.5 l of water a day. How much should a family of 4 take for 7 days?'), s: L('1) Oilaga kuniga: 2,5 · 4 = 10 l. 2) 7 kunga: 10 · 7 = 70 l. Javob: <b>70 l</b>.', '1) Семье в день: 2,5 · 4 = 10 л. 2) На 7 дней: 10 · 7 = 70 л. Ответ: <b>70 л</b>.', '1) Family per day: 2.5 · 4 = 10 l. 2) For 7 days: 10 · 7 = 70 l. Answer: <b>70 l</b>.') }
    ] },
    { kind: 'table', h: L('Uchlik jadvali', 'Таблица троек', 'Table of trios'), table: { head: [L('Me’yor', 'Норма', 'Rate'), L('Birliklar soni', 'Число единиц', 'Number of units'), L('Jami', 'Всего', 'Total')], rows: [
      [L('75 km/soat', '75 км/ч', '75 km/h'), L('4 soat', '4 ч', '4 h'), L('<b>300 km</b>', '<b>300 км</b>', '<b>300 km</b>')],
      [L('12 bet/kun', '12 стр./день', '12 pages/day'), L('<b>15 kun</b>', '<b>15 дней</b>', '<b>15 days</b>'), L('180 bet', '180 стр.', '180 pages')],
      [L('<b>8 ming so‘m/kg</b>', '<b>8 тыс. сум/кг</b>', '<b>8 thousand sum/kg</b>'), L('6 kg', '6 кг', '6 kg'), L('48 ming so‘m', '48 тыс. сум', '48 thousand sum')],
      [L('0,2 kg/kishi', '0,2 кг/чел.', '0.2 kg/person'), L('30 kishi', '30 чел.', '30 people'), L('<b>6 kg</b>', '<b>6 кг</b>', '<b>6 kg</b>')],
      [L('40 l/min', '40 л/мин', '40 l/min'), L('<b>25 min</b>', '<b>25 мин</b>', '<b>25 min</b>'), L('1000 l', '1000 л', '1000 l')]
    ] }, after: [
      L('Har bir qatorda qalin yozilgan kattalik qolgan ikkitasidan topilgan. Har birini o‘zingiz tekshiring: jami bo‘lsa — ko‘paytirish, qolganlari — bo‘lish.', 'В каждой строке величина, выделенная жирным, найдена по двум другим. Проверьте каждую сами: общее — умножением, остальные — делением.', 'In each row the bold quantity was found from the other two. Check each yourself: the total by multiplying, the others by dividing.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Amalni adashtirish.</b> «300 betga necha minut?» savolida 300 · 25 = 7500 minut deb yozish. 5 kunlik ishdan ko‘p — javob bema’ni! Birliklar soni so‘ralsa — bo‘lamiz.', '<b>Путаница действий.</b> На вопрос «сколько минут на 300 страниц?» ответить 300 · 25 = 7500 минут. Это больше 5 суток — ответ абсурден! Спрашивают число единиц — делим.', '<b>Wrong operation.</b> Answering “how many minutes for 300 pages?” with 300 · 25 = 7500 minutes. That is over 5 days — absurd! For the number of units, divide.'),
      L('<b>Birliklar mos emas.</b> Nasos minutiga 40 l, 2 soat ishladi: 40 · 2 = 80 l — xato. 2 soat = 120 minut, 40 · 120 = 4800 l.', '<b>Единицы не согласованы.</b> Насос — 40 л/мин, работал 2 часа: 40 · 2 = 80 л — ошибка. 2 ч = 120 мин, 40 · 120 = 4800 л.', '<b>Units do not match.</b> A pump at 40 l/min runs for 2 hours: 40 · 2 = 80 l is wrong. 2 h = 120 min, 40 · 120 = 4800 l.'),
      L('<b>Qoldiqni hisobga olmaslik.</b> 50 o‘quvchini 12 o‘rinli mikroavtobuslarga joylash: 50 : 12 ≈ 4,17. Javob 4 emas, <b>5 ta</b> avtobus — aks holda 2 bola qolib ketadi!', '<b>Забыть про остаток.</b> Рассадить 50 учеников в микроавтобусы по 12 мест: 50 : 12 ≈ 4,17. Ответ не 4, а <b>5</b> автобусов — иначе 2 ребёнка останутся!', '<b>Ignoring the remainder.</b> Seating 50 pupils in 12-seat minibuses: 50 : 12 ≈ 4.17. The answer is not 4 but <b>5</b> buses, or 2 children are left behind!'),
      L('<b>Noto‘g‘ri yaxlitlash.</b> Teskari holat ham bor: 50 m matodan 12 m li parda tikilsa, 4 ta parda chiqadi, 5 ta emas — beshinchiga mato yetmaydi. Shuning uchun har safar savol beramiz: ortib qolgan qism foydalimi yoki yo‘qmi?', '<b>Неверное округление.</b> Бывает и наоборот: из 50 м ткани шьют шторы по 12 м — выйдет 4 шторы, а не 5: на пятую ткани не хватит. Поэтому каждый раз спрашиваем себя: пригодится ли остаток?', '<b>Rounding the wrong way.</b> The opposite also happens: curtains of 12 m from 50 m of cloth give 4 curtains, not 5 — there is not enough cloth for a fifth. So each time ask: is the leftover part useful or not?')
    ], after: [
      L('Eng ishonchli himoya — javobni hayotiy tasavvur bilan solishtirish. Printer bir kunda 7500 minut ishlay olmaydi; oila haftaga 7 litr emas, o‘nlab litr suv ichadi; 5 ta avtobusda 50 bola sig‘adi, 4 tasida sig‘maydi. Agar javob g‘alati tuyulsa, qaysi formulani tanlaganingizni qayta ko‘rib chiqing va birliklarni tekshiring. Ko‘pincha xato bitta: ko‘paytirish o‘rniga bo‘lish yoki aksincha.', 'Самая надёжная защита — сравнить ответ с жизненным представлением. Принтер не может работать 7500 минут за день; семья выпивает за неделю не 7 литров, а десятки; в 5 автобусов 50 детей помещаются, в 4 — нет. Если ответ кажется странным, пересмотрите выбор формулы и проверьте единицы. Чаще всего ошибка одна: деление вместо умножения или наоборот.', 'The surest protection is to compare the answer with real life. A printer cannot run for 7500 minutes in a day; a family drinks not 7 litres a week but dozens; 50 children fit into 5 buses but not 4. If an answer looks odd, review which formula you chose and check the units. Usually the slip is just one: dividing instead of multiplying, or the other way round.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in life'), p: [
      L('<b>Ta’mirlash.</b> Bir litr bo‘yoq 8 m<sup>2</sup> devorga yetadi. Xona devorlari 48 m<sup>2</sup> bo‘lsa, 48 : 8 = 6 l bo‘yoq kerak. Ikki qavat bo‘yasak — 12 l.', '<b>Ремонт.</b> Одного литра краски хватает на 8 м<sup>2</sup> стены. Если стены комнаты — 48 м<sup>2</sup>, нужно 48 : 8 = 6 л. В два слоя — 12 л.', '<b>Decorating.</b> One litre of paint covers 8 m<sup>2</sup> of wall. If a room’s walls are 48 m<sup>2</sup>, you need 48 : 8 = 6 l. Two coats: 12 l.'),
      L('<b>Ovqat tayyorlash.</b> Retseptda 4 kishiga 0,6 kg go‘sht — bir kishiga 0,15 kg. 10 mehmon kelsa: 0,15 · 10 = 1,5 kg.', '<b>Готовка.</b> В рецепте 0,6 кг мяса на 4 человек — 0,15 кг на одного. Если придут 10 гостей: 0,15 · 10 = 1,5 кг.', '<b>Cooking.</b> A recipe uses 0.6 kg of meat for 4 people, so 0.15 kg each. For 10 guests: 0.15 · 10 = 1.5 kg.'),
      L('<b>Telefon.</b> Telefon zaryadi soatiga 12% kamaysa, to‘liq zaryad 100 : 12 ≈ 8 soatga yetadi. Videoni ko‘rganda sarf oshadi — me’yor o‘zgaradi.', '<b>Телефон.</b> Если заряд телефона уменьшается на 12% в час, полного заряда хватит на 100 : 12 ≈ 8 часов. При просмотре видео расход растёт — норма меняется.', '<b>Phone.</b> If a phone loses 12% charge an hour, a full battery lasts 100 : 12 ≈ 8 hours. Watching video uses more — the rate changes.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('Asalari 1 kg asal yig‘ish uchun gullar orasida taxminan 150 000 km uchadi — Yer ekvatori bo‘ylab 3,7 marta aylanib chiqqandek! Bitta asalari umri davomida bir choy qoshig‘ining o‘ndan biricha asal yig‘adi.', 'Чтобы собрать 1 кг мёда, пчёлы пролетают между цветами около 150 000 км — словно облетают Землю по экватору 3,7 раза! Одна пчела за всю жизнь собирает около десятой части чайной ложки мёда.', 'To gather 1 kg of honey, bees fly about 150 000 km between flowers — like circling the Earth at the equator 3.7 times! A single bee makes about a tenth of a teaspoon of honey in its whole life.'),
      L('Inson yuragi minutiga o‘rtacha 70 marta urib, kuniga 70 · 60 · 24 = 100 800 marta uradi. Bir yilda bu 36 milliondan ortiq zarba!', 'Сердце человека бьётся в среднем 70 раз в минуту, а в сутки — 70 · 60 · 24 = 100 800 раз. За год это больше 36 миллионов ударов!', 'A human heart beats about 70 times a minute, so 70 · 60 · 24 = 100 800 times a day. In a year that is over 36 million beats!')
    ] },
    { kind: 'practice', h: L('O‘zingiz yeching', 'Решите сами', 'Try it yourself'), list: [
      L('Poyezd soatiga 80 km yuradi. 520 km ni necha soatda o‘tadi?', 'Поезд идёт 80 км/ч. За сколько часов он пройдёт 520 км?', 'A train runs at 80 km/h. How many hours for 520 km?'),
      L('Har bir qutiga 24 ta tuxum sig‘adi. 15 qutida nechta tuxum?', 'В коробку помещается 24 яйца. Сколько яиц в 15 коробках?', 'A box holds 24 eggs. How many eggs are in 15 boxes?'),
      L('Lola kuniga 35 bet o‘qiydi. 280 betli kitobni necha kunda tugatadi?', 'Лола читает 35 страниц в день. За сколько дней она прочтёт книгу в 280 страниц?', 'Lola reads 35 pages a day. How many days for a 280-page book?')
    ], after: [
      L('Javoblar: 6,5 soat; 360 ta; 8 kun.', 'Ответы: 6,5 часа; 360 яиц; 8 дней.', 'Answers: 6.5 hours; 360 eggs; 8 days.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Uch kattalik: me’yor, birliklar soni, jami.', 'Три величины: норма, число единиц, всего.', 'Three quantities: rate, number of units, total.'),
      L('Jami = me’yor · birliklar soni.', 'Всего = норма · число единиц.', 'Total = rate · number of units.'),
      L('Birliklar soni = jami : me’yor.', 'Число единиц = всего : норма.', 'Number of units = total : rate.'),
      L('Birliklarni avval moslashtiring (soat ↔ minut).', 'Сначала согласуйте единицы (часы ↔ минуты).', 'Match the units first (hours ↔ minutes).'),
      L('Qoldiq bo‘lsa, mazmunga qarab yaxlitlang (avtobuslar soni — yuqoriga).', 'Если есть остаток, округляйте по смыслу (число автобусов — вверх).', 'With a remainder, round by meaning (number of buses — round up).'),
      L('Teskari amal bilan tekshiring.', 'Проверяйте обратным действием.', 'Check with the inverse operation.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-2';

  // ---------- t7. Foiz tushunchasi ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Hamma joyda «%» belgisi', 'Знак «%» повсюду', 'The “%” sign is everywhere'), p: [
      L('Telefoningiz ekranida «zaryad 64%», do‘kon oynasida «chegirma 30%», ob-havo xabarida «yomg‘ir ehtimoli 80%», sut qutisida «yog‘liligi 3,2%». Bu belgi shunchalik ko‘p uchraydiki, uni tushunmasdan zamonaviy hayotda yashash qiyin. Xo‘sh, foiz nima va nega odamlar uni bunchalik yaxshi ko‘radi?', 'На экране телефона «заряд 64%», на витрине «скидка 30%», в прогнозе погоды «вероятность дождя 80%», на пакете молока «жирность 3,2%». Этот знак встречается так часто, что без него трудно жить в современном мире. Так что же такое процент и почему люди так его любят?', 'Your phone says “battery 64%”, a shop window says “30% off”, the forecast says “80% chance of rain”, a milk carton says “3.2% fat”. The sign is so common that modern life is hard without understanding it. So what is a percent, and why do people like it so much?'),
      L('Sababi oddiy: foiz — turli narsalarni <b>bitta umumiy o‘lchov</b> bilan taqqoslash usuli. 25 ta o‘quvchidan 20 tasi va 40 ta o‘quvchidan 30 tasi imtihondan o‘tdi — qaysi sinf yaxshiroq? Kasrlarda bu qiyin, foizda esa darhol ko‘rinadi: 80% va 75%.', 'Причина проста: процент — способ сравнивать разные вещи <b>одной общей меркой</b>. Из 25 учеников экзамен сдали 20, из 40 — 30. Какой класс лучше? В дробях это трудно, а в процентах сразу видно: 80% и 75%.', 'The reason is simple: a percent lets us compare different things by <b>one common yardstick</b>. In one class 20 of 25 pupils passed an exam, in another 30 of 40. Which did better? Hard to see with fractions, obvious with percentages: 80% versus 75%.'),
      L('Bu mavzuda foizning ta’rifini, uning oddiy kasr va o‘nli kasr bilan bog‘lanishini, bir ko‘rinishdan boshqasiga o‘tishni o‘rganamiz.', 'В этой теме изучим определение процента, его связь с обыкновенной и десятичной дробью и переход от одной записи к другой.', 'In this topic we learn what a percent is, how it relates to fractions and decimals, and how to switch between the three forms.')
    ] },
    { kind: 'def', h: L('Foiz ta’rifi', 'Определение процента', 'What a percent is'), p: [
      L('<b>Foiz</b> (lotincha <i>per centum</i> — «yuzdan») — sonning yuzdan bir qismi. 1% = <sup>1</sup>/<sub>100</sub> = 0,01. Butun narsa 100% deb olinadi.', '<b>Процент</b> (лат. <i>per centum</i> — «на сотню») — одна сотая часть числа. 1% = <sup>1</sup>/<sub>100</sub> = 0,01. Всё целое принимают за 100%.', 'A <b>percent</b> (Latin <i>per centum</i>, “per hundred”) is one hundredth of a quantity. 1% = <sup>1</sup>/<sub>100</sub> = 0.01. The whole is taken as 100%.'),
      L('100 ta katakli kvadratni tasavvur qiling. Har bir katak — butunning 1%. 35 ta katak bo‘yalgan bo‘lsa — kvadratning 35% i bo‘yalgan. Hammasi bo‘yalsa — 100%, birortasi ham bo‘yalmasa — 0%.', 'Представьте квадрат из 100 клеток. Каждая клетка — 1% целого. Если закрашено 35 клеток — закрашено 35% квадрата. Все — 100%, ни одной — 0%.', 'Picture a square of 100 cells. Each cell is 1% of the whole. If 35 cells are shaded, 35% of the square is shaded. All of them: 100%; none: 0%.')
    ], list: [
      L('50% = <sup>50</sup>/<sub>100</sub> = <sup>1</sup>/<sub>2</sub> — yarmi.', '50% = <sup>50</sup>/<sub>100</sub> = <sup>1</sup>/<sub>2</sub> — половина.', '50% = <sup>50</sup>/<sub>100</sub> = <sup>1</sup>/<sub>2</sub> — a half.'),
      L('25% = <sup>1</sup>/<sub>4</sub> — chorak; 75% = <sup>3</sup>/<sub>4</sub>.', '25% = <sup>1</sup>/<sub>4</sub> — четверть; 75% = <sup>3</sup>/<sub>4</sub>.', '25% = <sup>1</sup>/<sub>4</sub> — a quarter; 75% = <sup>3</sup>/<sub>4</sub>.'),
      L('10% = <sup>1</sup>/<sub>10</sub>; 20% = <sup>1</sup>/<sub>5</sub>; 1% = <sup>1</sup>/<sub>100</sub>.', '10% = <sup>1</sup>/<sub>10</sub>; 20% = <sup>1</sup>/<sub>5</sub>; 1% = <sup>1</sup>/<sub>100</sub>.', '10% = <sup>1</sup>/<sub>10</sub>; 20% = <sup>1</sup>/<sub>5</sub>; 1% = <sup>1</sup>/<sub>100</sub>.')
    ], after: [
      L('Foiz 100% dan katta ham bo‘lishi mumkin: agar narx ikki baravar oshsa, yangi narx eskisining 200% i bo‘ladi. 150% — bu bir yarim barobar.', 'Процент может быть и больше 100%: если цена выросла вдвое, новая цена — 200% старой. 150% — это в полтора раза.', 'A percentage can exceed 100%: if a price doubles, the new price is 200% of the old one. 150% means one and a half times.')
    ] },
    { kind: 'history', h: L('«%» belgisi qanday paydo bo‘lgan?', 'Как появился знак «%»?', 'How did the “%” sign appear?'), p: [
      L('Yuzga nisbatan hisoblash Qadimgi Rimda ham bo‘lgan: imperator Avgust sotilgan tovarlardan <sup>1</sup>/<sub>100</sub> soliq — «centesima rerum venalium» joriy qilgan. O‘rta asr Italiyasida bankirlar va savdogarlar qarz va foyda hisobida «per cento» iborasini doim ishlatishgan.', 'Счёт «на сотню» существовал ещё в Древнем Риме: император Август ввёл налог в <sup>1</sup>/<sub>100</sub> с проданных товаров — «centesima rerum venalium». В средневековой Италии банкиры и купцы постоянно использовали выражение «per cento» при расчётах долгов и прибыли.', 'Counting “per hundred” goes back to ancient Rome: the emperor Augustus introduced a tax of <sup>1</sup>/<sub>100</sub> on goods sold, the “centesima rerum venalium”. In medieval Italy bankers and merchants used the phrase “per cento” constantly when working out debts and profits.'),
      L('Savdogarlar tez yozish uchun «per cento» ni qisqartirib «p cto» deb yozishgan. Asrlar davomida «cto» ning harflari egilib, qisqarib, oxiri ikki doiracha va qiya chiziqqa aylandi — bugungi <b>%</b> belgisi shunday tug‘ilgan. XVII asrga kelib u keng tarqaldi.', 'Чтобы писать быстрее, купцы сокращали «per cento» до «p cto». За века буквы «cto» наклонялись, сжимались и в конце концов превратились в два кружочка и косую черту — так родился знак <b>%</b>. К XVII веку он стал общепринятым.', 'To write faster, merchants shortened “per cento” to “p cto”. Over the centuries the letters “cto” tilted and shrank until they became two little circles and a slash — that is how the <b>%</b> sign was born. By the 17th century it was in common use.'),
      L('Sharqda ham ulushlar bilan hisoblash juda rivojlangan edi. Al-Xorazmiy meros masalalarida mulkni ulushlarga bo‘lishni batafsil tushuntirgan, al-Koshiy esa o‘nli kasrlar bilan hisoblashni yengillashtirgan — foiz aslida yuzdan birlardagi o‘nli kasrdir.', 'На Востоке счёт долями тоже был развит. Аль-Хорезми подробно объяснял раздел имущества на доли в задачах о наследстве, а аль-Каши облегчил вычисления с десятичными дробями — а процент, по сути, и есть десятичная дробь в сотых.', 'Calculating with shares was highly developed in the East too. Al-Khwarizmi explained in detail how to split property into shares in inheritance problems, and al-Kashi made decimal calculation easier — and a percent is really just a decimal in hundredths.')
    ] },
    { kind: 'rule', h: L('Uch ko‘rinish: kasr, o‘nli kasr, foiz', 'Три записи: дробь, десятичная, процент', 'Three forms: fraction, decimal, percent'), list: [
      L('<b>Foiz → o‘nli kasr:</b> 100 ga bo‘lamiz (vergul 2 xona chapga): 40% = 0,4; 7% = 0,07; 125% = 1,25.', '<b>Процент → десятичная:</b> делим на 100 (запятая на 2 знака влево): 40% = 0,4; 7% = 0,07; 125% = 1,25.', '<b>Percent → decimal:</b> divide by 100 (point 2 places left): 40% = 0.4; 7% = 0.07; 125% = 1.25.'),
      L('<b>O‘nli kasr → foiz:</b> 100 ga ko‘paytiramiz (vergul 2 xona o‘ngga): 0,75 = 75%; 0,3 = 30%; 0,05 = 5%.', '<b>Десятичная → процент:</b> умножаем на 100 (запятая на 2 знака вправо): 0,75 = 75%; 0,3 = 30%; 0,05 = 5%.', '<b>Decimal → percent:</b> multiply by 100 (point 2 places right): 0.75 = 75%; 0.3 = 30%; 0.05 = 5%.'),
      L('<b>Oddiy kasr → foiz:</b> maxrajni 100 ga keltiramiz: <sup>3</sup>/<sub>4</sub> = <sup>75</sup>/<sub>100</sub> = 75%; <sup>2</sup>/<sub>5</sub> = <sup>40</sup>/<sub>100</sub> = 40%.', '<b>Обыкновенная дробь → процент:</b> приводим к знаменателю 100: <sup>3</sup>/<sub>4</sub> = <sup>75</sup>/<sub>100</sub> = 75%; <sup>2</sup>/<sub>5</sub> = <sup>40</sup>/<sub>100</sub> = 40%.', '<b>Fraction → percent:</b> make the denominator 100: <sup>3</sup>/<sub>4</sub> = <sup>75</sup>/<sub>100</sub> = 75%; <sup>2</sup>/<sub>5</sub> = <sup>40</sup>/<sub>100</sub> = 40%.'),
      L('<b>Foiz → oddiy kasr:</b> 100 ga bo‘lingan kasr yozib qisqartiramiz: 60% = <sup>60</sup>/<sub>100</sub> = <sup>3</sup>/<sub>5</sub>.', '<b>Процент → обыкновенная дробь:</b> пишем дробь со знаменателем 100 и сокращаем: 60% = <sup>60</sup>/<sub>100</sub> = <sup>3</sup>/<sub>5</sub>.', '<b>Percent → fraction:</b> write it over 100 and simplify: 60% = <sup>60</sup>/<sub>100</sub> = <sup>3</sup>/<sub>5</sub>.')
    ], after: [
      L('Bularning hammasi bitta sonning uch xil «kiyimi». <sup>1</sup>/<sub>2</sub>, 0,5 va 50% — aynan bir xil miqdor, xuddi «yarim soat», «30 minut» va «0,5 soat» bir xil vaqt bo‘lgani kabi.', 'Всё это три «наряда» одного числа. <sup>1</sup>/<sub>2</sub>, 0,5 и 50% — одна и та же величина, как «полчаса», «30 минут» и «0,5 часа» — одно и то же время.', 'These are three “outfits” of the same number. <sup>1</sup>/<sub>2</sub>, 0.5 and 50% are exactly the same amount, just as “half an hour”, “30 minutes” and “0.5 h” are the same time.')
    ] },
    { kind: 'steps', h: L('Kasrni foizga aylantirish', 'Перевод дроби в проценты', 'Turning a fraction into a percent'), p: [
      L('Masalan, <sup>7</sup>/<sub>20</sub> ni foizda ifodalaymiz.', 'Например, выразим <sup>7</sup>/<sub>20</sub> в процентах.', 'For example, express <sup>7</sup>/<sub>20</sub> as a percent.')
    ], list: [
      L('1-qadam. Maxrajni 100 ga yetkazish uchun nechaga ko‘paytirish kerak? 100 : 20 = 5.', 'Шаг 1. На что умножить знаменатель, чтобы получить 100? 100 : 20 = 5.', 'Step 1. What turns the denominator into 100? 100 : 20 = 5.'),
      L('2-qadam. Surat va maxrajni 5 ga ko‘paytiramiz: <sup>7</sup>/<sub>20</sub> = <sup>35</sup>/<sub>100</sub>.', 'Шаг 2. Умножаем числитель и знаменатель на 5: <sup>7</sup>/<sub>20</sub> = <sup>35</sup>/<sub>100</sub>.', 'Step 2. Multiply top and bottom by 5: <sup>7</sup>/<sub>20</sub> = <sup>35</sup>/<sub>100</sub>.'),
      L('3-qadam. Yuzdan 35 — bu 35%.', 'Шаг 3. 35 сотых — это 35%.', 'Step 3. 35 hundredths is 35%.'),
      L('4-qadam. Agar maxraj 100 ga oson keltirilmasa (masalan, <sup>1</sup>/<sub>8</sub>), suratni maxrajga bo‘lib o‘nli kasr topamiz: 1 : 8 = 0,125 = 12,5%.', 'Шаг 4. Если знаменатель не приводится к 100 легко (например, <sup>1</sup>/<sub>8</sub>), делим числитель на знаменатель: 1 : 8 = 0,125 = 12,5%.', 'Step 4. If the denominator does not go easily into 100 (e.g. <sup>1</sup>/<sub>8</sub>), divide top by bottom: 1 : 8 = 0.125 = 12.5%.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Namunalarda uchala ko‘rinish o‘rtasida ikki tomonga harakat qilamiz. Har safar o‘zingizdan so‘rang: natija mantiqiymi? Yarimdan kam ulush 50% dan kam bo‘lishi kerak.', 'В примерах переходим между тремя записями в обе стороны. Каждый раз спрашивайте себя: разумен ли результат? Доля меньше половины должна быть меньше 50%.', 'In these examples we move between the three forms in both directions. Each time ask: does the result make sense? A share less than half must be under 50%.')
    ], ex: [
      { q: L('<sup>3</sup>/<sub>4</sub> ni foizda yozing.', 'Запишите <sup>3</sup>/<sub>4</sub> в процентах.', 'Write <sup>3</sup>/<sub>4</sub> as a percent.'), s: L('100 : 4 = 25. <sup>3</sup>/<sub>4</sub> = <sup>75</sup>/<sub>100</sub> = <b>75%</b>. O‘nli kasrda: 0,75.', '100 : 4 = 25. <sup>3</sup>/<sub>4</sub> = <sup>75</sup>/<sub>100</sub> = <b>75%</b>. В десятичной записи: 0,75.', '100 : 4 = 25. <sup>3</sup>/<sub>4</sub> = <sup>75</sup>/<sub>100</sub> = <b>75%</b>. As a decimal: 0.75.') },
      { q: L('40% ni o‘nli va oddiy kasr ko‘rinishida yozing.', 'Запишите 40% десятичной и обыкновенной дробью.', 'Write 40% as a decimal and as a fraction.'), s: L('40 : 100 = <b>0,4</b>. <sup>40</sup>/<sub>100</sub> = <b><sup>2</sup>/<sub>5</sub></b>.', '40 : 100 = <b>0,4</b>. <sup>40</sup>/<sub>100</sub> = <b><sup>2</sup>/<sub>5</sub></b>.', '40 : 100 = <b>0.4</b>. <sup>40</sup>/<sub>100</sub> = <b><sup>2</sup>/<sub>5</sub></b>.') },
      { q: L('Sinfda 25 o‘quvchi, ulardan 9 tasi qizlar. Qizlar necha foiz?', 'В классе 25 учеников, из них 9 девочек. Сколько процентов составляют девочки?', 'A class has 25 pupils, 9 of them girls. What percentage are girls?'), s: L('Ulush: <sup>9</sup>/<sub>25</sub>. 100 : 25 = 4, <sup>9</sup>/<sub>25</sub> = <sup>36</sup>/<sub>100</sub>. Javob: <b>36%</b>. O‘g‘illar — 64%.', 'Доля: <sup>9</sup>/<sub>25</sub>. 100 : 25 = 4, <sup>9</sup>/<sub>25</sub> = <sup>36</sup>/<sub>100</sub>. Ответ: <b>36%</b>. Мальчики — 64%.', 'Share: <sup>9</sup>/<sub>25</sub>. 100 : 25 = 4, so <sup>9</sup>/<sub>25</sub> = <sup>36</sup>/<sub>100</sub>. Answer: <b>36%</b>. Boys: 64%.') },
      { q: L('Qaysi biri katta: 0,6 yoki 58%?', 'Что больше: 0,6 или 58%?', 'Which is bigger: 0.6 or 58%?'), s: L('0,6 = 60%. 60% &gt; 58%. Javob: <b>0,6</b> katta.', '0,6 = 60%. 60% &gt; 58%. Ответ: <b>0,6</b> больше.', '0.6 = 60%. 60% &gt; 58%. Answer: <b>0.6</b> is bigger.') }
    ] },
    { kind: 'table', h: L('Muhim mosliklar', 'Важные соответствия', 'Key equivalents'), table: { head: [L('Kasr', 'Дробь', 'Fraction'), L('O‘nli kasr', 'Десятичная', 'Decimal'), L('Foiz', 'Процент', 'Percent')], rows: [
      ['1/100', L('0,01', '0,01', '0.01'), '1%'],
      ['1/10', L('0,1', '0,1', '0.1'), '10%'],
      ['1/5', L('0,2', '0,2', '0.2'), '20%'],
      ['1/4', L('0,25', '0,25', '0.25'), '25%'],
      ['1/2', L('0,5', '0,5', '0.5'), '50%'],
      ['3/4', L('0,75', '0,75', '0.75'), '75%'],
      ['1', '1', '100%']
    ] }, after: [
      L('Bu jadvalni yoddan bilish foydali — do‘konda, imtihonda va o‘yinlarda ko‘p vaqtni tejaydi. Qolgan foizlarni shulardan yig‘ish mumkin: 35% = 25% + 10%, 60% = 50% + 10%.', 'Эту таблицу полезно знать наизусть — она экономит много времени в магазине, на экзамене и в играх. Остальные проценты можно собрать из этих: 35% = 25% + 10%, 60% = 50% + 10%.', 'It is worth knowing this table by heart: it saves lots of time in shops, exams and games. Other percentages can be built from these: 35% = 25% + 10%, 60% = 50% + 10%.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>7% = 0,7</b> — xato. 100 ga bo‘lishda vergul <b>ikki</b> xona suriladi: 7% = 0,07. 0,7 esa 70%.', '<b>7% = 0,7</b> — ошибка. При делении на 100 запятая сдвигается на <b>два</b> знака: 7% = 0,07. А 0,7 — это 70%.', '<b>7% = 0.7</b> is wrong. Dividing by 100 moves the point <b>two</b> places: 7% = 0.07. 0.7 is 70%.'),
      L('<b>Kasrni to‘g‘ridan-to‘g‘ri yozish.</b> <sup>1</sup>/<sub>4</sub> = 14% yoki 4% — xato. Avval maxrajni 100 ga keltiring: 25%.', '<b>Запись дроби «как есть».</b> <sup>1</sup>/<sub>4</sub> = 14% или 4% — ошибка. Сначала приведите знаменатель к 100: 25%.', '<b>Copying the digits.</b> <sup>1</sup>/<sub>4</sub> = 14% or 4% is wrong. First make the denominator 100: 25%.'),
      L('<b>100% dan oshmaydi deb o‘ylash.</b> Hosil o‘tgan yilgidan 120% bo‘lishi mumkin — demak, ko‘paygan.', '<b>Думать, что больше 100% не бывает.</b> Урожай может составить 120% прошлогоднего — значит, он вырос.', '<b>Thinking nothing exceeds 100%.</b> A harvest can be 120% of last year’s — it grew.'),
      L('<b>Butunni unutish.</b> «30%» o‘z-o‘zidan son emas — har doim «nimaning 30% i?» deb so‘rang. 100 ning 30% i va 1000 ning 30% i — turlicha.', '<b>Забывать о целом.</b> «30%» само по себе не число — всегда спрашивайте «30% от чего?». 30% от 100 и 30% от 1000 — разные вещи.', '<b>Forgetting the whole.</b> “30%” alone is not an amount — always ask “30% of what?”. 30% of 100 and 30% of 1000 are different.')
    ] },
    { kind: 'life', h: L('Hayotda foizlar', 'Проценты в жизни', 'Percentages in life'), p: [
      L('<b>Maktabda.</b> Test natijasi ko‘pincha foizda beriladi: 40 savoldan 34 tasi to‘g‘ri — <sup>34</sup>/<sub>40</sub> = 0,85 = 85%. Turli testlarni (20, 40, 50 savolli) taqqoslash uchun foiz eng qulay.', '<b>В школе.</b> Результат теста часто дают в процентах: 34 верных из 40 — <sup>34</sup>/<sub>40</sub> = 0,85 = 85%. Чтобы сравнивать разные тесты (из 20, 40, 50 вопросов), проценты удобнее всего.', '<b>At school.</b> Test results are often given in percent: 34 out of 40 correct is <sup>34</sup>/<sub>40</sub> = 0.85 = 85%. To compare tests of 20, 40 or 50 questions, percentages are the handiest.'),
      L('<b>Oziq-ovqat.</b> Qatiq qutisida «yog‘ 2,5%» — 100 g mahsulotda 2,5 g yog‘ bor. Shokoladda «kakao 70%» — uning massasining 70% i kakao mahsulotlari.', '<b>Еда.</b> На катыке написано «жир 2,5%» — в 100 г продукта 2,5 г жира. На шоколаде «какао 70%» — 70% его массы составляют какао-продукты.', '<b>Food.</b> A yoghurt pot says “fat 2.5%”: 100 g contains 2.5 g of fat. Chocolate labelled “70% cocoa” is 70% cocoa products by mass.'),
      L('<b>Tabiat.</b> Yer yuzasining taxminan 71% ini suv egallaydi. Inson tanasining 60% ga yaqini suv. Havoning 78% i azot, 21% i kislorod.', '<b>Природа.</b> Около 71% поверхности Земли покрыто водой. Тело человека примерно на 60% состоит из воды. Воздух — это 78% азота и 21% кислорода.', '<b>Nature.</b> About 71% of the Earth’s surface is water. The human body is roughly 60% water. Air is 78% nitrogen and 21% oxygen.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('Promille (‰) — mingdan bir qism belgisi. Dengiz suvining sho‘rligi taxminan 35‰, ya’ni 1 kg suvda 35 g tuz. Orol dengizi qurib borgani sari uning sho‘rligi bir necha barobar oshib ketgan.', 'Промилле (‰) — знак тысячной доли. Солёность морской воды около 35‰, то есть 35 г соли на 1 кг воды. По мере высыхания Аральского моря его солёность выросла в несколько раз.', 'Per mille (‰) is the sign for thousandths. Sea water is about 35‰ salt, i.e. 35 g of salt per 1 kg of water. As the Aral Sea dried up, its saltiness rose several times over.'),
      L('«Yuz foiz ishonaman» iborasi matematikadan kundalik nutqqa o‘tgan. Lekin «110% kuch bilan ishladim» deyish matematik jihatdan g‘alati — butun kuch 100% ku!', 'Выражение «уверен на сто процентов» пришло из математики в повседневную речь. А вот «работал на 110%» с точки зрения математики странно — ведь все силы — это 100%!', 'The phrase “100% sure” moved from maths into everyday speech. But “giving 110%” is odd mathematically — all your effort is 100%!')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумайте', 'Think about it'), list: [
      L('<sup>1</sup>/<sub>20</sub> necha foiz?', 'Сколько процентов составляет <sup>1</sup>/<sub>20</sub>?', 'What percentage is <sup>1</sup>/<sub>20</sub>?'),
      L('0,08 ni foizda yozing.', 'Запишите 0,08 в процентах.', 'Write 0.08 as a percent.'),
      L('Tartiblang: 0,3; 35%; <sup>1</sup>/<sub>4</sub>.', 'Расположите по возрастанию: 0,3; 35%; <sup>1</sup>/<sub>4</sub>.', 'Put in order: 0.3; 35%; <sup>1</sup>/<sub>4</sub>.'),
      L('Pitsaning 3 bo‘lagi yeyildi, jami 8 bo‘lak edi. Necha foizi qoldi?', 'Из 8 кусков пиццы съели 3. Сколько процентов осталось?', '3 of 8 pizza slices were eaten. What percentage is left?')
    ], after: [
      L('Javoblar: 5%; 8%; <sup>1</sup>/<sub>4</sub> (25%) &lt; 0,3 (30%) &lt; 35%; <sup>5</sup>/<sub>8</sub> = 0,625 = 62,5%.', 'Ответы: 5%; 8%; <sup>1</sup>/<sub>4</sub> (25%) &lt; 0,3 (30%) &lt; 35%; <sup>5</sup>/<sub>8</sub> = 0,625 = 62,5%.', 'Answers: 5%; 8%; <sup>1</sup>/<sub>4</sub> (25%) &lt; 0.3 (30%) &lt; 35%; <sup>5</sup>/<sub>8</sub> = 0.625 = 62.5%.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('1% = <sup>1</sup>/<sub>100</sub> = 0,01; butun = 100%.', '1% = <sup>1</sup>/<sub>100</sub> = 0,01; целое = 100%.', '1% = <sup>1</sup>/<sub>100</sub> = 0.01; the whole = 100%.'),
      L('Foiz → o‘nli kasr: 100 ga bo‘lish; o‘nli kasr → foiz: 100 ga ko‘paytirish.', 'Процент → десятичная: делим на 100; десятичная → процент: умножаем на 100.', 'Percent → decimal: divide by 100; decimal → percent: multiply by 100.'),
      L('Kasr → foiz: maxrajni 100 ga keltiring yoki suratni maxrajga bo‘ling.', 'Дробь → процент: приведите знаменатель к 100 или разделите числитель на знаменатель.', 'Fraction → percent: make the denominator 100, or divide top by bottom.'),
      L('<sup>1</sup>/<sub>2</sub> = 50%, <sup>1</sup>/<sub>4</sub> = 25%, <sup>1</sup>/<sub>10</sub> = 10% — yod oling.', '<sup>1</sup>/<sub>2</sub> = 50%, <sup>1</sup>/<sub>4</sub> = 25%, <sup>1</sup>/<sub>10</sub> = 10% — запомните.', '<sup>1</sup>/<sub>2</sub> = 50%, <sup>1</sup>/<sub>4</sub> = 25%, <sup>1</sup>/<sub>10</sub> = 10% — learn them.'),
      L('Foiz turli to‘plamlarni bir o‘lchovda taqqoslash imkonini beradi.', 'Процент позволяет сравнивать разные совокупности одной меркой.', 'Percentages let us compare different groups on one scale.')
    ] }
  ] });

  // ---------- t8. Miqdorning foizi ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('240 ning 15% i qancha?', 'Сколько составляет 15% от 240?', 'What is 15% of 240?'), p: [
      L('Foiz nima ekanini bildik. Endi eng ko‘p uchraydigan savolga o‘tamiz: <b>berilgan miqdorning foizini topish</b>. Maktabda 240 o‘quvchi bor, ularning 15% i shaxmat to‘garagiga qatnashadi. Necha o‘quvchi? Kitob 400 bet, Sardor uning 30% ini o‘qidi — necha bet?', 'Мы знаем, что такое процент. Теперь перейдём к самому частому вопросу: <b>как найти процент от данной величины</b>. В школе 240 учеников, 15% из них ходят в шахматный кружок. Сколько это учеников? В книге 400 страниц, Сардор прочитал 30% — сколько страниц?', 'We know what a percent is. Now for the most common question of all: <b>finding a percentage of a given amount</b>. A school has 240 pupils and 15% of them go to chess club. How many pupils is that? A book has 400 pages and Sardor has read 30% — how many pages?'),
      L('Bunday savollar har qadamda uchraydi: chegirma, soliq, imtihon bali, hosil, aholi soni. Bu mavzuda ularni yechishning asosiy usulini va og‘zaki hisob uchun qulay yo‘llarni o‘rganamiz.', 'Такие вопросы встречаются на каждом шагу: скидка, налог, баллы на экзамене, урожай, население. В этой теме изучим основной способ их решения и удобные приёмы для устного счёта.', 'Questions like these are everywhere: discounts, tax, exam marks, harvests, population. In this topic we learn the main method for solving them and handy shortcuts for mental maths.'),
      L('Asosiy g‘oya juda oddiy: avval butunning 1% ini topamiz, so‘ngra uni kerakli foizlar soniga ko‘paytiramiz. Qolgan barcha usullar shu g‘oyaning qisqartirilgan shakllaridir.', 'Главная идея очень проста: сначала находим 1% целого, а затем умножаем его на нужное число процентов. Все остальные приёмы — сокращённые формы этой идеи.', 'The main idea is very simple: first find 1% of the whole, then multiply by the number of percent you need. Every other method is a shortcut of this idea.')
    ] },
    { kind: 'def', h: L('Butun va uning qismi', 'Целое и его часть', 'The whole and its part'), p: [
      L('Har bir foiz masalasida uchta kattalik bor: <b>butun</b> (100% deb olinadigan miqdor), <b>foizlar soni</b> (p%) va <b>qism</b> (butunning p% iga teng miqdor). Bu mavzuda butun va foiz ma’lum, qismni topamiz.', 'В каждой задаче на проценты три величины: <b>целое</b> (величина, принятая за 100%), <b>число процентов</b> (p%) и <b>часть</b> (величина, равная p% целого). В этой теме целое и процент известны, ищем часть.', 'Every percentage problem has three quantities: the <b>whole</b> (the amount taken as 100%), the <b>percentage</b> (p%) and the <b>part</b> (the amount equal to p% of the whole). In this topic the whole and the percentage are known, and we find the part.'),
      L('Masalan, «240 ning 15% i» iborasida 240 — butun, 15% — foiz, natija (36) — qism. O‘zbek tilida «240 ning 15% i», rus tilida «15% от 240», ingliz tilida «15% of 240» deyiladi — ma’no bir xil.', 'Например, в выражении «15% от 240» 240 — целое, 15% — процент, результат (36) — часть. По-узбекски говорят «240 ning 15% i», по-английски «15% of 240» — смысл один.', 'For example, in “15% of 240”, 240 is the whole, 15% the percentage and the result (36) the part. In Uzbek one says “240 ning 15% i”, in Russian “15% от 240” — the meaning is the same.')
    ], after: [
      L('Butunni to‘g‘ri aniqlash juda muhim: «nimaning foizi?» degan savolga javob — butun. Agar narx 20% ga oshgan bo‘lsa, butun — <i>eski</i> narx, yangisi emas.', 'Очень важно правильно определить целое: ответ на вопрос «процент от чего?» — это целое. Если цена выросла на 20%, целое — <i>старая</i> цена, а не новая.', 'Identifying the whole correctly matters a lot: the answer to “a percentage of what?” is the whole. If a price rises by 20%, the whole is the <i>old</i> price, not the new one.')
    ] },
    { kind: 'history', h: L('Foizlar va savdo tarixi', 'Проценты и история торговли', 'Percentages and the history of trade'), p: [
      L('O‘rta asrlarda Samarqand, Buxoro va Xiva bozorlarida savdogarlar tovar narxining ma’lum ulushini boj sifatida to‘lashgan. Buyuk Ipak yo‘lida karvonsaroylar ham yuk qiymatining ulushini olishgan. Bunday ulushlarni hisoblash har bir savdogar uchun zarur ko‘nikma edi.', 'В Средние века на базарах Самарканда, Бухары и Хивы купцы платили пошлину в виде определённой доли цены товара. На Великом шёлковом пути караван-сараи тоже брали долю от стоимости груза. Расчёт таких долей был необходимым навыком каждого купца.', 'In the Middle Ages merchants at the bazaars of Samarkand, Bukhara and Khiva paid duty as a fixed share of the price of their goods. Caravanserais on the Silk Road also took a share of a cargo’s value. Working out such shares was an essential skill for every trader.'),
      L('1202-yilda italyan matematigi <b>Leonardo Fibonachchi</b> «Abak kitobi»ni yozdi. Unda arab olimlaridan, jumladan al-Xorazmiydan o‘rgangan hind raqamlarini va savdo hisoblarini yevropaliklarga tushuntirdi. Kitobda foyda va zararni «yuzdan» hisoblash masalalari ko‘p.', 'В 1202 году итальянский математик <b>Леонардо Фибоначчи</b> написал «Книгу абака». В ней он объяснил европейцам индийские цифры и торговые расчёты, которые изучил у арабских учёных, в том числе по трудам аль-Хорезми. В книге много задач на расчёт прибыли и убытка «на сотню».', 'In 1202 the Italian mathematician <b>Leonardo Fibonacci</b> wrote the “Book of Calculation” (Liber Abaci). In it he explained to Europeans the Indian numerals and commercial arithmetic he had learned from Arab scholars, including the works of al-Khwarizmi. The book is full of problems on profit and loss “per hundred”.'),
      L('Bugun foizlar statistikada markaziy o‘rin tutadi: aholi o‘sishi, iqtisodiyot, ob-havo ehtimoli, saylov natijalari — hammasi foizda e’lon qilinadi.', 'Сегодня проценты занимают центральное место в статистике: рост населения, экономика, вероятность погоды, результаты выборов — всё объявляется в процентах.', 'Today percentages are central to statistics: population growth, the economy, weather probabilities, election results are all reported in percent.')
    ] },
    { kind: 'rule', h: L('Asosiy qoida', 'Основное правило', 'The main rule'), p: [
      L('<b>N ning p% i = N : 100 · p</b>', '<b>p% от N = N : 100 · p</b>', '<b>p% of N = N : 100 · p</b>'),
      L('Ya’ni: avval 1% ni topamiz (N : 100), keyin uni p ga ko‘paytiramiz. 240 ning 15% i: 240 : 100 = 2,4 (bu 1%); 2,4 · 15 = 36.', 'То есть: сначала находим 1% (N : 100), затем умножаем на p. 15% от 240: 240 : 100 = 2,4 (это 1%); 2,4 · 15 = 36.', 'That is: first find 1% (N : 100), then multiply by p. 15% of 240: 240 : 100 = 2.4 (that is 1%); 2.4 · 15 = 36.'),
      L('Boshqacha yozuv: foizni o‘nli kasrga aylantirib, songa ko‘paytiramiz: 15% = 0,15; 240 · 0,15 = 36. Ikkala usul bir xil natija beradi.', 'Другая запись: переводим процент в десятичную дробь и умножаем на число: 15% = 0,15; 240 · 0,15 = 36. Оба способа дают одно и то же.', 'Another way: turn the percent into a decimal and multiply: 15% = 0.15; 240 · 0.15 = 36. Both ways give the same result.')
    ], list: [
      L('<b>50%</b> — yarmi: N : 2. 80 ning 50% i = 40.', '<b>50%</b> — половина: N : 2. 50% от 80 = 40.', '<b>50%</b> — half: N : 2. 50% of 80 = 40.'),
      L('<b>25%</b> — chorak: N : 4. 120 ning 25% i = 30.', '<b>25%</b> — четверть: N : 4. 25% от 120 = 30.', '<b>25%</b> — a quarter: N : 4. 25% of 120 = 30.'),
      L('<b>10%</b> — N : 10. 350 ning 10% i = 35.', '<b>10%</b> — N : 10. 10% от 350 = 35.', '<b>10%</b> — N : 10. 10% of 350 = 35.'),
      L('<b>5%</b> — 10% ning yarmi. 350 ning 5% i = 17,5.', '<b>5%</b> — половина от 10%. 5% от 350 = 17,5.', '<b>5%</b> — half of 10%. 5% of 350 = 17.5.')
    ] },
    { kind: 'steps', h: L('Qadamma-qadam', 'Шаг за шагом', 'Step by step'), p: [
      L('Masala: 1500 ning 12% ini toping.', 'Задача: найдите 12% от 1500.', 'Problem: find 12% of 1500.')
    ], list: [
      L('1-qadam. Butunni aniqlang: N = 1500.', 'Шаг 1. Определите целое: N = 1500.', 'Step 1. Identify the whole: N = 1500.'),
      L('2-qadam. 1% ni toping: 1500 : 100 = 15.', 'Шаг 2. Найдите 1%: 1500 : 100 = 15.', 'Step 2. Find 1%: 1500 : 100 = 15.'),
      L('3-qadam. Foizlar soniga ko‘paytiring: 15 · 12 = 180.', 'Шаг 3. Умножьте на число процентов: 15 · 12 = 180.', 'Step 3. Multiply by the percentage: 15 · 12 = 180.'),
      L('4-qadam. Tekshiring: 10% = 150, 2% = 30, jami 180. To‘g‘ri!', 'Шаг 4. Проверьте: 10% = 150, 2% = 30, вместе 180. Верно!', 'Step 4. Check: 10% = 150, 2% = 30, total 180. Correct!')
    ], after: [
      L('Tekshiruvdagi usul — foizni qulay bo‘laklarga ajratish — og‘zaki hisob uchun eng yaxshi yo‘l. 35% = 25% + 10%, 15% = 10% + 5%, 90% = 100% − 10%.', 'Приём из проверки — разложение процента на удобные части — лучший путь для устного счёта. 35% = 25% + 10%, 15% = 10% + 5%, 90% = 100% − 10%.', 'The trick in the check — splitting the percentage into handy pieces — is the best way to work mentally. 35% = 25% + 10%, 15% = 10% + 5%, 90% = 100% − 10%.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir namunani ikki usulda yechib ko‘ramiz: formula bilan (avval 1%, keyin ko‘paytirish) va qulay bo‘laklar bilan (10%, 5%, 50%). Ikki usul bir xil javob bersa, xato yo‘qligiga ishonch hosil qilamiz. Oxirgi namunada birliklarga ham e’tibor bering: kilogrammni avval grammga aylantirdik, shunda javob qulayroq son bo‘lib chiqdi.', 'Каждый пример решаем двумя способами: по формуле (сначала 1%, потом умножение) и с помощью удобных частей (10%, 5%, 50%). Если оба способа дают один ответ, мы уверены, что ошибки нет. В последнем примере обратите внимание и на единицы: килограммы мы сначала перевели в граммы, и ответ вышел удобнее.', 'We solve each example two ways: by the formula (1% first, then multiply) and with handy pieces (10%, 5%, 50%). When both ways agree, we can be sure there is no mistake. In the last example notice the units too: we turned kilograms into grams first, so the answer came out as a friendlier number.')
    ], ex: [
      { q: L('240 ning 15% ini toping.', 'Найдите 15% от 240.', 'Find 15% of 240.'), s: L('240 : 100 = 2,4; 2,4 · 15 = 36. Yoki: 10% = 24, 5% = 12, 24 + 12 = 36. Javob: <b>36</b>.', '240 : 100 = 2,4; 2,4 · 15 = 36. Или: 10% = 24, 5% = 12, 24 + 12 = 36. Ответ: <b>36</b>.', '240 : 100 = 2.4; 2.4 · 15 = 36. Or: 10% = 24, 5% = 12, 24 + 12 = 36. Answer: <b>36</b>.') },
      { q: L('Kitob 400 bet. Sardor uning 30% ini o‘qidi. Necha bet o‘qidi va necha bet qoldi?', 'В книге 400 страниц. Сардор прочитал 30%. Сколько страниц он прочитал и сколько осталось?', 'A book has 400 pages. Sardor read 30%. How many pages has he read and how many are left?'), s: L('400 : 100 · 30 = 120 bet o‘qildi. Qoldi: 400 − 120 = 280 bet (bu 70%). Javob: <b>120 va 280 bet</b>.', '400 : 100 · 30 = 120 страниц прочитано. Осталось: 400 − 120 = 280 (это 70%). Ответ: <b>120 и 280 страниц</b>.', '400 : 100 · 30 = 120 pages read. Left: 400 − 120 = 280 (that is 70%). Answer: <b>120 and 280 pages</b>.') },
      { q: L('Bog‘dagi 60 tup daraxtning 45% i olma. Nechta olma daraxti bor?', 'В саду 60 деревьев, 45% из них — яблони. Сколько яблонь?', 'An orchard has 60 trees and 45% are apple trees. How many apple trees?'), s: L('60 : 100 = 0,6; 0,6 · 45 = 27. Yoki: 50% = 30, 5% = 3, 30 − 3 = 27. Javob: <b>27 tup</b>.', '60 : 100 = 0,6; 0,6 · 45 = 27. Или: 50% = 30, 5% = 3, 30 − 3 = 27. Ответ: <b>27 деревьев</b>.', '60 : 100 = 0.6; 0.6 · 45 = 27. Or: 50% = 30, 5% = 3, 30 − 3 = 27. Answer: <b>27 trees</b>.') },
      { q: L('Sut tarkibida 3,2% yog‘ bor. 2 kg sutda necha gramm yog‘?', 'В молоке 3,2% жира. Сколько граммов жира в 2 кг молока?', 'Milk is 3.2% fat. How many grams of fat are in 2 kg of milk?'), s: L('2 kg = 2000 g. 2000 : 100 = 20; 20 · 3,2 = 64. Javob: <b>64 g</b>.', '2 кг = 2000 г. 2000 : 100 = 20; 20 · 3,2 = 64. Ответ: <b>64 г</b>.', '2 kg = 2000 g. 2000 : 100 = 20; 20 · 3.2 = 64. Answer: <b>64 g</b>.') }
    ] },
    { kind: 'table', h: L('200 ning foizlari', 'Проценты от 200', 'Percentages of 200'), table: { head: [L('Foiz', 'Процент', 'Percent'), L('Hisob', 'Вычисление', 'Calculation'), L('Natija', 'Результат', 'Result')], rows: [
      ['1%', '200 : 100', '2'],
      ['5%', '2 · 5', '10'],
      ['10%', '200 : 10', '20'],
      ['25%', '200 : 4', '50'],
      ['50%', '200 : 2', '100'],
      ['75%', '50 · 3', '150'],
      ['120%', '200 + 40', '240']
    ] }, after: [
      L('Oxirgi qatorga qarang: 120% — butunning o‘zi (100%) va yana 20% i. Shuning uchun natija butunning o‘zidan katta chiqdi. Foiz 100 dan kichik bo‘lsa qism butundan kichik, katta bo‘lsa — katta.', 'Посмотрите на последнюю строку: 120% — это всё целое (100%) и ещё 20%. Поэтому результат больше самого целого. Если процент меньше 100, часть меньше целого, если больше — больше.', 'Look at the last row: 120% is the whole (100%) plus another 20%. That is why the result is bigger than the whole. If the percentage is below 100 the part is smaller than the whole; above 100, bigger.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Foizni to‘g‘ridan-to‘g‘ri ko‘paytirish.</b> 240 · 15 = 3600 — bu 15% emas, 1500%! 100 ga bo‘lishni unutmang.', '<b>Умножение на процент «как есть».</b> 240 · 15 = 3600 — это не 15%, а 1500%! Не забудьте делить на 100.', '<b>Multiplying by the raw percentage.</b> 240 · 15 = 3600 is not 15% but 1500%! Do not forget to divide by 100.'),
      L('<b>Foizni ayirish.</b> 80 ning 25% i = 80 − 25 = 55 — xato. Foiz — bu ulush, son emas: 80 : 4 = 20.', '<b>Вычитание процента.</b> 25% от 80 = 80 − 25 = 55 — ошибка. Процент — это доля, а не число: 80 : 4 = 20.', '<b>Subtracting the percentage.</b> 25% of 80 = 80 − 25 = 55 is wrong. A percent is a share, not a number: 80 : 4 = 20.'),
      L('<b>Noto‘g‘ri butun.</b> «Qizlar o‘g‘illardan 20% ko‘p» — butun o‘g‘illar soni, umumiy son emas.', '<b>Неверное целое.</b> «Девочек на 20% больше, чем мальчиков» — целое здесь число мальчиков, а не общее число.', '<b>Wrong whole.</b> “There are 20% more girls than boys” — the whole is the number of boys, not the total.'),
      L('<b>Natijani tekshirmaslik.</b> 60 ning 45% i 270 chiqsa — xato aniq: 45% yarmidan kam, demak javob 30 dan kam bo‘lishi kerak.', '<b>Не проверять результат.</b> Если 45% от 60 получилось 270 — ошибка очевидна: 45% меньше половины, значит, ответ меньше 30.', '<b>Not checking.</b> If 45% of 60 comes out as 270, the error is obvious: 45% is under half, so the answer must be under 30.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Uses in life'), p: [
      L('<b>Telefon zaryadi.</b> Batareya 4000 mA·soat, zaryad 35% — ichida 4000 : 100 · 35 = 1400 mA·soat qolgan. Bu o‘yin uchun yetadimi, shuni hisoblab olish mumkin.', '<b>Заряд телефона.</b> Батарея 4000 мА·ч, заряд 35% — в ней осталось 4000 : 100 · 35 = 1400 мА·ч. Можно прикинуть, хватит ли на игру.', '<b>Phone battery.</b> A 4000 mAh battery at 35% holds 4000 : 100 · 35 = 1400 mAh. You can work out whether that is enough for a game.'),
      L('<b>Ovqatlanish.</b> Kunlik 2000 kkal ning 25% i nonushtaga to‘g‘ri kelsin desak, nonushta 500 kkal bo‘lishi kerak. Shifokorlar va sportchilar shunday hisoblaydi.', '<b>Питание.</b> Если на завтрак должно приходиться 25% от 2000 ккал в день, завтрак — 500 ккал. Так считают врачи и спортсмены.', '<b>Nutrition.</b> If breakfast should provide 25% of a daily 2000 kcal, it should be 500 kcal. Doctors and athletes calculate this way.'),
      L('<b>Qishloq xo‘jaligi.</b> Paxta chigitidan taxminan 20% yog‘ olinadi. 5 tonna chigitdan 5000 : 100 · 20 = 1000 kg paxta yog‘i chiqadi.', '<b>Сельское хозяйство.</b> Из хлопковых семян получают около 20% масла. Из 5 тонн семян выйдет 5000 : 100 · 20 = 1000 кг хлопкового масла.', '<b>Farming.</b> Cotton seed yields about 20% oil. 5 tonnes of seed give 5000 : 100 · 20 = 1000 kg of cottonseed oil.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('Hiyla: <b>a ning b% i = b ning a% i</b>. 8 ning 50% i = 50 ning 8% i = 4. Shuning uchun 25 ning 16% ini topish qiyin tuyulsa, 16 ning 25% ini — choragini oling: 4!', 'Хитрость: <b>a% от b = b% от a</b>. 50% от 8 = 8% от 50 = 4. Поэтому если трудно найти 16% от 25, найдите 25% от 16 — четверть: 4!', 'A trick: <b>a% of b = b% of a</b>. 50% of 8 = 8% of 50 = 4. So if 16% of 25 looks hard, find 25% of 16 — a quarter: 4!'),
      L('O‘zbekiston aholisining qariyb yarmi 30 yoshgacha bo‘lgan yoshlar. Mamlakat aholisi 37 milliondan oshgan, demak yoshlar soni taxminan 18 million atrofida.', 'Почти половина населения Узбекистана — молодёжь до 30 лет. Население страны превысило 37 миллионов, значит, молодых людей около 18 миллионов.', 'Almost half of Uzbekistan’s population is under 30. With over 37 million people, that is roughly 18 million young people.')
    ] },
    { kind: 'practice', h: L('O‘zingiz yeching', 'Решите сами', 'Try it yourself'), list: [
      L('500 ning 8% i?', '8% от 500?', '8% of 500?'),
      L('Sinfdagi 30 o‘quvchining 60% i sport bilan shug‘ullanadi. Nechta?', '60% из 30 учеников класса занимаются спортом. Сколько?', '60% of the 30 pupils in a class do sport. How many?'),
      L('32 ning 25% ini ikki usulda toping.', 'Найдите 25% от 32 двумя способами.', 'Find 25% of 32 in two ways.'),
      L('Qaysi biri katta: 300 ning 20% i yoki 200 ning 30% i?', 'Что больше: 20% от 300 или 30% от 200?', 'Which is bigger: 20% of 300 or 30% of 200?')
    ], after: [
      L('Javoblar: 40; 18 nafar; 32 : 4 = 8 va 0,32 · 25 = 8; teng — ikkalasi 60.', 'Ответы: 40; 18 учеников; 32 : 4 = 8 и 0,32 · 25 = 8; равны — оба 60.', 'Answers: 40; 18 pupils; 32 : 4 = 8 and 0.32 · 25 = 8; equal, both 60.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('N ning p% i = N : 100 · p (yoki N · 0,0p).', 'p% от N = N : 100 · p (или N · 0,0p).', 'p% of N = N : 100 · p (or N times the decimal).'),
      L('Avval 1% ni toping, keyin ko‘paytiring.', 'Сначала найдите 1%, потом умножайте.', 'Find 1% first, then multiply.'),
      L('Qulay foizlar: 50% — yarmi, 25% — chorak, 10% — o‘ndan biri.', 'Удобные проценты: 50% — половина, 25% — четверть, 10% — десятая часть.', 'Handy percentages: 50% half, 25% a quarter, 10% a tenth.'),
      L('Murakkab foizni qulaylarga ajrating: 15% = 10% + 5%.', 'Сложный процент раскладывайте на удобные: 15% = 10% + 5%.', 'Split awkward percentages: 15% = 10% + 5%.'),
      L('Butunni to‘g‘ri aniqlang — «nimaning foizi?»', 'Правильно определяйте целое — «процент от чего?»', 'Identify the whole — “a percentage of what?”'),
      L('p &lt; 100 bo‘lsa, qism butundan kichik.', 'Если p &lt; 100, часть меньше целого.', 'If p &lt; 100, the part is smaller than the whole.')
    ] }
  ] });
})(this);
(function (root) { 'use strict'; var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '5-2';

  // ---------- t9. QQS, chegirma va omonat foizi ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Pul va foizlar', 'Деньги и проценты', 'Money and percentages'), p: [
      L('Do‘konda «Barcha kiyimlarga 20% chegirma!» degan e’lon. Chekda «shu jumladan QQS 12%» degan satr. Bank reklamasi: «Omonatingizga yillik 18%!». Bu uch holatning hammasida foizlar pulga aylanadi. Ularni tushunadigan odam aqlli xarid qiladi, aldanmaydi va pulini ko‘paytirishni biladi.', 'В магазине объявление: «Скидка 20% на всю одежду!». В чеке строка «в том числе НДС 12%». Реклама банка: «18% годовых по вашему вкладу!». Во всех трёх случаях проценты превращаются в деньги. Тот, кто их понимает, покупает разумно, не даёт себя обмануть и умеет приумножать деньги.', 'A shop sign says “20% off all clothes!”. A receipt has a line “including VAT 12%”. A bank advert says “18% a year on your deposit!”. In all three cases percentages turn into money. Someone who understands them shops wisely, is not fooled and knows how to make money grow.'),
      L('Bu mavzuda uchta muhim moliyaviy tushunchani o‘rganamiz: <b>chegirma</b> (narxning kamayishi), <b>QQS</b> (narxga qo‘shiladigan soliq) va <b>omonat foizi</b> (bankdagi pulning o‘sishi). Uchalasida ham o‘tgan mavzudagi «miqdorning foizini topish» ko‘nikmasi ishlaydi.', 'В этой теме изучим три важных финансовых понятия: <b>скидку</b> (уменьшение цены), <b>НДС</b> (налог, добавляемый к цене) и <b>процент по вкладу</b> (рост денег в банке). Во всех трёх работает навык прошлой темы — «найти процент от величины».', 'In this topic we study three important money ideas: the <b>discount</b> (a price cut), <b>VAT</b> (a tax added to the price) and <b>savings interest</b> (money growing in a bank). All three use the skill from the last topic, finding a percentage of an amount.'),
      L('Bunday bilim faqat kattalar uchun emas: cho‘ntak pulingizni rejalashtirish, sovg‘a uchun pul yig‘ish yoki ikki do‘kondagi narxlarni solishtirish ham shu hisoblarga tayanadi.', 'Такие знания нужны не только взрослым: планирование карманных денег, накопление на подарок или сравнение цен в двух магазинах — всё опирается на эти расчёты.', 'This knowledge is not only for adults: planning your pocket money, saving for a present or comparing prices in two shops all rely on these calculations.')
    ] },
    { kind: 'def', h: L('Uch atama', 'Три термина', 'Three terms'), list: [
      L('<b>Chegirma</b> — tovar narxining kamaytirilishi. «20% chegirma» — narxning 20% i olib tashlanadi, xaridor 80% ini to‘laydi.', '<b>Скидка</b> — уменьшение цены товара. «Скидка 20%» — из цены убирают 20%, покупатель платит 80%.', 'A <b>discount</b> is a reduction in price. “20% off” means 20% of the price is removed and the buyer pays 80%.'),
      L('<b>QQS</b> (qo‘shilgan qiymat solig‘i) — davlatga to‘lanadigan soliq, u tovar narxiga qo‘shiladi. O‘zbekistonda QQS stavkasi hozir <b>12%</b>. Xaridor tovar narxining 112% ini to‘laydi.', '<b>НДС</b> (налог на добавленную стоимость) — налог в пользу государства, он прибавляется к цене товара. В Узбекистане ставка НДС сейчас <b>12%</b>. Покупатель платит 112% от цены товара.', '<b>VAT</b> (value added tax) is a tax paid to the state and added to the price. In Uzbekistan the VAT rate is currently <b>12%</b>. The buyer pays 112% of the price before tax.'),
      L('<b>Omonat</b> — bankka saqlashga qo‘yilgan pul. <b>Yillik foiz</b> — bank bir yilda omonat summasining necha foizini qo‘shib berishi. 1 000 000 so‘m yillik 20% bilan — yil oxirida 200 000 so‘m foyda.', '<b>Вклад</b> — деньги, положенные в банк на хранение. <b>Годовой процент</b> — сколько процентов от суммы вклада банк добавит за год. 1 000 000 сум под 20% годовых — за год доход 200 000 сум.', 'A <b>deposit</b> is money placed in a bank for safekeeping. The <b>annual interest rate</b> is the percentage of the deposit the bank adds in a year. 1 000 000 sum at 20% a year earns 200 000 sum in a year.')
    ], after: [
      L('E’tibor bering: chegirmada narx <b>kamayadi</b>, QQS va omonat foizida esa miqdor <b>oshadi</b>. Har uchala holatda butun — boshlang‘ich summa (eski narx, soliqsiz narx, omonat summasi).', 'Обратите внимание: при скидке цена <b>уменьшается</b>, а при НДС и проценте по вкладу сумма <b>растёт</b>. Во всех трёх случаях целое — исходная сумма (старая цена, цена без налога, сумма вклада).', 'Notice: with a discount the price <b>falls</b>, while with VAT and interest the amount <b>rises</b>. In all three cases the whole is the starting amount (old price, price before tax, sum deposited).')
    ] },
    { kind: 'history', h: L('Soliqlar, banklar va bozorlar', 'Налоги, банки и базары', 'Taxes, banks and bazaars'), p: [
      L('Soliqlar qadimdan bor. Qadimgi Misrda fir’avnlar hosilning bir qismini soliq sifatida olgan. Amir Temur davlatida savdogarlardan olinadigan boj aniq qoidalar bilan belgilangan va karvon yo‘llari xavfsizligi shu mablag‘ hisobidan ta’minlangan.', 'Налоги существуют с древности. В Древнем Египте фараоны забирали часть урожая в качестве налога. В государстве Амира Темура пошлины с купцов устанавливались чёткими правилами, и на эти средства обеспечивалась безопасность караванных путей.', 'Taxes are ancient. In Egypt the pharaohs took part of the harvest as tax. In Amir Temur’s state the duties paid by merchants were fixed by clear rules, and the money kept the caravan routes safe.'),
      L('Zamonaviy banklarning ajdodlari O‘rta asr Italiyasida paydo bo‘ldi: pul almashtiruvchilar «banco» — skameykada o‘tirib ishlagan. «Bank» so‘zi shundan kelib chiqqan. Ular omonatlarni saqlab, qarz berib, foiz hisoblashgan.', 'Предки современных банков появились в средневековой Италии: менялы работали, сидя на скамье — «banco». Отсюда слово «банк». Они хранили вклады, давали в долг и начисляли проценты.', 'The ancestors of modern banks appeared in medieval Italy: money changers worked sitting at a bench, a “banco”. That is where the word “bank” comes from. They kept deposits, lent money and charged interest.'),
      L('Qo‘shilgan qiymat solig‘ini 1954-yilda fransuz moliyachisi <b>Moris Lore</b> taklif qilgan. Hozir u dunyoning 170 dan ortiq mamlakatida amal qiladi. O‘zbekistonda QQS 2023-yildan boshlab 12% qilib belgilangan.', 'Налог на добавленную стоимость в 1954 году предложил французский финансист <b>Морис Лоре</b>. Сейчас он действует более чем в 170 странах мира. В Узбекистане с 2023 года ставка НДС — 12%.', 'Value added tax was proposed in 1954 by the French official <b>Maurice Lauré</b>. Today it is used in more than 170 countries. In Uzbekistan the VAT rate has been 12% since 2023.')
    ] },
    { kind: 'rule', h: L('Formulalar', 'Формулы', 'Formulas'), list: [
      L('<b>Chegirma:</b> chegirma miqdori = narx : 100 · p; yangi narx = narx − chegirma. Yoki tezroq: yangi narx = narx : 100 · (100 − p).', '<b>Скидка:</b> размер скидки = цена : 100 · p; новая цена = цена − скидка. Или быстрее: новая цена = цена : 100 · (100 − p).', '<b>Discount:</b> discount = price : 100 · p; new price = price − discount. Or faster: new price = price : 100 · (100 − p).'),
      L('<b>QQS:</b> QQS miqdori = narx : 100 · 12; to‘lanadigan narx = narx + QQS = narx : 100 · 112.', '<b>НДС:</b> сумма НДС = цена : 100 · 12; цена к оплате = цена + НДС = цена : 100 · 112.', '<b>VAT:</b> VAT = price : 100 · 12; price to pay = price + VAT = price : 100 · 112.'),
      L('<b>Omonat (bir yil):</b> foyda = summa : 100 · p; yil oxirida hisobda = summa + foyda.', '<b>Вклад (один год):</b> доход = сумма : 100 · p; на счёте через год = сумма + доход.', '<b>Deposit (one year):</b> interest = sum : 100 · p; balance after a year = sum + interest.')
    ], after: [
      L('Chegirmaning tezkor yo‘li: 20% chegirma bo‘lsa, siz narxning 80% ini to‘laysiz. 200 000 ning 80% i: 2000 · 80 = 160 000. Bitta amal — tayyor javob.', 'Быстрый путь для скидки: при скидке 20% вы платите 80% цены. 80% от 200 000: 2000 · 80 = 160 000. Одно действие — готовый ответ.', 'The quick route for discounts: with 20% off you pay 80% of the price. 80% of 200 000: 2000 · 80 = 160 000. One step and you are done.'),
      L('Ikki yil davomida omonat qolsa, ikkinchi yilda foiz yangi, kattalashgan summaga hisoblanadi. Bu «murakkab foiz» deyiladi va pulni tez o‘stiradi. Uni yuqori sinflarda batafsil o‘rganasiz.', 'Если вклад лежит два года, во второй год процент начисляется на новую, увеличенную сумму. Это называется «сложный процент», и он быстро растит деньги. Его подробно изучают в старших классах.', 'If a deposit stays two years, in the second year interest is paid on the new, larger sum. This is called “compound interest” and it makes money grow fast. You will study it in detail in later grades.')
    ] },
    { kind: 'steps', h: L('Chegirmali narxni topish', 'Как найти цену со скидкой', 'Finding a sale price'), p: [
      L('Krossovka 350 000 so‘m, chegirma 30%.', 'Кроссовки стоят 350 000 сум, скидка 30%.', 'Trainers cost 350 000 sum with 30% off.')
    ], list: [
      L('1-qadam. 1% ni toping: 350 000 : 100 = 3500.', 'Шаг 1. Найдите 1%: 350 000 : 100 = 3500.', 'Step 1. Find 1%: 350 000 : 100 = 3500.'),
      L('2-qadam. Chegirma miqdori: 3500 · 30 = 105 000 so‘m.', 'Шаг 2. Размер скидки: 3500 · 30 = 105 000 сум.', 'Step 2. The discount: 3500 · 30 = 105 000 sum.'),
      L('3-qadam. Yangi narx: 350 000 − 105 000 = 245 000 so‘m.', 'Шаг 3. Новая цена: 350 000 − 105 000 = 245 000 сум.', 'Step 3. New price: 350 000 − 105 000 = 245 000 sum.'),
      L('4-qadam. Tekshiruv: 100% − 30% = 70%; 3500 · 70 = 245 000. Mos!', 'Шаг 4. Проверка: 100% − 30% = 70%; 3500 · 70 = 245 000. Совпадает!', 'Step 4. Check: 100% − 30% = 70%; 3500 · 70 = 245 000. It matches!')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir namunada avval butunni (boshlang‘ich summani) aniqlaymiz, keyin foizni topamiz va oxirida summa kamayadimi yoki oshadimi — shunga qarab ayiramiz yoki qo‘shamiz.', 'В каждом примере сначала определяем целое (исходную сумму), затем находим процент и в конце вычитаем или прибавляем — в зависимости от того, уменьшается сумма или растёт.', 'In each example we first identify the whole (the starting amount), then find the percentage, and finally subtract or add depending on whether the amount shrinks or grows.')
    ], ex: [
      { q: L('Ko‘ylak 200 000 so‘m, 20% chegirma. Qancha to‘laymiz?', 'Рубашка стоит 200 000 сум, скидка 20%. Сколько платим?', 'A shirt costs 200 000 sum with 20% off. How much do we pay?'), s: L('Chegirma: 200 000 : 100 · 20 = 40 000. Narx: 200 000 − 40 000 = <b>160 000 so‘m</b>.', 'Скидка: 200 000 : 100 · 20 = 40 000. Цена: 200 000 − 40 000 = <b>160 000 сум</b>.', 'Discount: 200 000 : 100 · 20 = 40 000. Price: 200 000 − 40 000 = <b>160 000 sum</b>.') },
      { q: L('Tovar narxi QQSsiz 450 000 so‘m. QQS 12%. QQS miqdori va to‘liq narx?', 'Цена товара без НДС — 450 000 сум. НДС 12%. Сумма НДС и полная цена?', 'An item costs 450 000 sum before VAT. VAT is 12%. How much VAT, and the full price?'), s: L('QQS: 4500 · 12 = 54 000 so‘m. To‘liq narx: 450 000 + 54 000 = <b>504 000 so‘m</b>.', 'НДС: 4500 · 12 = 54 000 сум. Полная цена: 450 000 + 54 000 = <b>504 000 сум</b>.', 'VAT: 4500 · 12 = 54 000 sum. Full price: 450 000 + 54 000 = <b>504 000 sum</b>.') },
      { q: L('Bankka 2 000 000 so‘m yillik 15% bilan qo‘yildi. Bir yildan keyin hisobda qancha bo‘ladi?', 'В банк положили 2 000 000 сум под 15% годовых. Сколько будет на счёте через год?', '2 000 000 sum is deposited at 15% a year. What is the balance after one year?'), s: L('Foyda: 20 000 · 15 = 300 000. Hisobda: 2 000 000 + 300 000 = <b>2 300 000 so‘m</b>.', 'Доход: 20 000 · 15 = 300 000. На счёте: 2 000 000 + 300 000 = <b>2 300 000 сум</b>.', 'Interest: 20 000 · 15 = 300 000. Balance: 2 000 000 + 300 000 = <b>2 300 000 sum</b>.') },
      { q: L('Qaysi biri arzon: 120 000 so‘mlik sumka 25% chegirma bilan yoki 100 000 so‘mlik sumka 10% chegirma bilan?', 'Что дешевле: сумка за 120 000 сум со скидкой 25% или сумка за 100 000 сум со скидкой 10%?', 'Which is cheaper: a 120 000 sum bag at 25% off or a 100 000 sum bag at 10% off?'), s: L('Birinchisi: 120 000 ning 75% i = 90 000. Ikkinchisi: 100 000 ning 90% i = 90 000. Javob: <b>narxlari teng</b> — katta chegirma har doim ham arzonroq degani emas!', 'Первая: 75% от 120 000 = 90 000. Вторая: 90% от 100 000 = 90 000. Ответ: <b>цены равны</b> — большая скидка не всегда значит дешевле!', 'First: 75% of 120 000 = 90 000. Second: 90% of 100 000 = 90 000. Answer: <b>the prices are equal</b> — a bigger discount does not always mean cheaper!') }
    ] },
    { kind: 'table', h: L('500 000 so‘mlik tovar', 'Товар за 500 000 сум', 'An item costing 500 000 sum'), table: { head: [L('Holat', 'Ситуация', 'Situation'), L('Foiz miqdori', 'Сумма процента', 'Percentage amount'), L('Yakuniy summa', 'Итоговая сумма', 'Final amount')], rows: [
      [L('10% chegirma', 'Скидка 10%', '10% off'), '50 000', '450 000'],
      [L('25% chegirma', 'Скидка 25%', '25% off'), '125 000', '375 000'],
      [L('50% chegirma', 'Скидка 50%', '50% off'), '250 000', '250 000'],
      [L('QQS 12%', 'НДС 12%', 'VAT 12%'), '60 000', '560 000'],
      [L('Omonat, yillik 20%', 'Вклад, 20% годовых', 'Deposit, 20% a year'), '100 000', '600 000']
    ] }, after: [
      L('Jadvaldan ko‘rinadiki, bir xil foizlar summa uchun turlicha ta’sir qiladi: chegirma summani kamaytiradi, soliq va omonat foizi esa oshiradi.', 'Из таблицы видно, что проценты действуют на сумму по-разному: скидка уменьшает сумму, а налог и процент по вкладу увеличивают.', 'The table shows that percentages act on the amount in different ways: a discount reduces it, while tax and interest increase it.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Chegirmani narx deb yozish.</b> 200 000 ga 20% chegirma — javob 40 000 emas! 40 000 — chegirma miqdori, narx esa 160 000.', '<b>Записать скидку вместо цены.</b> Скидка 20% на 200 000 — ответ не 40 000! 40 000 — размер скидки, а цена — 160 000.', '<b>Giving the discount instead of the price.</b> 20% off 200 000: the answer is not 40 000! That is the discount; the price is 160 000.'),
      L('<b>Foizni pul kabi ayirish.</b> 200 000 − 20 = 199 980 — bema’ni. Avval 20% ni so‘mga aylantiring.', '<b>Вычитать процент как деньги.</b> 200 000 − 20 = 199 980 — бессмыслица. Сначала переведите 20% в сумы.', '<b>Subtracting the percentage as money.</b> 200 000 − 20 = 199 980 is nonsense. First turn 20% into sum.'),
      L('<b>Ikki chegirmani qo‘shish.</b> Avval 20%, keyin yana 10% chegirma — bu 30% emas! Ikkinchi chegirma yangi narxdan hisoblanadi: 100 000 → 80 000 → 72 000, ya’ni jami 28%.', '<b>Складывать две скидки.</b> Сначала 20%, потом ещё 10% — это не 30%! Вторая скидка считается от новой цены: 100 000 → 80 000 → 72 000, то есть всего 28%.', '<b>Adding two discounts.</b> 20% off then a further 10% off is not 30%! The second is taken from the new price: 100 000 → 80 000 → 72 000, so 28% in total.'),
      L('<b>Omonatda faqat foydani yozish.</b> «Hisobda qancha?» deb so‘ralsa, foydani boshlang‘ich summaga qo‘shish kerak.', '<b>Записать только доход по вкладу.</b> Если спрашивают «сколько на счёте?», доход нужно прибавить к исходной сумме.', '<b>Giving only the interest.</b> If asked “what is the balance?”, add the interest to the starting sum.')
    ] },
    { kind: 'life', h: L('Aqlli xaridor', 'Разумный покупатель', 'A smart shopper'), p: [
      L('<b>Chegirma tuzog‘i.</b> Ba’zi do‘konlar avval narxni ko‘tarib, keyin «50% chegirma» yozadi. Aqlli xaridor chegirma foiziga emas, yakuniy narxga qaraydi va uni boshqa do‘konlar bilan solishtiradi.', '<b>Ловушка скидок.</b> Некоторые магазины сначала поднимают цену, а потом пишут «скидка 50%». Разумный покупатель смотрит не на процент скидки, а на итоговую цену и сравнивает её с другими магазинами.', '<b>The discount trap.</b> Some shops raise a price first and then advertise “50% off”. A smart shopper looks not at the discount percentage but at the final price, and compares it with other shops.'),
      L('<b>Chekni o‘qing.</b> O‘zbekistonda chekda QQS alohida qatorda ko‘rsatiladi. 112 000 so‘mlik xaridda QQS 12 000 so‘m: 100 000 — tovar, 12 000 — davlatga soliq. Bu pul maktablar, kasalxonalar va yo‘llar qurilishiga sarflanadi.', '<b>Читайте чек.</b> В Узбекистане НДС указывается в чеке отдельной строкой. В покупке на 112 000 сум НДС — 12 000: 100 000 — товар, 12 000 — налог государству. Эти деньги идут на школы, больницы и дороги.', '<b>Read the receipt.</b> In Uzbekistan VAT is shown on a separate line. In a 112 000 sum purchase the VAT is 12 000: 100 000 for the goods and 12 000 tax for the state, which pays for schools, hospitals and roads.'),
      L('<b>Jamg‘arma.</b> Har oy 50 000 so‘m yig‘ib, yil oxirida 600 000 so‘mni bankka yillik 20% bilan qo‘ysangiz, keyingi yil 120 000 so‘m qo‘shimcha daromad olasiz — pul o‘zi ishlaydi!', '<b>Накопления.</b> Если каждый месяц откладывать 50 000 сум, а в конце года положить 600 000 в банк под 20% годовых, через год получите ещё 120 000 сум — деньги работают сами!', '<b>Saving.</b> Put aside 50 000 sum a month, then bank the 600 000 at 20% a year, and next year you earn an extra 120 000 sum — the money works for you!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Interesting facts'), p: [
      L('Albert Eynshteynga nisbat beriladigan bir gap bor: «Murakkab foiz — dunyoning sakkizinchi mo‘jizasi». U haqiqatan aytganmi — aniq emas, lekin g‘oya to‘g‘ri: yillik 10% bilan pul taxminan 7 yilda ikki baravar oshadi.', 'Альберту Эйнштейну приписывают фразу: «Сложный процент — восьмое чудо света». Говорил ли он это на самом деле — неизвестно, но идея верна: под 10% годовых деньги удваиваются примерно за 7 лет.', 'A saying is often attributed to Albert Einstein: “Compound interest is the eighth wonder of the world.” Whether he really said it is unclear, but the idea holds: at 10% a year money roughly doubles in 7 years.'),
      L('Dunyodagi eng katta chegirma kunlaridan biri — Xitoydagi «Yolg‘izlar kuni» (11-noyabr). Bir kunda onlayn do‘konlar o‘nlab milliard dollarlik tovar sotadi.', 'Один из крупнейших дней скидок в мире — «День холостяков» в Китае (11 ноября). За один день интернет-магазины продают товаров на десятки миллиардов долларов.', 'One of the biggest sale days in the world is China’s “Singles’ Day” on 11 November. Online shops sell tens of billions of dollars of goods in a single day.')
    ] },
    { kind: 'practice', h: L('O‘zingiz yeching', 'Решите сами', 'Try it yourself'), list: [
      L('Velosiped 1 500 000 so‘m, chegirma 15%. Yangi narx?', 'Велосипед стоит 1 500 000 сум, скидка 15%. Новая цена?', 'A bicycle costs 1 500 000 sum, 15% off. New price?'),
      L('QQSsiz narx 80 000 so‘m. QQS bilan narx?', 'Цена без НДС — 80 000 сум. Цена с НДС?', 'Price before VAT: 80 000 sum. Price with VAT?'),
      L('500 000 so‘m yillik 22% bilan omonatga qo‘yildi. Bir yillik foyda?', '500 000 сум положили под 22% годовых. Доход за год?', '500 000 sum is saved at 22% a year. Interest for one year?')
    ], after: [
      L('Javoblar: 1 275 000 so‘m; 89 600 so‘m; 110 000 so‘m.', 'Ответы: 1 275 000 сум; 89 600 сум; 110 000 сум.', 'Answers: 1 275 000 sum; 89 600 sum; 110 000 sum.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Chegirma narxni kamaytiradi: yangi narx = narxning (100 − p)% i.', 'Скидка уменьшает цену: новая цена = (100 − p)% от цены.', 'A discount lowers the price: new price = (100 − p)% of the price.'),
      L('QQS (12%) narxga qo‘shiladi: to‘liq narx = narxning 112% i.', 'НДС (12%) прибавляется к цене: полная цена = 112% от цены.', 'VAT (12%) is added: full price = 112% of the price.'),
      L('Omonat: bir yillik foyda = summaning p% i; hisobda = summa + foyda.', 'Вклад: доход за год = p% от суммы; на счёте = сумма + доход.', 'Deposit: a year’s interest = p% of the sum; balance = sum + interest.'),
      L('Butun — har doim boshlang‘ich summa.', 'Целое — всегда исходная сумма.', 'The whole is always the starting amount.'),
      L('Ketma-ket chegirmalar qo‘shilmaydi.', 'Последовательные скидки не складываются.', 'Successive discounts do not simply add up.'),
      L('Foiz miqdorini yakuniy summa bilan adashtirmang.', 'Не путайте сумму процента с итоговой суммой.', 'Do not confuse the percentage amount with the final amount.')
    ] }
  ] });

  // ---------- t10. O‘rtacha qiymat tushunchasi ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Teng bo‘lib chiqsak...', 'Если разделить поровну...', 'If we shared equally...'), p: [
      L('Uch do‘st yong‘oq terdi: Aziz 12 ta, Bobur 20 ta, Dilshod 16 ta. Ular yong‘oqlarni teng bo‘lishga kelishdi. Hammasini bir joyga yig‘ishdi: 12 + 20 + 16 = 48 ta. Uchga bo‘lishdi: 48 : 3 = 16 tadan. Har biriga 16 ta tegdi. Ana shu 16 — terilgan yong‘oqlarning <b>o‘rtacha</b> soni.', 'Три друга собирали орехи: Азиз — 12, Бобур — 20, Дильшод — 16. Они договорились разделить орехи поровну. Сложили всё вместе: 12 + 20 + 16 = 48. Разделили на троих: 48 : 3 = 16. Каждому досталось по 16. Это 16 — <b>среднее</b> число собранных орехов.', 'Three friends gathered walnuts: Aziz 12, Bobur 20 and Dilshod 16. They agreed to share them equally. They put them all together: 12 + 20 + 16 = 48, and divided by three: 48 : 3 = 16 each. That 16 is the <b>average</b> number of walnuts gathered.'),
      L('O‘rtacha qiymat — ko‘p sonlarni bitta son bilan ifodalashning eng mashhur usuli. Ob-havo xabarida «o‘rtacha harorat», maktabda «o‘rtacha baho», sportda «o‘yin boshiga o‘rtacha gol» — hammasi shu tushuncha.', 'Среднее значение — самый известный способ выразить много чисел одним числом. «Средняя температура» в прогнозе погоды, «средний балл» в школе, «в среднем голов за игру» в спорте — всё это одно и то же понятие.', 'The average is the best-known way of summing up many numbers with a single one. “Average temperature” in the forecast, “average mark” at school, “average goals per game” in sport — all are the same idea.'),
      L('Bu mavzuda o‘rtacha qiymatni topishni, uning ma’nosini va qachon u foydali, qachon esa aldamchi bo‘lishini o‘rganamiz.', 'В этой теме научимся находить среднее, поймём его смысл и узнаем, когда оно полезно, а когда может ввести в заблуждение.', 'In this topic we learn to find an average, understand what it means, and see when it is helpful and when it can mislead.')
    ] },
    { kind: 'def', h: L('O‘rtacha arifmetik', 'Среднее арифметическое', 'The arithmetic mean'), p: [
      L('Bir nechta sonning <b>o‘rtacha arifmetigi</b> (o‘rtacha qiymati) — bu sonlar yig‘indisining ularning soniga bo‘linmasi.', '<b>Средним арифметическим</b> (средним значением) нескольких чисел называется частное от деления их суммы на их количество.', 'The <b>arithmetic mean</b> (average) of several numbers is their sum divided by how many numbers there are.'),
      L('Ma’nosi: agar barcha qiymatlarni «tenglashtirsak», ya’ni kattalaridan olib kichiklariga bersak, har biri o‘rtacha qiymatga teng bo‘lib qoladi. Kub minoralarini tasavvur qiling: 3, 5 va 4 kubli ustunlar. Eng balandidan bitta kubni eng pastiga o‘tkazsak — 4, 4, 4. O‘rtacha — 4.', 'Смысл: если все значения «выровнять», то есть взять у больших и отдать меньшим, каждое станет равно среднему. Представьте башни из кубиков: столбики из 3, 5 и 4 кубиков. Переложим один кубик с самого высокого на самый низкий — получится 4, 4, 4. Среднее — 4.', 'The meaning: if we “level out” the values, taking from the big ones and giving to the small ones, each becomes equal to the average. Imagine towers of 3, 5 and 4 cubes. Move one cube from the tallest to the shortest and you get 4, 4, 4. The average is 4.')
    ], list: [
      L('O‘rtacha qiymat har doim eng kichik va eng katta qiymat <b>orasida</b> bo‘ladi.', 'Среднее всегда находится <b>между</b> наименьшим и наибольшим значением.', 'The average always lies <b>between</b> the smallest and largest values.'),
      L('Agar barcha sonlar teng bo‘lsa, o‘rtacha ham shu songa teng.', 'Если все числа равны, среднее равно этому числу.', 'If all the numbers are equal, the average equals that number.'),
      L('O‘rtacha butun son bo‘lmasligi mumkin: 1, 2 ning o‘rtachasi 1,5.', 'Среднее может быть нецелым: среднее 1 и 2 равно 1,5.', 'The average need not be a whole number: the average of 1 and 2 is 1.5.')
    ] },
    { kind: 'history', h: L('O‘rtacha qiymat tarixidan', 'Из истории среднего', 'A history of the average'), p: [
      L('Qadimgi yunon olimlari, xususan, Pifagor maktabi vakillari bir necha xil «o‘rtacha»larni o‘rganishgan: arifmetik, geometrik va garmonik. Ular buni musiqa va me’morchilikdagi uyg‘unlikni tushuntirishda ishlatgan.', 'Древнегреческие учёные, в частности последователи Пифагора, изучали несколько видов «средних»: арифметическое, геометрическое и гармоническое. Они использовали их, чтобы объяснить гармонию в музыке и архитектуре.', 'Ancient Greek scholars, especially the followers of Pythagoras, studied several kinds of “mean”: arithmetic, geometric and harmonic. They used them to explain harmony in music and architecture.'),
      L('<b>Beruniy</b> va Ulug‘bek rasadxonasi astronomlari yulduzlar o‘rnini ko‘p marta o‘lchab, natijalarni o‘rtachalashtirish orqali xatolarni kamaytirishgan. Ulug‘bekning «Ziji Ko‘ragoniy» jadvalidagi 1018 ta yulduz koordinatalari o‘z davrining eng aniq ma’lumotlari edi.', '<b>Беруни</b> и астрономы обсерватории Улугбека многократно измеряли положение звёзд и уменьшали ошибки, усредняя результаты. Координаты 1018 звёзд в таблицах Улугбека «Зидж-и Гурагани» были самыми точными для своего времени.', '<b>Biruni</b> and the astronomers of Ulugh Beg’s observatory measured star positions many times and reduced errors by averaging the results. The coordinates of 1018 stars in Ulugh Beg’s “Zij-i Gurgani” tables were the most accurate of their time.'),
      L('XIX asrda belgiyalik olim <b>Adolf Ketle</b> «o‘rtacha odam» g‘oyasini ilgari surdi: minglab odamlarning bo‘yi va vaznini o‘lchab, o‘rtacha qiymatlarni hisobladi. Zamonaviy statistika shundan boshlangan.', 'В XIX веке бельгийский учёный <b>Адольф Кетле</b> выдвинул идею «среднего человека»: измерив рост и вес тысяч людей, он вычислил средние значения. С этого началась современная статистика.', 'In the 19th century the Belgian scientist <b>Adolphe Quetelet</b> put forward the idea of the “average man”: he measured the height and weight of thousands of people and computed the averages. Modern statistics began there.')
    ] },
    { kind: 'rule', h: L('Formula', 'Формула', 'The formula'), p: [
      L('<b>O‘rtacha = yig‘indi : soni</b>', '<b>Среднее = сумма : количество</b>', '<b>Average = sum : count</b>'),
      L('a, b va c sonlarining o‘rtachasi: (a + b + c) : 3. To‘rtta sonniki: (a + b + c + d) : 4. Qavslar muhim: avval hamma sonlarni qo‘shamiz, keyin bo‘lamiz!', 'Среднее чисел a, b и c: (a + b + c) : 3. Четырёх чисел: (a + b + c + d) : 4. Скобки важны: сначала складываем все числа, потом делим!', 'The average of a, b and c is (a + b + c) : 3. Of four numbers: (a + b + c + d) : 4. The brackets matter: add all the numbers first, then divide!'),
      L('Sonlar soni deganda qatnashgan barcha qiymatlar, shu jumladan nollar ham tushuniladi. Agar o‘quvchi bir kun 0 bet o‘qigan bo‘lsa, bu kun ham sanaladi.', 'Количество — это число всех участвующих значений, включая нули. Если ученик в какой-то день прочёл 0 страниц, этот день тоже считается.', 'The count includes every value taking part, zeros included. If a pupil read 0 pages one day, that day still counts.')
    ] },
    { kind: 'steps', h: L('Qadamma-qadam', 'Шаг за шагом', 'Step by step'), p: [
      L('Haftaning 5 kunidagi harorat: 18°, 21°, 20°, 17°, 24°. O‘rtacha haroratni topamiz.', 'Температура за 5 дней недели: 18°, 21°, 20°, 17°, 24°. Найдём среднюю температуру.', 'Temperatures over 5 days: 18°, 21°, 20°, 17°, 24°. Let us find the average temperature.')
    ], list: [
      L('1-qadam. Barcha qiymatlarni yozib oling va sanang: 5 ta.', 'Шаг 1. Выпишите все значения и сосчитайте их: 5 штук.', 'Step 1. Write down all the values and count them: 5.'),
      L('2-qadam. Yig‘indini toping: 18 + 21 + 20 + 17 + 24 = 100.', 'Шаг 2. Найдите сумму: 18 + 21 + 20 + 17 + 24 = 100.', 'Step 2. Find the sum: 18 + 21 + 20 + 17 + 24 = 100.'),
      L('3-qadam. Soniga bo‘ling: 100 : 5 = 20.', 'Шаг 3. Разделите на количество: 100 : 5 = 20.', 'Step 3. Divide by the count: 100 : 5 = 20.'),
      L('4-qadam. Tekshiring: 20° eng kichik (17°) va eng katta (24°) qiymat orasida. Javob: o‘rtacha <b>20°</b>.', 'Шаг 4. Проверьте: 20° лежит между наименьшим (17°) и наибольшим (24°). Ответ: в среднем <b>20°</b>.', 'Step 4. Check: 20° lies between the smallest (17°) and largest (24°). Answer: an average of <b>20°</b>.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir namunada formulani qo‘llaymiz va natijani «oraliqda yotadimi?» degan savol bilan tekshiramiz. Uchinchi namunada o‘rtacha kasr son chiqadi — bu mutlaqo normal.', 'В каждом примере применяем формулу и проверяем результат вопросом «лежит ли он между крайними?». В третьем примере среднее получается дробным — это совершенно нормально.', 'In each example we apply the formula and check the result with the question “does it lie in between?”. In the third example the average is a decimal — that is perfectly normal.')
    ], ex: [
      { q: L('3, 5 va 4 ning o‘rtachasi?', 'Среднее чисел 3, 5 и 4?', 'Average of 3, 5 and 4?'), s: L('(3 + 5 + 4) : 3 = 12 : 3 = <b>4</b>.', '(3 + 5 + 4) : 3 = 12 : 3 = <b>4</b>.', '(3 + 5 + 4) : 3 = 12 : 3 = <b>4</b>.') },
      { q: L('O‘quvchining test ballari: 78, 85, 92, 65. O‘rtacha ball?', 'Баллы ученика за тесты: 78, 85, 92, 65. Средний балл?', 'A pupil’s test scores: 78, 85, 92, 65. Average score?'), s: L('Yig‘indi: 78 + 85 + 92 + 65 = 320. 320 : 4 = <b>80</b> ball.', 'Сумма: 78 + 85 + 92 + 65 = 320. 320 : 4 = <b>80</b> баллов.', 'Sum: 78 + 85 + 92 + 65 = 320. 320 : 4 = <b>80</b> points.') },
      { q: L('Uch qopning massasi: 2,5 kg, 3 kg, 4 kg. O‘rtacha massa?', 'Масса трёх мешков: 2,5 кг, 3 кг, 4 кг. Средняя масса?', 'Three sacks weigh 2.5 kg, 3 kg and 4 kg. Average mass?'), s: L('(2,5 + 3 + 4) : 3 = 9,5 : 3 ≈ <b>3,17 kg</b>. Natija 2,5 va 4 orasida — to‘g‘ri.', '(2,5 + 3 + 4) : 3 = 9,5 : 3 ≈ <b>3,17 кг</b>. Результат между 2,5 и 4 — верно.', '(2.5 + 3 + 4) : 3 = 9.5 : 3 ≈ <b>3.17 kg</b>. It lies between 2.5 and 4 — correct.') },
      { q: L('Futbol jamoasi 6 o‘yinda 2, 0, 3, 1, 4, 2 gol urdi. O‘yin boshiga o‘rtacha nechta gol?', 'Футбольная команда в 6 играх забила 2, 0, 3, 1, 4, 2 гола. Сколько в среднем голов за игру?', 'A football team scored 2, 0, 3, 1, 4, 2 goals in 6 games. Average goals per game?'), s: L('Yig‘indi: 12. Nolni ham sanaymiz — 6 ta o‘yin. 12 : 6 = <b>2 gol</b>.', 'Сумма: 12. Нуль тоже считаем — 6 игр. 12 : 6 = <b>2 гола</b>.', 'Sum: 12. The zero counts too — 6 games. 12 : 6 = <b>2 goals</b>.') }
    ] },
    { kind: 'table', h: L('Bir haftalik kuzatuv', 'Наблюдение за неделю', 'A week of observations'), p: [
      L('Malika besh kun davomida qancha bet kitob o‘qiganini yozib bordi. Jadvalning oxirgi ustunida har bir kun o‘rtachadan qanchaga ko‘p yoki kam ekani ko‘rsatilgan. Plyus — o‘rtachadan ko‘p, minus — kam.', 'Малика пять дней записывала, сколько страниц она прочитала. В последнем столбце таблицы показано, на сколько каждый день больше или меньше среднего. Плюс — больше среднего, минус — меньше.', 'Malika recorded how many pages she read over five days. The last column shows how far each day is above or below the average. Plus means above, minus means below.')
    ], table: { head: [L('Kun', 'День', 'Day'), L('O‘qilgan bet', 'Прочитано страниц', 'Pages read'), L('O‘rtachadan farqi', 'Отличие от среднего', 'Difference from average')], rows: [
      [L('Dushanba', 'Понедельник', 'Monday'), '25', '−5'],
      [L('Seshanba', 'Вторник', 'Tuesday'), '30', '0'],
      [L('Chorshanba', 'Среда', 'Wednesday'), '40', '+10'],
      [L('Payshanba', 'Четверг', 'Thursday'), '20', '−10'],
      [L('Juma', 'Пятница', 'Friday'), '35', '+5'],
      [L('Jami / o‘rtacha', 'Всего / среднее', 'Total / average'), '150 / 30', '0']
    ] }, after: [
      L('Qiziq xossa: har bir qiymatning o‘rtachadan farqlarini qo‘shsak, doim <b>nol</b> chiqadi: −5 + 0 + 10 − 10 + 5 = 0. O‘rtachadan yuqorilar pastdagilarni aynan qoplaydi — tenglashtirish g‘oyasi aynan shu.', 'Интересное свойство: если сложить отклонения всех значений от среднего, всегда получится <b>нуль</b>: −5 + 0 + 10 − 10 + 5 = 0. Превышения над средним точно покрывают недостачи — в этом и состоит идея выравнивания.', 'A neat property: add up how far each value is from the average and you always get <b>zero</b>: −5 + 0 + 10 − 10 + 5 = 0. The amounts above the average exactly cover those below — that is the levelling idea.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Noto‘g‘ri songa bo‘lish.</b> 4 ta sonni qo‘shib, 2 ga yoki 3 ga bo‘lish. Necha son qo‘shilgan bo‘lsa — shunchaga bo‘ling.', '<b>Деление не на то число.</b> Сложить 4 числа и разделить на 2 или 3. На сколько чисел сложили — на столько и делите.', '<b>Dividing by the wrong number.</b> Adding 4 numbers and dividing by 2 or 3. Divide by however many numbers you added.'),
      L('<b>Nollarni tashlab yuborish.</b> 2, 0, 3, 1, 4, 2 da nolni sanamasdan 12 : 5 = 2,4 — xato. To‘g‘risi 12 : 6 = 2.', '<b>Отбрасывать нули.</b> В ряду 2, 0, 3, 1, 4, 2 не посчитать нуль: 12 : 5 = 2,4 — ошибка. Верно: 12 : 6 = 2.', '<b>Dropping zeros.</b> Ignoring the 0 in 2, 0, 3, 1, 4, 2 gives 12 : 5 = 2.4 — wrong. Correct: 12 : 6 = 2.'),
      L('<b>Qavslarsiz hisoblash.</b> 3 + 5 + 4 : 3 = 9,33 — bo‘lish faqat oxirgi songa tegdi. Yozing: (3 + 5 + 4) : 3.', '<b>Вычисление без скобок.</b> 3 + 5 + 4 : 3 = 9,33 — деление затронуло только последнее число. Пишите: (3 + 5 + 4) : 3.', '<b>Leaving out brackets.</b> 3 + 5 + 4 : 3 = 9.33 — only the last number was divided. Write (3 + 5 + 4) : 3.'),
      L('<b>Javobni tekshirmaslik.</b> O‘rtacha eng kattadan katta yoki eng kichikdan kichik chiqsa — aniq xato bor.', '<b>Не проверять ответ.</b> Если среднее больше наибольшего или меньше наименьшего — точно есть ошибка.', '<b>Not checking.</b> If the average is above the largest or below the smallest value, there is definitely a mistake.'),
      L('<b>O‘rtachalarning o‘rtachasini olish.</b> Bir sinfda 20 o‘quvchining o‘rtacha bali 80, boshqasida 30 o‘quvchiniki 70. Ikki sinfning umumiy o‘rtachasi (80 + 70) : 2 = 75 emas! Ballar yig‘indisi 1600 + 2100 = 3700, o‘quvchilar 50 ta, o‘rtacha 3700 : 50 = 74.', '<b>Среднее от средних.</b> В одном классе у 20 учеников средний балл 80, в другом у 30 учеников — 70. Общее среднее двух классов не (80 + 70) : 2 = 75! Сумма баллов 1600 + 2100 = 3700, учеников 50, среднее 3700 : 50 = 74.', '<b>Averaging the averages.</b> One class of 20 pupils averages 80, another of 30 averages 70. The overall average is not (80 + 70) : 2 = 75! Total points 1600 + 2100 = 3700 over 50 pupils gives 3700 : 50 = 74.')
    ], after: [
      L('Xatolarning ko‘pchiligi shoshilishdan kelib chiqadi. Qiymatlarni ro‘yxat qilib yozing, ularni barmoq bilan sanang, yig‘indini ikki marta tekshiring. Eng oddiy nazorat — natija eng kichik va eng katta qiymat orasida yotishi. Agar shunday bo‘lmasa, qo‘shishda yoki sanashda xato bor. Yana bir foydali usul: natijani soniga ko‘paytiring — yig‘indi qaytib chiqishi kerak.', 'Большинство ошибок — от спешки. Выпишите значения списком, пересчитайте их, дважды проверьте сумму. Простейший контроль — результат лежит между наименьшим и наибольшим значением. Если нет, ошибка в сложении или в подсчёте. Ещё один полезный приём: умножьте результат на количество — должна вернуться сумма.', 'Most mistakes come from rushing. List the values, count them, and check the sum twice. The simplest check is that the result lies between the smallest and largest values; if not, there is an error in the adding or counting. Another useful trick: multiply the result by the count — you should get the sum back.')
    ] },
    { kind: 'life', h: L('Hayotda o‘rtacha', 'Среднее в жизни', 'Averages in life'), p: [
      L('<b>Maktab.</b> Chorak bahosi ko‘pincha joriy baholarning o‘rtachasi asosida qo‘yiladi. 5, 4, 5, 3, 5 baholarning o‘rtachasi 22 : 5 = 4,4 — yaxlitlab «4».', '<b>Школа.</b> Четвертная оценка часто выставляется по среднему из текущих оценок. Среднее оценок 5, 4, 5, 3, 5 — 22 : 5 = 4,4, после округления «4».', '<b>School.</b> A term grade is often based on the average of the marks so far. The average of 5, 4, 5, 3, 5 is 22 : 5 = 4.4, which rounds to “4”.'),
      L('<b>Ob-havo.</b> Toshkentda iyulning o‘rtacha harorati taxminan +28°, yanvarniki esa +2° atrofida. Bu ko‘p yillik kuzatuvlarning o‘rtachasi.', '<b>Погода.</b> Средняя температура июля в Ташкенте — около +28°, января — около +2°. Это средние значения многолетних наблюдений.', '<b>Weather.</b> Tashkent’s average July temperature is about +28°, January’s about +2°. These are averages over many years of observations.'),
      L('<b>Sport va o‘yin.</b> Basketbolchining «o‘yin boshiga o‘rtacha 20 ochko» degani — ba’zi o‘yinlarda 30, ba’zilarida 10 bo‘lishi mumkin, lekin umumiy hisobda 20 dan.', '<b>Спорт и игры.</b> «В среднем 20 очков за игру» у баскетболиста значит: в одних играх 30, в других 10, но в целом по 20.', '<b>Sport and games.</b> A basketball player “averaging 20 points a game” may score 30 in some games and 10 in others, but 20 overall.')
    ] },
    { kind: 'fact', h: L('O‘rtacha aldaganda', 'Когда среднее обманывает', 'When the average misleads'), p: [
      L('Hazil: «O‘rtacha chuqurligi 1 metr bo‘lgan daryoda odam cho‘kib ketdi». Daryoning ko‘p joyi 20 cm, lekin bir joyi 3 metr bo‘lishi mumkin. O‘rtacha qiymat chekka holatlarni yashiradi.', 'Шутка: «Человек утонул в реке средней глубиной 1 метр». Река в основном может быть 20 см, но в одном месте — 3 метра. Среднее скрывает крайние случаи.', 'A joke: “A man drowned in a river with an average depth of 1 metre.” Most of the river may be 20 cm deep but one spot 3 metres. The average hides the extremes.'),
      L('Agar xonada to‘rt kishi oyiga 5 million so‘mdan, bittasi 100 million so‘m topsa, «o‘rtacha daromad» 24 million chiqadi — lekin xonadagi hech kim aslida 24 million topmaydi! Shuning uchun statistikada o‘rtachadan tashqari boshqa ko‘rsatkichlar ham ishlatiladi.', 'Если в комнате четверо зарабатывают по 5 миллионов сум в месяц, а один — 100 миллионов, «средний доход» получится 24 миллиона, хотя никто в комнате столько не получает! Поэтому в статистике кроме среднего используют и другие показатели.', 'If four people in a room earn 5 million sum a month and one earns 100 million, the “average income” is 24 million — yet nobody in the room earns that! That is why statistics uses other measures besides the average.')
    ] },
    { kind: 'practice', h: L('O‘zingiz yeching', 'Решите сами', 'Try it yourself'), list: [
      L('10, 20, 30, 40 ning o‘rtachasi?', 'Среднее 10, 20, 30, 40?', 'Average of 10, 20, 30, 40?'),
      L('Bolalarning bo‘yi: 140, 145, 138, 150, 142 cm. O‘rtacha bo‘y?', 'Рост детей: 140, 145, 138, 150, 142 см. Средний рост?', 'Children’s heights: 140, 145, 138, 150, 142 cm. Average height?'),
      L('Ikki sonning o‘rtachasi 7. Biri 4. Ikkinchisi?', 'Среднее двух чисел — 7. Одно из них 4. Второе?', 'Two numbers average 7. One is 4. The other?')
    ], after: [
      L('Javoblar: 25; 715 : 5 = 143 cm; yig‘indi 14, ikkinchisi 10.', 'Ответы: 25; 715 : 5 = 143 см; сумма 14, второе число 10.', 'Answers: 25; 715 : 5 = 143 cm; the sum is 14, so the other is 10.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('O‘rtacha = yig‘indi : soni.', 'Среднее = сумма : количество.', 'Average = sum : count.'),
      L('O‘rtacha — qiymatlar tenglashtirilganda har biriga tegadigan miqdor.', 'Среднее — величина, которая достанется каждому при выравнивании.', 'The average is what each gets when the values are levelled out.'),
      L('U har doim eng kichik va eng katta qiymat orasida.', 'Оно всегда между наименьшим и наибольшим значением.', 'It always lies between the smallest and largest values.'),
      L('Nollar ham sanaladi; avval qo‘shing, keyin bo‘ling.', 'Нули тоже считаются; сначала складывайте, потом делите.', 'Zeros count; add first, then divide.'),
      L('O‘rtachadan farqlar yig‘indisi nolga teng.', 'Сумма отклонений от среднего равна нулю.', 'Differences from the average add up to zero.'),
      L('O‘rtacha chekka qiymatlarni yashirishi mumkin.', 'Среднее может скрывать крайние значения.', 'An average can hide extreme values.')
    ] }
  ] });
})(this);
